def parkhomov_excess_heat(N_clusters=2.0e18, t_hours=1.0):
    """Parkhomov Ni-H excess heat: 630 eV/cluster * N_clusters, realistic 100-300 W range [canonical: scm_vacuum_manifold.py]"""
    energy_per_cluster_j = 630 * 1.60217662e-19
    P = N_clusters * energy_per_cluster_j * _np_scm.exp(-_KAPPA_FLOAT_SCM * t_hours * 24)
    return P / 1000  # kW  (~200 W at default params)

def pons_fleischmann_excess_heat(PdD_loading=0.9, volume=1e-6):
    """Pons-Fleischmann low-radiation excess heat: loading�V�(E_phonon*scaling_factor)�Phi�buoyancy [canonical: scm_vacuum_manifold.py]"""
    P = PdD_loading * volume * (_E_PHONON_SCM * _SCALING_SCM) * _PHI_RESONANCE * 0.001 * 1e6
    return P / 1e3  # kW
