# SPECTRAL DECOMPOSITION

# -------------------------------------------------------------------------------

class SpectralDecomposition:
    """

    Spectral decomposition methods for operators and matrices.

    Implements:

        - Eigenvalue decomposition
        - Singular Value Decomposition (SVD)
        - Spectral theorem applications
        - Power spectral density
        - Fourier spectral methods
        - Operator function evaluation via spectra

    Mathematical Framework:

        For Hermitian A: A = S ?_i |?_i???_i|
        For general A: A = U S V^�  (SVD)

    Applications:

        - UQFF Hamiltonian diagonalization
        - Principal component analysis
        - Signal processing
        - Quantum state analysis

    """

    @staticmethod

    def eigendecomposition(A: np.ndarray, hermitian: bool = True) -> Dict[str, np.ndarray]:
        """
        Compute eigenvalue decomposition of matrix.
        Args:
            A: Square matrix (n�n)
            hermitian: If True, use optimized Hermitian solver
        Returns:
            Dictionary with eigenvalues, eigenvectors, and reconstruction
        """
        if hermitian:
            if SCIPY_AVAILABLE:
                from scipy.linalg import eigh
                eigenvalues, eigenvectors = eigh(A)
            else:
                eigenvalues, eigenvectors = np.linalg.eigh(A)
        else:
            if SCIPY_AVAILABLE:
                from scipy.linalg import eig
                eigenvalues, eigenvectors = eig(A)
            else:
                eigenvalues, eigenvectors = np.linalg.eig(A)
        # Sort by eigenvalue magnitude
        idx = np.argsort(np.abs(eigenvalues))[::-1]
        eigenvalues = eigenvalues[idx]
        eigenvectors = eigenvectors[:, idx]
        return {
            'eigenvalues': eigenvalues,
            'eigenvectors': eigenvectors,
            'n_eigenvalues': len(eigenvalues),
            'spectral_radius': np.max(np.abs(eigenvalues)),
            'trace': np.sum(eigenvalues),
            'determinant': np.prod(eigenvalues)
        }

    @staticmethod

    def svd(A: np.ndarray, full_matrices: bool = False) -> Dict[str, np.ndarray]:
        """
        Singular Value Decomposition: A = U S V^�
        Args:
            A: Matrix (m�n)
            full_matrices: If True, compute full U and V
        Returns:
            Dictionary with U, singular values, V^�, and diagnostics
        """
        if SCIPY_AVAILABLE:
            from scipy.linalg import svd as scipy_svd
            U, s, Vh = scipy_svd(A, full_matrices=full_matrices)
        else:
            U, s, Vh = np.linalg.svd(A, full_matrices=full_matrices)
        # Condition number
        cond = s[0] / s[-1] if s[-1] > 1e-15 else float('inf')
        # Effective rank (singular values > tolerance)
        tol = max(A.shape) * s[0] * np.finfo(float).eps
        rank = np.sum(s > tol)
        return {
            'U': U,
            'singular_values': s,
            'Vh': Vh,
            'condition_number': cond,
            'effective_rank': rank,
            'frobenius_norm': np.sqrt(np.sum(s**2)),
            'nuclear_norm': np.sum(s),
            'spectral_norm': s[0]
        }

    @staticmethod

    def low_rank_approximation(A: np.ndarray, k: int) -> np.ndarray:
        """
        Compute rank-k approximation using truncated SVD.
        A_k = S_{i=1}^k s_i u_i v_i^�
        Args:
            A: Original matrix
            k: Target rank
        Returns:
            Rank-k approximation
        """
        result = SpectralDecomposition.svd(A, full_matrices=False)
        U, s, Vh = result['U'], result['singular_values'], result['Vh']
        k = min(k, len(s))
        return U[:, :k] @ np.diag(s[:k]) @ Vh[:k, :]

    @staticmethod

    def matrix_function(A: np.ndarray, func: Callable,

                        hermitian: bool = True) -> np.ndarray:
        """
        Evaluate matrix function f(A) via spectral decomposition.
        f(A) = V f(?) V^�  where A = V ? V^�
        Args:
            A: Square matrix
            func: Scalar function to apply to eigenvalues
            hermitian: If True, assume Hermitian matrix
        Returns:
            f(A) matrix
        """
        result = SpectralDecomposition.eigendecomposition(A, hermitian)
        eigenvalues = result['eigenvalues']
        V = result['eigenvectors']
        # Apply function to eigenvalues
        f_lambda = np.array([func(lam) for lam in eigenvalues])
        # Reconstruct: f(A) = V diag(f(?)) V^�
        if hermitian:
            return V @ np.diag(f_lambda) @ V.T.conj()
        else:
            return V @ np.diag(f_lambda) @ np.linalg.inv(V)

    @staticmethod

    def matrix_exponential(A: np.ndarray, hermitian: bool = True) -> np.ndarray:
        """
        Compute matrix exponential exp(A) via spectral decomposition.
        exp(A) = V exp(?) V^�
        Useful for quantum time evolution: |?(t)? = exp(-iHt/?)|?(0)?
        """
        return SpectralDecomposition.matrix_function(A, np.exp, hermitian)

    @staticmethod

    def matrix_logarithm(A: np.ndarray, hermitian: bool = True) -> np.ndarray:
        """
        Compute matrix logarithm log(A) via spectral decomposition.
        log(A) = V log(?) V^�
        Requires positive definite matrix for real result.
        """
        return SpectralDecomposition.matrix_function(A, np.log, hermitian)

    @staticmethod

    def matrix_sqrt(A: np.ndarray, hermitian: bool = True) -> np.ndarray:
        """
        Compute matrix square root vA via spectral decomposition.
        vA = V v? V^�
        Requires positive semidefinite matrix.
        """
        return SpectralDecomposition.matrix_function(A, np.sqrt, hermitian)

    @staticmethod

    def power_spectral_density(signal: np.ndarray, fs: float = 1.0,

                                window: str = 'hann',
                                nperseg: int = None) -> Tuple[np.ndarray, np.ndarray]:
        """
        Compute power spectral density of a signal.
        PSD(f) = |FFT(signal)|� / N
        Args:
            signal: Time-domain signal
            fs: Sampling frequency (Hz)
            window: Window function ('hann', 'hamming', 'blackman', 'none')
            nperseg: Segment length for Welch method
        Returns:
            (frequencies, psd) arrays
        """
        n = len(signal)
        # Apply window
        if window == 'hann':
            w = np.hanning(n)
        elif window == 'hamming':
            w = np.hamming(n)
        elif window == 'blackman':
            w = np.blackman(n)
        else:
            w = np.ones(n)
        windowed = signal * w
        # FFT
        fft = np.fft.rfft(windowed)
        freqs = np.fft.rfftfreq(n, 1/fs)
        # Power spectral density
        psd = np.abs(fft)**2 / (fs * np.sum(w**2))
        return freqs, psd

    @staticmethod

    def fourier_spectral_derivative(f: np.ndarray, dx: float,

                                     order: int = 1) -> np.ndarray:
        """
        Compute derivative using Fourier spectral method.
        d^n f/dx^n via (ik)^n F(k) in Fourier space
        Args:
            f: Function values on uniform grid
            dx: Grid spacing
            order: Derivative order
        Returns:
            Derivative approximation on same grid
        """
        n = len(f)
        k = np.fft.fftfreq(n, dx) * 2 * np.pi
        f_hat = np.fft.fft(f)
        df_hat = (1j * k)**order * f_hat
        return np.real(np.fft.ifft(df_hat))

    @staticmethod

    def principal_components(X: np.ndarray, n_components: int = None,

                             center: bool = True) -> Dict[str, np.ndarray]:
        """
        Principal Component Analysis via SVD.
        Args:
            X: Data matrix (samples � features)
            n_components: Number of components to keep
            center: Whether to center data
        Returns:
            Dictionary with components, explained variance, projections
        """
        if center:
            X_centered = X - np.mean(X, axis=0)
        else:
            X_centered = X
        # SVD
        result = SpectralDecomposition.svd(X_centered)
        # Singular values to variance
        n_samples = X.shape[0]
        explained_variance = result['singular_values']**2 / (n_samples - 1)
        explained_variance_ratio = explained_variance / np.sum(explained_variance)
        # Principal components (rows of Vh)
        if n_components is None:
            n_components = min(X.shape)
        components = result['Vh'][:n_components]
        # Project data
        projections = X_centered @ components.T
        return {
            'components': components,
            'explained_variance': explained_variance[:n_components],
            'explained_variance_ratio': explained_variance_ratio[:n_components],
            'cumulative_variance_ratio': np.cumsum(explained_variance_ratio)[:n_components],
            'projections': projections,
            'mean': np.mean(X, axis=0) if center else np.zeros(X.shape[1])
        }

    @staticmethod

    def quantum_state_decomposition(psi: np.ndarray, 

                                     basis: np.ndarray) -> Dict[str, np.ndarray]:
        """
        Decompose quantum state in given basis.
        |?? = S c_i |f_i?
        Args:
            psi: State vector
            basis: Basis vectors (columns)
        Returns:
            Coefficients and probabilities
        """
        # Project onto basis
        coefficients = basis.T.conj() @ psi
        probabilities = np.abs(coefficients)**2
        return {
            'coefficients': coefficients,
            'probabilities': probabilities,
            'normalization': np.sum(probabilities),
            'entropy': -np.sum(probabilities * np.log(probabilities + 1e-15)),
            'dominant_state': np.argmax(probabilities),
            'dominant_amplitude': np.max(np.abs(coefficients))
        }

    def compute(self, dataset: dict = None):
        """Stub compute() for infrastructure/helper class."""
        return {}

# -------------------------------------------------------------------------------

# PARALLEL COMPUTATION (Multiprocessing / Joblib)

# -------------------------------------------------------------------------------

class ParallelComputation:
    """

    Parallel computation utilities for UQFF physics calculations.

    Implements:

        - Multiprocessing pool for CPU-bound tasks
        - Joblib wrapper for embarrassingly parallel operations
        - Batch processing for large datasets
        - Progress tracking for long computations

    Applications:

        - Multi-system UQFF calculations
        - Parameter space exploration
        - Monte Carlo sampling parallelization
        - Large-scale N-body simulations

    Usage:

        # Parallel map
        results = ParallelComputation.parallel_map(compute_uqff, systems, n_jobs=4)
        # Batch processing with progress
        results = ParallelComputation.batch_process(heavy_func, data, batch_size=100)

    """

    # Try to import joblib for enhanced parallelism

    try:

        from joblib import Parallel, delayed
        JOBLIB_AVAILABLE = True

    except ImportError:

        JOBLIB_AVAILABLE = False

    @staticmethod

    def get_cpu_count() -> int:
        """Get number of available CPU cores."""
        import multiprocessing
        return multiprocessing.cpu_count()

    @staticmethod

    def parallel_map(func: Callable, items: List, n_jobs: int = -1,

                     backend: str = 'auto', verbose: int = 0) -> List:
        """
        Apply function to items in parallel.
        Args:
            func: Function to apply to each item
            items: List of inputs
            n_jobs: Number of parallel jobs (-1 = all CPUs, 1 = sequential)
            backend: 'joblib', 'multiprocessing', or 'auto'
            verbose: Verbosity level for joblib
        Returns:
            List of results in same order as inputs
        """
        if n_jobs == 1 or len(items) == 0:
            return [func(item) for item in items]
        if n_jobs == -1:
            n_jobs = ParallelComputation.get_cpu_count()
        # Auto-select backend
        if backend == 'auto':
            backend = 'joblib' if ParallelComputation.JOBLIB_AVAILABLE else 'multiprocessing'
        if backend == 'joblib' and ParallelComputation.JOBLIB_AVAILABLE:
            from joblib import Parallel, delayed
            return Parallel(n_jobs=n_jobs, verbose=verbose)(
                delayed(func)(item) for item in items
            )
        else:
            # Fallback to multiprocessing
            import multiprocessing
            with multiprocessing.Pool(n_jobs) as pool:
                return pool.map(func, items)

    @staticmethod

    def parallel_starmap(func: Callable, args_list: List[Tuple],

                         n_jobs: int = -1) -> List:
        """
        Apply function with multiple arguments in parallel.
        Args:
            func: Function taking multiple arguments
            args_list: List of argument tuples
            n_jobs: Number of parallel jobs
        Returns:
            List of results
        """
        if n_jobs == 1 or len(args_list) == 0:
            return [func(*args) for args in args_list]
        if n_jobs == -1:
            n_jobs = ParallelComputation.get_cpu_count()
        if ParallelComputation.JOBLIB_AVAILABLE:
            from joblib import Parallel, delayed
            return Parallel(n_jobs=n_jobs)(
                delayed(func)(*args) for args in args_list
            )
        else:
            import multiprocessing
            with multiprocessing.Pool(n_jobs) as pool:
                return pool.starmap(func, args_list)

    @staticmethod

    def batch_process(func: Callable, data: List, batch_size: int = 100,

                      n_jobs: int = -1, progress_callback: Callable = None) -> List:
        """
        Process data in batches with optional parallelism.
        UQFF Application: Process 100+ astronomical systems in parallel
        with progress tracking for long computations.
        Args:
            func: Function to apply to each item
            data: Full dataset
            batch_size: Items per batch
            n_jobs: Parallel jobs per batch
            progress_callback: Called with (batch_idx, total_batches, batch_results)
        Returns:
            Combined results from all batches
        """
        n_items = len(data)
        n_batches = (n_items + batch_size - 1) // batch_size
        all_results = []
        for i in range(n_batches):
            start = i * batch_size
            end = min(start + batch_size, n_items)
            batch = data[start:end]
            # Process batch
            if n_jobs == 1:
                batch_results = [func(item) for item in batch]
            else:
                batch_results = ParallelComputation.parallel_map(func, batch, n_jobs)
            all_results.extend(batch_results)
            # Progress callback
            if progress_callback:
                progress_callback(i + 1, n_batches, batch_results)
        return all_results

    @staticmethod

    def parallel_monte_carlo(sampler_func: Callable, n_samples: int,

                             n_jobs: int = -1, seed_base: int = 42) -> np.ndarray:
        """
        Run Monte Carlo sampling in parallel with independent seeds.
        Args:
            sampler_func: Function that takes (n_samples, seed) and returns samples
            n_samples: Total number of samples
            n_jobs: Number of parallel jobs
            seed_base: Base seed (each worker gets seed_base + worker_id)
        Returns:
            Combined samples array
        """
        if n_jobs == -1:
            n_jobs = ParallelComputation.get_cpu_count()
        samples_per_job = n_samples // n_jobs
        remainder = n_samples % n_jobs
        # Create argument list: (n_samples_for_job, seed)
        args_list = []
        for i in range(n_jobs):
            n = samples_per_job + (1 if i < remainder else 0)
            args_list.append((n, seed_base + i))
        # Run in parallel
        results = ParallelComputation.parallel_starmap(sampler_func, args_list, n_jobs)
        # Combine
        return np.concatenate(results)

    @staticmethod

    def parallel_grid_evaluation(func: Callable, grid_points: List[np.ndarray],

                                  n_jobs: int = -1) -> np.ndarray:
        """
        Evaluate function on a grid in parallel.
        UQFF Application: Parameter space exploration, computing F_U_Bi_i
        over (r, t, ?) grid for visualization.
        Args:
            func: Function f(x1, x2, ..., xn) -> scalar
            grid_points: List of 1D arrays for each dimension
            n_jobs: Parallel jobs
        Returns:
            N-dimensional array of function values on grid
        """
        # Create meshgrid
        grids = np.meshgrid(*grid_points, indexing='ij')
        shape = grids[0].shape
        # Flatten to list of points
        points = np.stack([g.ravel() for g in grids], axis=1)
        # Evaluate in parallel
        values = ParallelComputation.parallel_map(
            lambda p: func(*p), [tuple(p) for p in points], n_jobs
        )
        # Reshape to grid
        return np.array(values).reshape(shape)

    @staticmethod

    def async_computation(func: Callable, *args, callback: Callable = None, 

                          **kwargs) -> 'multiprocessing.pool.AsyncResult':
        """
        Start an asynchronous computation.
        Args:
            func: Function to run
            *args: Function arguments
            callback: Called with result when done
            **kwargs: Function keyword arguments
        Returns:
            AsyncResult that can be queried for completion
        """
        import multiprocessing
        pool = multiprocessing.Pool(1)
        def wrapper():
            return func(*args, **kwargs)
        result = pool.apply_async(wrapper, callback=callback)
        return result

    @staticmethod

    def get_status() -> dict:
        """Get parallel computation status and capabilities."""
        import multiprocessing
        return {
            'cpu_count': multiprocessing.cpu_count(),
            'joblib_available': ParallelComputation.JOBLIB_AVAILABLE,
            'recommended_n_jobs': max(1, multiprocessing.cpu_count() - 1),
            'backends': ['multiprocessing'] + (['joblib'] if ParallelComputation.JOBLIB_AVAILABLE else [])
        }

    def compute(self, dataset: dict = None):
        """Stub compute() for infrastructure/helper class."""
        return {}

