# JSON-RPC SERVER MODE - For bidirectional Qt6 communication

# -------------------------------------------------------------------------------

class JSONRPCServer:
    """

    JSON-RPC server for Qt6 PythonBridge integration.

    Reads JSON requests from stdin, dispatches to methods, returns JSON responses.

    Protocol:

        Request:  {"id": 1, "method": "compute_equation", "params": {...}}
        Response: {"id": 1, "method": "compute_equation", "result": {...}}

    Start with: python CondensedPhysics.py --json-rpc

    """

    def __init__(self):

        self.running = False
        self.calculator = None  # Lazy load

    def run(self):
        """Main server loop - read stdin, dispatch, write stdout."""
        self.running = True
        UQFFLogger.info("JSONRPCServer", "Server started, awaiting requests...")
        while self.running:
            try:
                line = sys.stdin.readline()
                if not line:
                    break
                line = line.strip()
                if not line:
                    continue
                request = json.loads(line)
                response = self.dispatch(request)
                print(json.dumps(response), flush=True)
            except json.JSONDecodeError as e:
                error_response = {"error": f"Invalid JSON: {e}"}
                print(json.dumps(error_response), flush=True)
            except Exception as e:
                error_response = {"error": str(e)}
                print(json.dumps(error_response), flush=True)
        UQFFLogger.info("JSONRPCServer", "Server shutdown")

    def dispatch(self, request: dict) -> dict:
        """Route request to appropriate handler."""
        method = request.get("method", "")
        params = request.get("params", {})
        request_id = request.get("id", 0)
        # Handle shutdown
        if method == "__shutdown__":
            self.running = False
            return {"id": request_id, "method": method, "result": {"status": "shutdown"}}
        # Lazy load calculator
        if self.calculator is None:
            self.calculator = CondensedPhysicsCalculator()
        # Dispatch methods
        handlers = {
            "compute_equation": self._handle_compute_equation,
            "query_system": self._handle_query_system,
            "run_tests": self._handle_run_tests,
            "list_equations": self._handle_list_equations,
            "get_constants": self._handle_get_constants,
        }
        handler = handlers.get(method)
        if handler:
            result = handler(params)
            return {"id": request_id, "method": method, "result": result}
        else:
            return {"id": request_id, "error": f"Unknown method: {method}"}

    def _handle_compute_equation(self, params: dict) -> dict:
        """Compute a specific UQFF equation."""
        eq_num = params.get("equation", 1)
        system = params.get("system", {})
        t = params.get("t", 1.0)
        # Create SystemParams from dict
        sp = SystemParams(
            name=system.get("name", "Unknown"),
            M=float(system.get("M", CONSTANTS["M_sun"])),
            r=float(system.get("r", CONSTANTS["R_sun"])),
            T=float(system.get("T", 5778)),
            B0=float(system.get("B0", 1e-4)),
            omega_s=float(system.get("omega_s", 2.5e-6)),
        )
        self.calculator.current_system = sp
        result = self.calculator.compute_equation(eq_num, t)
        UQFFLogger.physics("UQFF", f"Equation {eq_num} computed", result)
        return result

    def _handle_query_system(self, params: dict) -> dict:
        """Query and load a system from APIs."""
        query = params.get("query", "Sun")
        sp = self.calculator.query_system(query)
        if sp:
            return {
                "name": sp.name,
                "M": sp.M,
                "r": sp.r,
                "T": sp.T,
                "B0": sp.B0,
                "omega_s": sp.omega_s,
            }
        return {"error": "System not found"}

    def _handle_run_tests(self, params: dict) -> dict:
        """Run framework tests."""
        result = run_framework_tests()
        UQFFLogger.validation("Tests", result["summary"], result)
        return result

    def _handle_list_equations(self, params: dict) -> dict:
        """List all available UQFF equations."""
        equations = []
        for i, eq in UQFF_MASTER_EQUATIONS.items():
            equations.append({
                "number": i,
                "name": eq.name,
                "description": eq.description,
                "scale": eq.scale
            })
        return {"equations": equations}

    def _handle_get_constants(self, params: dict) -> dict:
        """Return physical constants."""
        # Return a subset of important constants
        keys = params.get("keys", ["G", "c", "hbar", "M_sun", "R_sun"])
        result = {}
        for key in keys:
            if key in CONSTANTS:
                result[key] = CONSTANTS[key]
        return result

    def compute(self, dataset: dict = None):
        """Stub compute() for infrastructure/helper class."""
        return {}

