        if not hasattr(params, 'Q_UA'):
            params.Q_UA = 1e-11
        if not hasattr(params, 'd_g'):
            params.d_g = 2.55e20
        if not hasattr(params, 'g_local'):
            params.g_local = 9.81
        if not hasattr(params, 'V_sys'):
            params.V_sys = 1e30
        if not hasattr(params, 'delta_rho'):
            params.delta_rho = 0.27
        # aDPM base from DPM equation
        I = 1.0  # Intensity
        A = 1.0  # Area
        omega1, omega2 = params.omega_s, params.omega_c
        Evac_neb = CONSTANTS['rho_vac_UA']
        c_res = CONSTANTS['c']
        V_sys = params.V_sys
        FDPM = I * A * (omega1 - omega2)
        fDPM = 1.0
        aDPM = FDPM * fDPM * Evac_neb * c_res * V_sys
        # 5 Main frequencies
        f_super = 1e15
        f_quantum = 1e15
        f_aether = 1e12
        f_fluid = 1e6
        f_exp = 1e-18
        a_SuperFreq = aDPM * np.cos(f_super * t) * 0.1
        a_QuantumFreq = aDPM * np.cos(f_quantum * t) * 0.01
        a_AetherFreq = aDPM * np.cos(f_aether * t) * 0.001
        a_FluidFreq = aDPM * np.cos(f_fluid * t) * 1e-6
        a_ExpFreq = aDPM * np.cos(f_exp * t) * 1e-10
