class UQFFSuperconductive(UQFFMasterEquation):
    """

    UQFF Superconductive Mode

    Um_SCm = ?_vac,[SCm] � P_SCm � H_SCm � (1 - e^(-?t) � cos(pt_n))

    Key factors:

        P_SCm: Bose occupancy = 1 - exp(-E_react/kT)
        H_SCm: Heaviside ~0.99 at quiet Sun
        E_react: Reactivity energy with ? decay

    """

    def __init__(self):

        super().__init__(
            "UQFF_Superconductive",
            "Superconductive Mode: SCm vacuum density modulation",
            "Quantum"
        )

    def compute(self, dataset: dict = None, t: float = 1.0) -> Dict[str, Any]:
        """Compute superconductive SCm contribution"""
        # -- dict ? namespace (auto-generated) -----------------------
        if isinstance(dataset, dict):
            from types import SimpleNamespace as _NS
            params = _NS(**{k: v for k, v in dataset.items() if k in dataset})
        elif dataset is not None:
            params = dataset
        else:
            from types import SimpleNamespace as _NS
            params = _NS(M=1.989e30, r=6.96e8, B0=1e-4, omega0=2.5e-6,
                              v=1e5, R=6.96e8, T=5778.0, theta=0.1)
        # UQFF attr aliases (keys not in standard TEST_DATASET)
        if not hasattr(params, 'M_BH'):
            params.M_BH = getattr(params, 'Mbh', 8.15e36)
        if not hasattr(params, 't_n'):
            params.t_n = getattr(params, 'tn', 0.0)
        if not hasattr(params, 'R_b'):
            params.R_b = 1.496e13
        if not hasattr(params, 'rho_fluid'):
            params.rho_fluid = getattr(params, 'rho', 1e-20)
        if not hasattr(params, 'omega_c'):
            params.omega_c = getattr(params, 'omega', 1e-8)
        if not hasattr(params, 'L_X'):
            params.L_X = 1e30
        if not hasattr(params, 'P_SCm'):
            params.P_SCm = 1.0
        if not hasattr(params, 'P_core'):
            params.P_core = 1.0
        if not hasattr(params, 'f_feedback'):
            params.f_feedback = 0.05
        if not hasattr(params, 'name'):
            params.name = 'default'
        if not hasattr(params, 'omega_s'):
            params.omega_s = getattr(params, 'omega', 2.5e-6)
        if not hasattr(params, 'SCm_density'):
            params.SCm_density = 1e15
        if not hasattr(params, 'Q_A'):
            params.Q_A = 1e-10
        if not hasattr(params, 'Q_UA'):
            params.Q_UA = 1e-11
        if not hasattr(params, 'd_g'):
            params.d_g = 2.55e20
        if not hasattr(params, 'g_local'):
            params.g_local = 9.81
        if not hasattr(params, 'V_sys'):
            params.V_sys = 1e30
        if not hasattr(params, 'delta_rho'):
            params.delta_rho = 0.27
        rho_vac_SCm = CONSTANTS['rho_vac_SCm']
        rho_A = CONSTANTS['rho_A']
        kappa = CONSTANTS['kappa']
        k_B = CONSTANTS['k_B']
        gamma = CONSTANTS['gamma']
        H_SCm = CONSTANTS['H_SCm']
        B_crit = CONSTANTS['B_crit']
        v_SCm = CONSTANTS.get('v_SCm', 1e8)  # SCm velocity (108 m/s)
        day_to_sec = CONSTANTS['day_to_sec']
        # E_react calculation: E_react = (?_SCm � v_SCm�) / ?_A � e^(-?t)
        E_react = (rho_vac_SCm * v_SCm ** 2 / rho_A) * np.exp(-kappa * t / day_to_sec)
        # P_SCm (Bose occupancy)
        if params.T > 0:
            P_SCm = 1.0 - np.exp(-E_react / (k_B * params.T))
        else:
            P_SCm = 1.0
        # H_SCm Heaviside
        H_SCm_val = H_SCm if params.B0 < B_crit else 0.0
        # SCm contribution - CRITICAL: cos(pt_n) must be INSIDE the exponent
        # for proper time-reversal dynamics (see t_n document)
        cos_tn = np.cos(np.pi * params.t_n)
        exponent = -gamma * t * cos_tn
        decay_factor = 1.0 - np.exp(exponent)
        Um_SCm = rho_vac_SCm * P_SCm * H_SCm_val * decay_factor
        return {
            'Um_SCm': Um_SCm,
            'E_react': E_react,
            'P_SCm': P_SCm,
            'H_SCm': H_SCm_val,
            'decay_factor': decay_factor,
        }

