class UQFFQuadratic(UQFFMasterEquation):
    """

    UQFF Quadratic Mode

    x2 = (-b - v(b� - 4ac)) / 2a

    Quadratic root solutions for UQFF integrand approximations.

    Used for solving the F_U_Bi_i integral through algebraic roots.

    """

    def __init__(self):

        super().__init__(
            "UQFF_Quadratic",
            "Quadratic Mode: Root solutions for UQFF integrals",
            "Mathematical"
        )

    def compute(self, dataset: dict = None, t: float = 1.0) -> Dict[str, Any]:
        """Compute quadratic roots for UQFF"""
        # -- dict ? namespace (auto-generated) -----------------------
        if isinstance(dataset, dict):
            from types import SimpleNamespace as _NS
            params = _NS(**{k: v for k, v in dataset.items() if k in dataset})
        elif dataset is not None:
            params = dataset
        else:
            from types import SimpleNamespace as _NS
            params = _NS(M=1.989e30, r=6.96e8, B0=1e-4, omega0=2.5e-6,
                              v=1e5, R=6.96e8, T=5778.0, theta=0.1)
        # UQFF attr aliases (keys not in standard TEST_DATASET)
        if not hasattr(params, 'M_BH'):
            params.M_BH = getattr(params, 'Mbh', 8.15e36)
        if not hasattr(params, 't_n'):
            params.t_n = getattr(params, 'tn', 0.0)
        if not hasattr(params, 'R_b'):
            params.R_b = 1.496e13
        if not hasattr(params, 'rho_fluid'):
            params.rho_fluid = getattr(params, 'rho', 1e-20)
        if not hasattr(params, 'omega_c'):
            params.omega_c = getattr(params, 'omega', 1e-8)
        if not hasattr(params, 'L_X'):
            params.L_X = 1e30
        if not hasattr(params, 'P_SCm'):
            params.P_SCm = 1.0
        if not hasattr(params, 'P_core'):
            params.P_core = 1.0
        if not hasattr(params, 'f_feedback'):
            params.f_feedback = 0.05
        if not hasattr(params, 'name'):
            params.name = 'default'
        if not hasattr(params, 'omega_s'):
            params.omega_s = getattr(params, 'omega', 2.5e-6)
        if not hasattr(params, 'SCm_density'):
            params.SCm_density = 1e15
        if not hasattr(params, 'Q_A'):
            params.Q_A = 1e-10
        if not hasattr(params, 'Q_UA'):
            params.Q_UA = 1e-11
        if not hasattr(params, 'd_g'):
            params.d_g = 2.55e20
        if not hasattr(params, 'g_local'):
            params.g_local = 9.81
        if not hasattr(params, 'V_sys'):
            params.V_sys = 1e30
        if not hasattr(params, 'delta_rho'):
            params.delta_rho = 0.27
        G = CONSTANTS['G']
        c = CONSTANTS['c']
        epsilon_0 = CONSTANTS['epsilon_0']
        q = CONSTANTS['q']
        # Approximate coefficients from UQFF theory
        F_neutron = 1e6  # Typical neutron term
        # a coefficient (from gravitational + EM + light terms)
        a = (1.38e-41 * q / (4 * np.pi * epsilon_0 * params.r ** 2 * F_neutron) +
             (G * params.M / (params.r ** 2)) +
             (4 * c ** 2 / (params.r ** 2)))
        # b coefficient (from neutron + phase terms)
        PHASE = 0.0
        b = 2.51e-5 + F_neutron / (params.r ** 2) + PHASE + PHASE
        # c coefficient (constant + curvature)
        CURVATURE = 0.0
        c_coef = -3.06e175 + 1e-29 / (params.r ** 2) + CURVATURE
        # Discriminant
        discriminant = b ** 2 - 4 * a * c_coef
        # Roots
        if discriminant >= 0:
            x1 = (-b + np.sqrt(discriminant)) / (2 * a)
            x2 = (-b - np.sqrt(discriminant)) / (2 * a)
            real_roots = True
        else:
            # Complex roots
            real_part = -b / (2 * a)
            imag_part = np.sqrt(-discriminant) / (2 * a)
            x1 = complex(real_part, imag_part)
            x2 = complex(real_part, -imag_part)
            real_roots = False
        return {
            'a': a,
            'b': b,
            'c': c_coef,
            'discriminant': discriminant,
            'x1': x1,
            'x2': x2,
            'real_roots': real_roots,
        }

