        if not results['SC_m_in_range']:
            all_pass = False
        # Test 5: P_stable peaks at ? = exp(�) = exp(0) = 1
        P_stable_peak, _ = self.compute_P_stable(1.0)  # ? = 1, log(1) = 0 = �
        results['P_stable_peak_at_unity'] = P_stable_peak > 0.99
        if not results['P_stable_peak_at_unity']:
            all_pass = False
        # Test 6: P_stable in [0, 1]
        P_stable_low, _ = self.compute_P_stable(0.01)  # Far from peak
        P_stable_high, _ = self.compute_P_stable(100.0)  # Far from peak
