    def _generate_element_masses(self) -> Dict[int, float]:
        """Generate approximate element masses for Z=1 to 126"""
        m_p = CONSTANTS['m_proton']
        masses = {}
        for Z in range(1, 127):
            # Approximate mass number A � 2.5Z for heavy elements
            if Z <= 20:
                A = 2 * Z
            elif Z <= 83:
                A = int(2.2 * Z)
            else:
                A = int(2.5 * Z)  # Superheavy elements
            masses[Z] = A * m_p
        return masses

    def compute_Fg(self, r: float = None) -> Tuple[float, str]:
        """
        Compute gravitational force between proton and electron in H atom
        F_g = G � m_p � m_e / r�
        Parameters:
            r: Distance (m), default is Bohr radius a0
        Returns:
            F_g value and calculation steps
        PHYSICAL MEANING:
            This force is ~10?47 N, negligible compared to Coulomb force
            (~8.2�10?8 N), but included for universal framework completeness.
        """
        G = CONSTANTS['G']
        m_p = CONSTANTS['m_proton']
        m_e = CONSTANTS['m_electron']
        if r is None:
            r = CONSTANTS['a0_bohr']
        Fg = dpm_ug1_seed(m_p, r) * m_e
        # For comparison: Coulomb force
        k_e = 8.99e9  # Coulomb constant (N�m�/C�)
        e = 1.602e-19  # Elementary charge (C)
        F_coulomb = k_e * e**2 / r**2
        steps = f"""

    F_g (Gravitational Force in Hydrogen Atom)

    ---------------------------------------------------------------

    EQUATION: F_g = G � m_p � m_e / r�

    Step 1: Constants

            G = {G:.4e} m�/kg/s�
            m_p = {m_p:.4e} kg (proton mass)
            m_e = {m_e:.4e} kg (electron mass)
            r = {r:.4e} m (Bohr radius)

    Step 2: Gravitational force

            F_g = ({G:.4e}) � ({m_p:.4e}) � ({m_e:.4e}) / ({r:.4e})�
            F_g = {Fg:.4e} N

    COMPARISON TO COULOMB FORCE:

            F_Coulomb = k � e� / r� = {F_coulomb:.4e} N
            F_Coulomb / F_g = {F_coulomb / Fg:.2e}

    INTERPRETATION:

            Gravity is ~10�? times weaker than EM in atoms.
            Included for UQFF unification at cosmic scales."""
        return Fg, steps

    def compute_En(self, n: int) -> Tuple[float, str]:
        """
        Compute hydrogen energy levels from Schr�dinger equation
        E_n = -13.6 / n� eV
        Parameters:
            n: Principal quantum number (1, 2, 3, ...)
        Returns:
            E_n in eV and calculation steps
        """
        if n < 1:
            raise ValueError("Quantum number n must be = 1")
        E_Rydberg = CONSTANTS['E_ionization_H']
        En = -E_Rydberg / n**2
        # Also compute wavelength for emission n?1
        if n > 1:
            h = 6.626e-34  # Planck constant (J�s)
            c = CONSTANTS['c']
            delta_E_J = (E_Rydberg * (1 - 1/n**2)) * 1.602e-19  # J
            wavelength = h * c / delta_E_J * 1e9  # nm
        else:
            wavelength = float('inf')
        steps = f"""

    E_n (Hydrogen Energy Levels)

    ---------------------------------------------------------------

    EQUATION: E_n = -13.6 / n� eV

    Step 1: Quantum number

            n = {n}

    Step 2: Energy calculation

            E_{n} = -13.6 / {n}�
            E_{n} = -13.6 / {n**2}
            E_{n} = {En:.4f} eV

    Step 3: Wavelength for n?1 transition

            ? = hc / ?E = {wavelength:.2f} nm

    PHYSICAL INTERPRETATION:

            {'Ground state (most stable, tightly bound)' if n == 1 else
             f'Excited state n={n}, weakly bound, ~{abs(En):.2f} eV from ionization'}

    SPECTRAL SERIES:

            n=2?1: Lyman-a (121.6 nm, UV)
            n=3?2: Balmer-a (656.3 nm, red)
            n?8: Ionization continuum"""
        return En, steps

    def compute_reduced_mass(self, isotope: str = 'protium') -> Tuple[float, str]:
        """
        Compute reduced mass for hydrogen isotope
        � = m_e � m_nucleus / (m_e + m_nucleus)
        Parameters:
            isotope: 'protium', 'deuterium', or 'tritium'
        Returns:
            Reduced mass and calculation steps
        """
        m_e = CONSTANTS['m_electron']
        if isotope not in self.isotopes:
            raise ValueError(f"Unknown isotope: {isotope}")
        data = self.isotopes[isotope]
        m_nucleus = data['mass_kg']
        mu = m_e * m_nucleus / (m_e + m_nucleus)
        mu_ratio = mu / m_e
        steps = f"""

    � (Reduced Mass for {isotope.title()})

    ---------------------------------------------------------------

    EQUATION: � = m_e � m_nucleus / (m_e + m_nucleus)

    Step 1: Masses

            m_e = {m_e:.4e} kg
            m_nucleus ({data['symbol']}) = {m_nucleus:.4e} kg

    Step 2: Reduced mass

            � = ({m_e:.4e}) � ({m_nucleus:.4e}) / ({m_e:.4e} + {m_nucleus:.4e})
            � = {mu:.6e} kg

    Step 3: Ratio to electron mass

            � / m_e = {mu_ratio:.6f}

    ISOTOPIC SHIFT:

            Reduced mass affects energy levels: E_n ? �
            {data['symbol']} levels shifted by {(1-mu_ratio)*100:.4f}% from infinite-mass limit

    ALL ISOTOPES:

            �H (protium):   �/m_e � {CONSTANTS['mu_protium']/m_e:.6f}
            �H (deuterium): �/m_e � {CONSTANTS['mu_deuterium']/m_e:.6f}
            �H (tritium):   �/m_e � {CONSTANTS['mu_tritium']/m_e:.6f}"""
        return mu, steps

    def compute_meff_superconductor(self, T: float, Tc: float, 

                                     B: float = 1e6, B_crit: float = 1e3) -> Tuple[float, str]:
        """
        Compute effective mass in superconductive phase (Meissner effect)
        m_eff = m � (1 - B_crit/B) � f_sc(T, Tc)
        Parameters:
            T: Operating temperature (K)
            Tc: Critical temperature (K)
            B: Ambient magnetic field (T)
            B_crit: Critical magnetic field (T)
        Returns:
            Effective mass ratio and calculation steps
        """
        m_p = CONSTANTS['m_proton']
        alpha_sc = CONSTANTS['alpha_sc_H']
        beta_sc = CONSTANTS['beta_sc_H']
        # Meissner effect term (only valid for B > B_crit)
        if B > B_crit:
            meissner_factor = 1 - B_crit / B
        else:
            meissner_factor = 0.0  # Fully superconducting (expelled field)
        # Superconductivity factor
        f_sc = alpha_sc * np.exp(-beta_sc * (T - Tc)) if T > Tc else alpha_sc
        m_eff = m_p * meissner_factor * (1 + f_sc)
        steps = f"""

    m_eff (Effective Mass with Superconductivity)

    ---------------------------------------------------------------

    EQUATION: m_eff = m � (1 - B_crit/B) � (1 + f_sc)

    Step 1: Meissner effect term

            B = {B:.4e} T (ambient field)
            B_crit = {B_crit:.4e} T (critical field)
            Meissner factor = 1 - B_crit/B = {meissner_factor:.6f}

    Step 2: Superconductivity factor

            f_sc = a_sc � exp(-�(T - Tc))
            a_sc = {alpha_sc}, � = {beta_sc}
            T = {T:.1f} K, Tc = {Tc:.1f} K
            f_sc = {f_sc:.6f}

    Step 3: Effective mass

            m_eff = {m_p:.4e} � {meissner_factor:.6f} � (1 + {f_sc:.6f})
            m_eff = {m_eff:.6e} kg
            m_eff / m_p = {m_eff/m_p:.6f}

    INTERPRETATION:

            {'Superconducting state (T < Tc)' if T < Tc else 'Normal state (T > Tc)'}
            Effective mass is {'reduced' if m_eff < m_p else 'enhanced'} by superconductivity"""
        return m_eff, steps

    def compute_f_sc(self, T: float, Tc: float) -> Tuple[float, str]:
        """
        Compute superconductivity factor for MUGE
        f_sc(T) = a_sc � exp(-�(T - Tc))
        Parameters:
            T: Operating temperature (K)
            Tc: Critical temperature (K)
        Returns:
            f_sc value and calculation steps
        """
        alpha_sc = CONSTANTS['alpha_sc_H']
        beta_sc = CONSTANTS['beta_sc_H']
        if T <= Tc:
            f_sc = alpha_sc  # Maximum coupling below Tc
        else:
            f_sc = alpha_sc * np.exp(-beta_sc * (T - Tc))
        steps = f"""

    f_sc (Superconductivity Factor)

    ---------------------------------------------------------------

    EQUATION: f_sc = a_sc � exp(-�(T - Tc))  [for T > Tc]

              f_sc = a_sc                     [for T = Tc]

    Step 1: Parameters

            a_sc = {alpha_sc} (coupling strength)
            � = {beta_sc} (temperature sensitivity, 1/K)
            T = {T:.2f} K
            Tc = {Tc:.2f} K

    Step 2: Calculation

            T - Tc = {T - Tc:.2f} K
            {'T = Tc ? f_sc = a_sc' if T <= Tc else f'T > Tc ? f_sc = {alpha_sc} � exp(-{beta_sc} � {T-Tc:.2f})'}
            f_sc = {f_sc:.6f}

    INTERPRETATION:

            f_sc modulates gravitational interactions in MUGE-H
            Higher f_sc ? stronger superconductive coupling
            f_sc = {alpha_sc:.2f} is maximum (100% superconducting)"""
        return f_sc, steps

    def compute_MH_evolution(self, t_years: float, M_H0: float = 1.989e30) -> Tuple[float, str]:
        """
        Compute evolved hydrogen mass due to fusion depletion
        M_H(t) = M_H0 � exp(-?t/t_Hubble)
        Parameters:
            t_years: Time in years since star formation
            M_H0: Initial hydrogen mass (kg), default is 1 solar mass
        Returns:
            Current hydrogen mass and calculation steps
        """
        t_s = t_years * 3.156e7  # Convert to seconds
        lambda_f = CONSTANTS['lambda_fusion']
        t_Hubble = CONSTANTS['t_Hubble_s']
        exponent = -lambda_f * t_s / t_Hubble
        MH_t = M_H0 * np.exp(exponent)
        fraction_remaining = MH_t / M_H0
        steps = f"""

    M_H(t) (Hydrogen Mass Evolution)

    ---------------------------------------------------------------

    EQUATION: M_H(t) = M_H0 � exp(-?t/t_Hubble)

    Step 1: Parameters

            M_H0 = {M_H0:.4e} kg (initial mass)
            ? = {lambda_f} (fusion rate)
            t_Hubble = {t_Hubble:.4e} s (13.8 Gyr)

    Step 2: Time conversion

            t = {t_years:.2e} years
            t = {t_s:.4e} s

    Step 3: Exponent

            -?t/t_Hubble = -{lambda_f} � {t_s:.4e} / {t_Hubble:.4e}
            exponent = {exponent:.6e}

    Step 4: Evolved mass

            M_H(t) = {M_H0:.4e} � exp({exponent:.6e})
            M_H(t) = {MH_t:.4e} kg

    INTERPRETATION:

            Fraction remaining: {fraction_remaining*100:.4f}%
            Time to deplete 50%: {np.log(2) * t_Hubble / lambda_f / 3.156e7 / 1e9:.2f} Gyr"""
        return MH_t, steps

    def compute_pp_chain_rate(self, rho: float = None, X_H: float = None, 

                               T: float = None) -> Tuple[float, str]:
        """
        Compute proton-proton fusion rate in stellar core
        e_pp � 2.38�106 � ? � X_H� � T_6^(-2/3) � exp(-33.81/T_6^(1/3)) erg/g/s
        Parameters:
            rho: Core density (kg/m�), default is solar core
            X_H: Hydrogen mass fraction, default is initial 0.7
            T: Core temperature (K), default is 1.5�107 K
        Returns:
            Fusion rate in W/kg and calculation steps
        """
        # Defaults for solar core
        if rho is None:
            rho = CONSTANTS['rho_sun_core']
        if X_H is None:
            X_H = CONSTANTS['X_H_initial']
        if T is None:
            T = CONSTANTS['T_sun_core']
        # Convert to cgs for standard formula
        rho_cgs = rho / 1000  # kg/m� ? g/cm�
        T6 = T / 1e6  # Temperature in millions of K
        # e_pp in erg/g/s
        eps_erg = 2.38e6 * rho_cgs * X_H**2 * T6**(-2/3) * np.exp(-33.81 / T6**(1/3))
        # Convert to W/kg: 1 erg/g/s = 1e-4 W/kg
        eps_SI = eps_erg * 1e-4
        # Luminosity estimate for solar core
        M_core = 1.989e30 * 0.1  # 10% of solar mass in core
        L_core = eps_SI * M_core
        steps = f"""

    e_pp (Proton-Proton Fusion Rate)

    ---------------------------------------------------------------

    EQUATION: e_pp = 2.38�106 � ? � X_H� � T_6^(-2/3) � exp(-33.81/T_6^(1/3))

    Step 1: Core parameters

            ? = {rho:.4e} kg/m� = {rho_cgs:.2f} g/cm�
            X_H = {X_H:.2f} (hydrogen mass fraction)
            T = {T:.4e} K = {T6:.2f} MK

    Step 2: Temperature factor

            T_6^(-2/3) = {T6**(-2/3):.4f}

    Step 3: Coulomb barrier tunneling

            exp(-33.81/T_6^(1/3)) = exp(-33.81/{T6**(1/3):.4f})
            = exp({-33.81/T6**(1/3):.4f})
            = {np.exp(-33.81/T6**(1/3)):.4e}

    Step 4: Fusion rate

            e_pp = 2.38�106 � {rho_cgs:.2f} � {X_H**2:.4f} � {T6**(-2/3):.4f} � {np.exp(-33.81/T6**(1/3)):.4e}
            e_pp = {eps_erg:.4e} erg/g/s
            e_pp = {eps_SI:.4e} W/kg

    Step 5: Core luminosity estimate

            L_core = e � M_core = {eps_SI:.4e} � {M_core:.2e}
            L_core = {L_core:.4e} W

    PP-CHAIN REACTIONS:

        4p ? 4He + 2e? + 2?e + {CONSTANTS['Q_pp_MeV']:.2f} MeV
        Step 1: p+p ? �H + e? + ?e + {CONSTANTS['pp_step1_MeV']:.2f} MeV
        Step 2: �H+p ? �He + ? + {CONSTANTS['pp_step2_MeV']:.2f} MeV
        Step 3: �He+�He ? 4He + 2p + {CONSTANTS['pp_step3_MeV']:.2f} MeV"""
        return eps_SI, steps

    def compute_metallic_H_transition(self, P: float, T: float = 5000) -> Tuple[Dict[str, Any], str]:
        """
        Compute metallic hydrogen phase transition properties
        Parameters:
            P: Pressure (Pa)
            T: Temperature (K), default 5000 K (planetary interior)
        Returns:
            Transition properties dict and calculation steps
        """
        P_transition = CONSTANTS['P_metallic_H_transition']
        rho_liquid = CONSTANTS['rho_liquid_H']
        rho_metallic = CONSTANTS['rho_metallic_H']
        Tc_exp = CONSTANTS['Tc_metallic_H_exp']
        # Phase determination
        is_metallic = P >= P_transition
        # Density interpolation near transition
        if P < P_transition * 0.5:
            rho = rho_liquid
            phase = 'molecular (insulating)'
        elif P < P_transition:
            # Transition region
            f = (P - P_transition * 0.5) / (P_transition * 0.5)
            rho = rho_liquid + f * (rho_metallic - rho_liquid)
            phase = 'transition'
        else:
            rho = rho_metallic
            phase = 'metallic (conductive)'
        # Superconductivity check
        is_superconducting = is_metallic and T < Tc_exp
        result = {
            'pressure_Pa': P,
            'pressure_GPa': P / 1e9,
            'temperature_K': T,
            'phase': phase,
            'is_metallic': is_metallic,
            'density_kg_m3': rho,
            'is_superconducting': is_superconducting,
            'Tc_K': Tc_exp if is_metallic else None,
        }
        steps = f"""

    Metallic Hydrogen Phase Transition

    ---------------------------------------------------------------

    TRANSITION: Molecular ? Metallic at P � 200 GPa (2 Mbar)

    Step 1: Input conditions

            P = {P:.4e} Pa = {P/1e9:.1f} GPa
            T = {T:.1f} K

    Step 2: Phase determination

            P_transition = {P_transition:.4e} Pa = {P_transition/1e9:.0f} GPa
            P {'=' if is_metallic else '<'} P_transition
            Phase: {phase}

    Step 3: Density

            ?_liquid = {rho_liquid} kg/m�
            ?_metallic = {rho_metallic} kg/m�
            Current ? = {rho:.1f} kg/m�

    Step 4: Superconductivity check

            Is metallic: {is_metallic}
            Tc (metallic H) = {Tc_exp} K
            T {'<' if is_superconducting else '>'} Tc
            Superconducting: {is_superconducting}

    PLANETARY CONTEXT:

        Jupiter core: P � {CONSTANTS['Jupiter_core_P']/1e9:.0f} GPa ? metallic H
        Jupiter metallic H fraction: {CONSTANTS['Jupiter_metallic_H_fraction']*100:.0f}%
        Saturn metallic H fraction: {CONSTANTS['Saturn_metallic_H_fraction']*100:.0f}%"""
        return result, steps

    def compute_g_MUGE(self, r: float, t_years: float, Z: int = 1,

                       T: float = 300, Tc: float = None) -> Tuple[float, Dict[str, Any], str]:
        """
        Compute Master Universal Gravity Equation for Hydrogen Evolution
        g_MUGE(r,t,Z) = G�m_eff(t)�m_p/r� + S(Z=1 to Z_max) G�M_Z/r_Z� � (1+f_sc) � e^(H0t/c)
        Parameters:
            r: Distance from nucleus (m)
            t_years: Cosmic time since formation (years)
            Z: Atomic number of interacting element (default 1 = H)
            T: Operating temperature (K)
            Tc: Critical temperature for superconductivity (default uses H3S)
        Returns:
            g_MUGE value, component dict, and calculation steps
        """
        G = CONSTANTS['G']
        m_p = CONSTANTS['m_proton']
        H0 = CONSTANTS['H0_SI']
        c = CONSTANTS['c']
        # Time conversion
        t_s = t_years * 3.156e7
        # Default Tc to H3S if not specified
        if Tc is None:
            Tc = CONSTANTS['H3S_Tc']
        # 1. Effective mass (evolved + superconductivity modified)
        MH_t, _ = self.compute_MH_evolution(t_years, m_p)
        m_eff = MH_t
        # 2. Atomic gravity term: G�m_eff�m_p/r�
        g_atomic = dpm_ug1_seed(m_eff, r) * m_p
        # 3. Superconductivity factor
        f_sc, _ = self.compute_f_sc(T, Tc)
        # 4. Cosmic expansion factor
        expansion_factor = np.exp(H0 * t_s / c)
        # 5. Elemental interaction sum (simplified: single element Z)
        if Z in self.element_masses:
            M_Z = self.element_masses[Z]
        else:
            M_Z = 2.5 * Z * m_p  # Estimate for superheavy
        r_Z = r  # Assume same distance for simplicity
        g_Z = dpm_ug1_seed(M_Z, r_Z) * (1 + f_sc) * expansion_factor
        # Total MUGE
