        E2, _ = self.compute_En(2)
        results['E_ground_state'] = abs(E1 + 13.6) < 0.1
        results['E_first_excited'] = abs(E2 + 3.4) < 0.1
        if not results['E_ground_state'] or not results['E_first_excited']:
            all_pass = False
        # Test 3: Reduced masses
        mu_p, _ = self.compute_reduced_mass('protium')
        mu_d, _ = self.compute_reduced_mass('deuterium')
        results['reduced_mass_order'] = mu_p < mu_d  # Deuterium has larger reduced mass
        if not results['reduced_mass_order']:
            all_pass = False
        # Test 4: Superconductivity factor
        f_sc_below, _ = self.compute_f_sc(T=200, Tc=203)  # Below Tc
        f_sc_above, _ = self.compute_f_sc(T=300, Tc=203)  # Above Tc
        results['f_sc_below_Tc_max'] = abs(f_sc_below - 0.1) < 0.01
        results['f_sc_above_Tc_decays'] = f_sc_above < f_sc_below
        if not results['f_sc_below_Tc_max'] or not results['f_sc_above_Tc_decays']:
            all_pass = False
        # Test 5: Mass evolution (stellar hydrogen depletion)
        M_solar = 1.989e30  # Initial solar mass
        MH_now, _ = self.compute_MH_evolution(t_years=4.6e9, M_H0=M_solar)  # Sun age
        results['mass_decreases'] = MH_now < M_solar  # Mass should decrease due to fusion
        results['mass_positive'] = MH_now > 0
        if not results['mass_decreases'] or not results['mass_positive']:
            all_pass = False
        # Test 6: PP chain rate positive
        eps_pp, _ = self.compute_pp_chain_rate()
        results['pp_rate_positive'] = eps_pp > 0
        if not results['pp_rate_positive']:
            all_pass = False
        # Test 7: Metallic H transition
