    def compute_nonlocal_term(self, n: int, t: float) -> Tuple[float, str]:
        """
        Compute non-local interaction term from Red Dwarf Reactor data
        [SSq]^n26 � exp(-p - t)
        Parameters:
            n: Quantum state number (1-26)
            t: Time (s)
        Returns:
            Non-local term value and calculation steps
        """
        SSq = CONSTANTS['SSq_base']  # 0.57
        # [SSq]^(n/26) � exp(-p - t)
        SSq_power = SSq ** (n / 26)
        exp_term = np.exp(-np.pi - t)
        nl_val = SSq_power * exp_term
        steps = f"""

    Non-Local Interaction Term

    ---------------------------------------------------------------

    EQUATION: [SSq]^(n/26) � exp(-p - t)

    Step 1: Parameters

            [SSq] = {SSq} (calibrated value)
            n = {n} (quantum state)
            t = {t:.4e} s

    Step 2: Power term

            [SSq]^(n/26) = {SSq}^({n}/26) = {SSq_power:.6e}

    Step 3: Exponential term

            exp(-p - t) = exp({-np.pi - t:.6f}) = {exp_term:.6e}

    Step 4: Non-local term

            [SSq]^(n/26) � exp(-p - t) = {SSq_power:.6e} � {exp_term:.6e}
            = {nl_val:.6e}

    PHYSICAL MEANING:

        This term models non-local jumps observed in plasmoid behavior
        in Red Dwarf Reactor experiments. Decays rapidly with time."""
        return nl_val, steps

    def compute_negative_time_operator(self, t_n: float) -> Tuple[float, str]:
        """
        Compute negative time operator for quantum state transitions
        t? = -t_n � exp(p - t_n)
        Parameters:
            t_n: Normalized time relative to reference
        Returns:
            Negative time operator value and steps
        """
        t_minus = -t_n * np.exp(np.pi - t_n)
        steps = f"""

    Negative Time Operator

    ---------------------------------------------------------------

    EQUATION: t? = -t_n � exp(p - t_n)

    Step 1: Input

            t_n = {t_n:.4f} (normalized time)

    Step 2: Exponent

            p - t_n = {np.pi - t_n:.4f}
            exp(p - t_n) = {np.exp(np.pi - t_n):.4e}

    Step 3: Negative time

            t? = -{t_n:.4f} � {np.exp(np.pi - t_n):.4e}
            t? = {t_minus:.4e}

    PHYSICAL MEANING:

        Drives transitions between 26 quantum states.
        Enables time-reversal effects in TRZs.
        Note: t? is negative, indicating backward time flow."""
        return t_minus, steps

    def compute_quark_mass_energy(self, quark: str, n: int = None) -> Tuple[float, str]:
        """
        Compute UQFF-modified quark mass energy with quantum state
        E_q = m_q � c� � exp(n/26)
        Parameters:
            quark: 'u', 'd', 'c', 's', 't', or 'b'
            n: Quantum state (1-26), default uses particle's assigned state
        Returns:
            Mass energy in J and calculation steps
        """
        if quark not in self.quarks:
            raise ValueError(f"Unknown quark: {quark}")
        q = self.quarks[quark]
        c = CONSTANTS['c']
        m_q = q['mass_kg']
        if n is None:
            n = q['quantum_state']
        # E_q = m_q � c� � exp(n/26)
        E_base = m_q * c**2
        quantum_factor = np.exp(n / 26)
        E_q = E_base * quantum_factor
        steps = f"""

    Quark Mass Energy ({q['name']} Quark, n={n})

    ---------------------------------------------------------------

    EQUATION: E_q = m_q � c� � exp(n/26)

    Step 1: Quark parameters

            Quark: {q['symbol']} ({q['name']})
            Mass: m_q = {m_q:.4e} kg
            Charge: q = {q['charge']:.2f}e
            Generation: {q['generation']}

    Step 2: Base mass energy

            E_base = m_q � c�
            E_base = {m_q:.4e} � ({c:.4e})�
            E_base = {E_base:.4e} J
            E_base = {E_base / 1.602e-19 / 1e6:.3f} MeV

    Step 3: Quantum state factor

            exp(n/26) = exp({n}/26) = exp({n/26:.4f})
            = {quantum_factor:.6f}

    Step 4: UQFF mass energy

            E_q = {E_base:.4e} � {quantum_factor:.6f}
            E_q = {E_q:.4e} J
            E_q = {E_q / 1.602e-19 / 1e6:.3f} MeV

    UQFF INTERPRETATION:

        The factor exp(n/26) modifies mass based on quantum state.
        Higher states (n?26) have enhanced effective mass.
        This bridges physical and conscious reality dimensions."""
        return E_q, steps

    def compute_quark_energy_density(self, quark: str, t: float = 0, 

                                      t_n: float = 0) -> Tuple[float, str]:
        """
        Compute quark energy density in UQFF framework
        U_q = ?_q � ?_vac,[SCm] � ?_vac,[UA] � ?_q(t) � cos(pt_n) � (1+f_TRZ) 
              � exp(-[SSq]^n26 � exp(-p-t))
        Parameters:
            quark: 'u', 'd', 'c', 's', 't', or 'b'
            t: Time (s)
            t_n: Normalized time
        Returns:
            Energy density in J/m� and calculation steps
        """
        if quark not in self.quarks:
            raise ValueError(f"Unknown quark: {quark}")
        q = self.quarks[quark]
        # Get parameters
        lambda_q = q['lambda']
        omega_q = q['omega']
        n = q['quantum_state']
        rho_SCm = CONSTANTS['rho_vac_SCm']  # _RHO_VAC_SCM at solar scale
        rho_UA = CONSTANTS['rho_vac_UA']    # _RHO_VAC_UA at solar scale
        f_TRZ = CONSTANTS['f_TRZ']          # 0.1
        # Compute terms
        cos_term = np.cos(np.pi * t_n)
        nl_val, _ = self.compute_nonlocal_term(n, t)
        # U_q = ?_q � ?_SCm � ?_UA � ?_q � cos(pt_n) � (1+f_TRZ) � exp(-nl_val)
        U_q = lambda_q * rho_SCm * rho_UA * omega_q * cos_term * (1 + f_TRZ) * np.exp(-nl_val)
        steps = f"""

    Quark Energy Density in Aether ({q['name']} Quark)

    -------------------------------------------------------------------------------

    EQUATION:

        U_q = ?_q � ?_vac,[SCm] � ?_vac,[UA] � ?_q(t) � cos(pt_n) � (1+f_TRZ)
              � exp(-[SSq]^(n/26) � exp(-p-t))

    -------------------------------------------------------------------------------

    PARAMETERS

    -------------------------------------------------------------------------------

        Quark: {q['symbol']} ({q['name']})
        ?_q (coupling) = {lambda_q}
        ?_q (vortex freq) = {omega_q:.2e} rad/s
        n (quantum state) = {n}
        t = {t:.4e} s
        t_n = {t_n:.4f}

    -------------------------------------------------------------------------------

    VACUUM DENSITIES

    -------------------------------------------------------------------------------

        ?_vac,[SCm] = {rho_SCm:.4e} J/m�
        ?_vac,[UA] = {rho_UA:.4e} J/m�

    -------------------------------------------------------------------------------

    CALCULATION

    -------------------------------------------------------------------------------

        cos(pt_n) = cos({np.pi * t_n:.4f}) = {cos_term:.6f}
        f_TRZ = {f_TRZ}
        (1 + f_TRZ) = {1 + f_TRZ}
        Non-local term = {nl_val:.6e}
        exp(-nl_val) = {np.exp(-nl_val):.6f}
        U_q = {lambda_q} � {rho_SCm:.4e} � {rho_UA:.4e} � {omega_q:.2e}
              � {cos_term:.6f} � {1 + f_TRZ} � {np.exp(-nl_val):.6f}
        U_q = {U_q:.4e} J/m�

    PHYSICAL INTERPRETATION:

        Quarks are quantized vortices in the [UA] superfluid.
        Energy density depends on coupling to [SCm] + [UA] vacuum.
        Non-local term reflects quark confinement via gluon exchange."""
        return U_q, steps

