    def compute_decay_rate(self, particle: str, t: float = 0) -> Tuple[float, str]:
        """
        Compute particle decay rate.
        G = (1/t) � e^(-t/t)
        Args:
            particle: Particle name (e.g., 'neutron', 'K_plus', 'muon')
            t: Time since creation (s)
        Returns:
            Tuple of (decay rate G in s?�, explanation string)
        """
        tau = self.decay_lifetimes.get(particle, 1.0)
        Gamma = (1/tau) * np.exp(-t/tau)
        survival_prob = np.exp(-t/tau)
        explanation = f"""

    PARTICLE DECAY RATE ({particle})

    -------------------------------------------------------------------------------

    FORMULA:

        G(t) = (1/t) � e^(-t/t)
        P_survival = e^(-t/t)

    INPUTS:

        t_{particle} = {tau:.4e} s (mean lifetime)
        t = {t:.4e} s (time since creation)

    CALCULATION:

        G = (1/{tau:.4e}) � e^(-{t:.4e}/{tau:.4e})
          = {1/tau:.4e} � {np.exp(-t/tau):.6f}
          = {Gamma:.4e} s?�
        P_survival = {survival_prob:.4f} ({survival_prob*100:.2f}%)

    PHYSICAL INTERPRETATION:

        Particles decay via the WEAK FORCE in UQFF. The decay rate in the
        Aether context may differ from vacuum due to [UA] interactions.

    -------------------------------------------------------------------------------

    """

        return Gamma, explanation

