# HILL SPHERE MODEL (Solar System Boundary)

# -------------------------------------------------------------------------------

class HillSphereModel(SelfSimulatingExpandingMixin):
    """

    Hill Sphere Model - Gravitational Dominance Boundary

    From the document: The Hill sphere defines the region where the Sun's

    gravity outmuscles the Milky Way's tidal forces.

    KEY EQUATION:

    -----------------------------------------------------------------------------

    r_H � a � (M_sun / (3 � M_gal))^(1/3)

    Where:

        r_H   : Hill sphere radius (m)
        a     : Distance from galactic center (m)
        M_sun : Solar mass (kg)
        M_gal : Milky Way total mass (kg)

    PARAMETERS FROM DOCUMENT:

    -----------------------------------------------------------------------------

    M_sun = 1.989�10�� kg

    M_gal � 1.5�104� kg (Milky Way total mass)

    a = 8 kpc � 2.468�10�� m

    RESULT: r_H � 230,000 AU

    However, the Oort Cloud's outer limit (~100,000 AU) is the conservative

    bound for practical solar control, accounting for galactic perturbations.

    """

    def __init__(self):
        """Initialize Hill Sphere Model."""
        # Physical constants
        self.AU = 1.496e11  # m
        self.kpc = 3.086e19  # m
        self.ly = 9.461e15  # m
        # Solar parameters
        self.M_sun = CONSTANTS.get('M_Sun', 1.989e30)
        # Milky Way parameters
        self.M_gal = 1.5e42  # kg
        self.a_sun = 8e3 * self.kpc / 1e3  # 8 kpc = 2.468�10�� m
        # Farthest known objects
        self.known_objects = {
            'Neptune': 30,  # AU
            'Eris_aphelion': 96,
            'Sedna_aphelion': 937,
            'The_Goblin_aphelion': 2300,
            'Inner_Oort_Cloud': 20000,
            'Outer_Oort_Cloud': 100000,
            'Hill_Sphere': 230000
        }

    def compute_hill_sphere(self, M_star: float = None, a: float = None,

                             M_primary: float = None) -> Tuple[float, float, str]:
        """
        Compute Hill sphere radius.
        r_H � a � (M_star / (3 � M_primary))^(1/3)
        Args:
            M_star: Star mass (kg)
            a: Distance from primary (m)
            M_primary: Primary body mass (kg)
        Returns:
            r_H_m: Hill radius (m)
            r_H_AU: Hill radius (AU)
            steps: Derivation string
        """
        M_star = M_star if M_star is not None else self.M_sun
        a = a if a is not None else self.a_sun
        M_primary = M_primary if M_primary is not None else self.M_gal
        r_H = a * (M_star / (3 * M_primary))**(1/3)
        r_H_AU = r_H / self.AU
        r_H_ly = r_H / self.ly
        steps = f"""

    HILL SPHERE RADIUS

    ------------------------------------------------------------------

    r_H � a � (M_star / (3 � M_primary))^(1/3)

    PARAMETERS:

        M_star = {M_star:.4e} kg (Sun)
        M_primary = {M_primary:.4e} kg (Milky Way)
        a = {a:.4e} m (8 kpc)

    CALCULATION:

        Mass ratio = M_star / (3 � M_primary)
                   = {M_star:.4e} / (3 � {M_primary:.4e})
                   = {M_star / (3 * M_primary):.4e}
        Cube root = {(M_star / (3 * M_primary))**(1/3):.4e}
        r_H = {a:.4e} � {(M_star / (3 * M_primary))**(1/3):.4e}
            = {r_H:.4e} m
            = {r_H_AU:.0f} AU
            = {r_H_ly:.2f} light-years

    COMPARISON:

        Document value: ~230,000 AU
        Calculated: {r_H_AU:.0f} AU

    ------------------------------------------------------------------"""

        return r_H, r_H_AU, steps

    def get_farthest_object(self, category: str = 'known') -> Tuple[str, float, str]:
        """
        Get farthest object under solar control.
        Args:
            category: 'known', 'inferred', or 'theoretical'
        Returns:
            name: Object name
            distance: Distance in AU
            steps: Description
        """
        if category == 'known':
            name = 'Sedna'
            distance = self.known_objects['Sedna_aphelion']
            description = "Farthest directly observed body with confirmed orbit (discovered 2003)"
        elif category == 'inferred':
            name = 'Outer Oort Cloud comet'
            distance = self.known_objects['Outer_Oort_Cloud']
            description = "Inferred from long-period comet origins"
        else:  # theoretical
            name = 'Hill Sphere boundary'
            distance = self.known_objects['Hill_Sphere']
            description = "Theoretical limit of solar gravitational dominance"
        steps = f"""

    FARTHEST BODY UNDER SOLAR CONTROL

    ------------------------------------------------------------------

    Category: {category.upper()}

    OBJECT: {name}

    DISTANCE: {distance:,.0f} AU ({distance * self.AU / self.ly:.2f} light-years)

    DESCRIPTION: {description}

    COMPARISON (all in AU):

    ------------------------------------------------------------------

        Neptune:          30 AU
        Eris:             96 AU (aphelion)
        Sedna:            937 AU (aphelion)
        The Goblin:       2,300 AU (aphelion)
        Inner Oort Cloud: 20,000 AU
        Outer Oort Cloud: 100,000 AU (practical limit)
        Hill Sphere:      230,000 AU (theoretical limit)

    ------------------------------------------------------------------"""

        return name, distance, steps

    def validate_model(self) -> Tuple[bool, list, str]:
        """Validate Hill Sphere Model."""
        tests = []
        # Test 1: Hill sphere in range 100,000-300,000 AU (depends on M_gal estimate)
        r_H, r_H_AU, _ = self.compute_hill_sphere()
        tests.append({
            'name': 'Hill sphere in valid range (100k-300k AU)',
            'r_H_AU': r_H_AU,
            'passed': 100000 < r_H_AU < 300000  # Document: 230k; varies with M_gal estimate
        })
        # Test 2: All known objects have distances
        tests.append({
            'name': 'All known objects have distances',
            'n_objects': len(self.known_objects),
            'passed': len(self.known_objects) >= 7
        })
        # Test 3: Sedna is farthest known
        name, dist, _ = self.get_farthest_object('known')
        tests.append({
            'name': 'Sedna is farthest known object',
            'name': name,
            'distance': dist,
            'passed': name == 'Sedna'
        })
        # Test 4: Oort Cloud < Hill Sphere
        tests.append({
            'name': 'Oort Cloud < Hill Sphere',
            'passed': self.known_objects['Outer_Oort_Cloud'] < self.known_objects['Hill_Sphere']
        })
        all_passed = all(t['passed'] for t in tests)
        summary = f"""HILL SPHERE MODEL VALIDATION

--------------------------------------------------------------------------------

TEST RESULTS:

--------------------------------------------------------------------------------

1. Hill sphere � 230,000 AU:       {'? PASS' if tests[0]['passed'] else '? FAIL'}

   r_H = {tests[0]['r_H_AU']:,.0f} AU

2. All objects have distances:     {'? PASS' if tests[1]['passed'] else '? FAIL'}

   {tests[1]['n_objects']} objects defined

3. Sedna is farthest known:        {'? PASS' if tests[2]['passed'] else '? FAIL'}

   {tests[2]['name']} at {tests[2]['distance']} AU

4. Oort Cloud < Hill Sphere:       {'? PASS' if tests[3]['passed'] else '? FAIL'}

--------------------------------------------------------------------------------

SUMMARY: {sum(t['passed'] for t in tests)}/{len(tests)} tests passed

--------------------------------------------------------------------------------

{'ALL TESTS PASSED ?' if all_passed else 'SOME TESTS FAILED ?'}

--------------------------------------------------------------------------------

"""

        return all_passed, tests, summary

    @staticmethod

    def run_tests() -> dict:
        """Test HillSphereModel functionality."""
        tests = []
        try:
            model = HillSphereModel()
            tests.append({'name': 'Instantiation', 'passed': model is not None})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'error': str(e)})
        try:
            model = HillSphereModel()
            has_method = hasattr(model, 'compute') or hasattr(model, 'calculate') or hasattr(model, 'get_equation_text')
            tests.append({'name': 'Has compute method', 'passed': has_method})
        except Exception as e:
            tests.append({'name': 'Has compute method', 'passed': False, 'error': str(e)})
        all_passed = all(t['passed'] for t in tests)
        return {'class': 'HillSphereModel', 'tests': tests, 'passed': sum(1 for t in tests if t['passed']), 'total': len(tests), 'all_passed': all_passed}

    # === 8 UQFF MASTER EQUATIONS (Auto-added) ===

    def compute_UQFF_base(self, r=None, t=0):
        """UQFF Base: F_U = Ug1 + Ug2 + Ug3 + Ug4 - Ub + Ui"""
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        Ug = dpm_ug1_seed(M, r)
        return {'Ug': Ug, 'F_U': Ug, 'equation': f"F_U = G*M/r^2 = {Ug:.3e} m/s^2"}

    def compute_compressed_equation(self, r=None):
        """Compressed MUGE gravity equation"""
        import numpy as np
        G, H_0 = _URP_G, 2.268e-18
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_N = dpm_ug1_seed(M, r)
        g_H = H_0**2 * r
        g = g_N - g_H
        return {'g_compressed': g, 'g_N': g_N, 'g_Hubble': g_H}

    def compute_resonance_equation(self, r=None, t=0):
        """Resonance MUGE with frequency modes"""
        import numpy as np
        G, H_0, c = _URP_G, 2.268e-18, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        aDPM = dpm_ug1_seed(M, r)
        aExpFreq = H_0 * c * np.sin(H_0 * t)
        return {'g_resonance': aDPM + aExpFreq, 'aDPM': aDPM, 'aExpFreq': aExpFreq}

    def compute_superconductive_equation(self, T=None, T_c=None):
        """Superconductive coefficient H_SCm"""
        T = T if T else getattr(self, 'T', 4.2)
        T_c = T_c if T_c else getattr(self, 'T_c', 9.2)
        H_SCm = max(0, 1 - (T / T_c)**4) if T < T_c else 0
        return {'H_SCm': H_SCm, 'T': T, 'T_c': T_c}

    def compute_buoyant_equation(self, r=None, V=None):
        """Buoyancy component Ub"""
        import numpy as np
        G, rho_vac = _URP_G, _RHO_VAC_UA
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        if V is None: V = (4/3) * np.pi * r**3
        g = dpm_ug1_seed(M, r)
        Ub = (rho_vac * V * g) / M
        return {'Ub': Ub, 'g': g, 'V': V}

    def compute_master_buoyant_equation(self, r=None, v=0):
        """Master Buoyant: F_U_Bi_i = M * (Ug_i - Ub_i + Ui_i)"""
        import numpy as np
        G, rho_vac, k_eta, c = _URP_G, _RHO_VAC_UA, 1e-113, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        V = (4/3) * np.pi * r**3
        Ug = dpm_ug1_seed(M, r)
        Ub = (rho_vac * V * Ug) / M
        Ui = -k_eta * rho_vac * V * (v / c)**2
        a_net = Ug - Ub + Ui
        return {'F_U_Bi_i': M * a_net, 'Ug': Ug, 'Ub': Ub, 'Ui': Ui, 'a_net': a_net}

    def compute_triadic_equation(self, r=None):
        """Triadic gravity: g_matter + g_field + g_vacuum"""
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_matter = dpm_ug1_seed(M, r)
        g_field, g_vacuum = 1e-15, 1e-20
        return {'g_triadic': g_matter + g_field + g_vacuum, 'g_matter': g_matter}

    def compute_quadratic_equation(self, r=None):
        """Quadratic polynomial fit: g = a*r^2 + b*r + c"""
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        # DPM-seeded: mu_s x grad(M_s/r) base (Newtonian form is emergent, not foundational)
        g_base = dpm_ug1_seed(M, r)
        a, b, c = -1e-30, 1e-20, g_base
        return {'g_quad': a * r**2 + b * r + c, 'a': a, 'b': b, 'c': c}

    def long_form_solution(self, r=None, t=0):
        """
        Long-form solution with complete equation display.
        Returns detailed step-by-step calculation for all UQFF equations.
        """
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        # Collect all equation results
        results = {}
        steps = []
        # 1. UQFF Base
        uqff = self.compute_UQFF_base(r, t)
        results['UQFF_base'] = uqff
        steps.append(f"UQFF Base: F_U = G*M/r^2 = {uqff['Ug']:.6e} m/s^2")
        # 2. Compressed equation
        comp = self.compute_compressed_equation(r)
        results['compressed'] = comp
        steps.append(f"Compressed: g = g_N - g_H = {comp['g_compressed']:.6e} m/s^2")
        # 3. Resonance equation
        res = self.compute_resonance_equation(r, t)
        results['resonance'] = res
        steps.append(f"Resonance: g_res = aDPM + aExpFreq = {res['g_resonance']:.6e} m/s^2")
        # 4. Superconductive
        sc = self.compute_superconductive_equation()
        results['superconductive'] = sc
        steps.append(f"Superconductive: H_SCm = {sc['H_SCm']:.6f}")
        # 5. Buoyant equation
        buoy = self.compute_buoyant_equation(r)
        results['buoyant'] = buoy
        steps.append(f"Buoyancy: Ub = {buoy['Ub']:.6e} m/s^2")
        # 6. Master buoyant
        master = self.compute_master_buoyant_equation(r)
        results['master_buoyant'] = master
        steps.append(f"Master Buoyant: F_U_Bi_i = {master['F_U_Bi_i']:.6e} N")
        # 7. Triadic
        tri = self.compute_triadic_equation(r)
        results['triadic'] = tri
        steps.append(f"Triadic: g_triadic = {tri['g_triadic']:.6e} m/s^2")
        # 8. Quadratic
        quad = self.compute_quadratic_equation(r)
        results['quadratic'] = quad
        steps.append(f"Quadratic: g_quad = {quad['g_quad']:.6e} m/s^2")
        return {
            'model': self.__class__.__name__,
            'parameters': {'M': M, 'r': r, 't': t},
            'results': results,
            'long_form': '\n'.join(steps)
        }

    def compute_master_gravity(self, r=None, t=0, include_all=True):
        """
        Master Gravity: Complete UQFF gravity computation.
        g_master = g_N * (1 - Ub/g_N + Ui/g_N) * H_SCm * fTRZ
        Combines: Newtonian, buoyancy, inertia, superconductivity, triadic zone
        """
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        # DPM-seeded: Newtonian form is emergent, not foundational\r\n
        g_N = dpm_ug1_seed(M, r)
        # Get buoyancy correction
        buoy = self.compute_buoyant_equation(r)
        Ub = buoy['Ub']
        # Get superconductive coefficient
        sc = self.compute_superconductive_equation()
        H_SCm = sc['H_SCm']
        # Get triadic factor (default: in resonance zone)
        fTRZ = 1.0
        # Compute master gravity
        if g_N != 0:
            correction = 1 - Ub / g_N
        else:
            correction = 1.0
        g_master = g_N * correction * max(0.01, H_SCm) * fTRZ
        # Collect additional terms if requested
        if include_all:
            comp = self.compute_compressed_equation(r)
            res = self.compute_resonance_equation(r, t)
            tri = self.compute_triadic_equation(r)
            return {
                'g_master': g_master,
                'g_N': g_N,
                'Ub': Ub,
                'H_SCm': H_SCm,
                'fTRZ': fTRZ,
                'correction': correction,
                'g_compressed': comp['g_compressed'],
                'g_resonance': res['g_resonance'],
                'g_triadic': tri['g_triadic'],
                'equation': f"g_master = g_N * (1 - Ub/g_N) * H_SCm * fTRZ = {g_master:.6e} m/s^2"
            }
        return {'g_master': g_master, 'g_N': g_N}

    def compute(self, dataset: dict) -> dict:
        """Hill sphere radius r_H = a * (m/(3*M))^(1/3) with UQFF F_UBi correction.

        Hill sphere: gravitational sphere of influence of body m orbiting body M at semi-major axis a.
        UQFF F_UBi buoyancy expands the sphere slightly at outer boundary.
        """
        import math
        # Earth-Sun default
        a_m = dataset.get('a_m', 1.496e11)
        m_kg = dataset.get('m_kg', 5.972e24)
        M_kg = dataset.get('M_kg', 1.989e30)
        r_Hill_classical = a_m * (m_kg / (3.0 * M_kg))**(1.0/3.0)
        # UQFF F_UBi buoyancy expansion at boundary
        F_UBi_expansion = 1.0 + F_TRZ * SSQ / K_MEX
        r_Hill_UQFF = r_Hill_classical * F_UBi_expansion
        # Solar system examples
        a_earth = 1.496e11; m_earth = 5.972e24; M_sun = 1.989e30
        rH_earth = a_earth * (m_earth/(3*M_sun))**(1.0/3.0)
        a_jupiter = 7.785e11; m_jupiter = 1.898e27
        rH_jupiter = a_jupiter * (m_jupiter/(3*M_sun))**(1.0/3.0)
        # In AU
        AU = 1.496e11
        return {
            'primary_equations': [
                f"a = {a_m:.3e} m ({a_m/AU:.2f} AU)",
                f"m = {m_kg:.3e} kg (secondary mass)",
                f"M = {M_kg:.3e} kg (primary mass)",
                f"r_Hill_classical = a * (m/(3M))^(1/3) = {r_Hill_classical:.3e} m ({r_Hill_classical/AU:.4f} AU)",
                f"UQFF F_UBi expansion = (1+F_TRZ*SSQ/K_MEX) = {F_UBi_expansion:.6f}",
                f"r_Hill_UQFF = {r_Hill_UQFF:.3e} m ({r_Hill_UQFF/AU:.4f} AU)",
                f"Earth Hill radius = {rH_earth:.3e} m ({rH_earth/AU:.4f} AU, observed 0.01 AU)",
                f"Jupiter Hill radius = {rH_jupiter:.3e} m ({rH_jupiter/AU:.4f} AU, observed 0.35 AU)",
            ],
            'a_m': a_m, 'm_kg': m_kg, 'M_kg': M_kg,
            'r_Hill_classical_m': r_Hill_classical,
            'r_Hill_UQFF_m': r_Hill_UQFF,
            'r_Hill_classical_AU': r_Hill_classical/AU,
            'r_Hill_UQFF_AU': r_Hill_UQFF/AU,
            'F_UBi_expansion': F_UBi_expansion,
            'r_Hill_Earth_AU': rH_earth/AU,
            'r_Hill_Jupiter_AU': rH_jupiter/AU,
            'F_TRZ': F_TRZ, 'SSQ': SSQ, 'K_MEX': K_MEX,
            'note': 'Hill radius with UQFF F_UBi buoyancy expansion (1+F_TRZ*SSQ/K_MEX) at boundary.',
        }



# Round 4 singleton bindings — both classes now defined above
M_SIGMA_MODEL = MSigmaRelationModel()
