        tests.append(f"Test 3: ?_obs(500nm, z=0.5) = {lambda_obs*1e9:.0f} nm = 750: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        # Test 4: Higher spin ? prograde ISCO closer ? higher redshift (deeper potential)
