class BHMFEvolutionModel(SelfSimulatingExpandingMixin):
    """

    Black Hole Mass Function Evolution Model

    Models the evolution of the SMBH mass distribution over cosmic time,

    tracking population growth through accretion and mergers.

    KEY EQUATION (Continuity):

    -----------------------------------------------------------------------------

    ?F(M,z)/?z + ?[F(M,z)???]/?M = S(M,z)

    Where:

        F(M,z) : Number density of SMBHs with mass M at redshift z (Mpc?� dex?�)
        ??? : Average accretion rate (M_?/yr)
        S(M,z) : Source/sink term (mergers, seeding)

    PHYSICAL INTERPRETATION:

    -----------------------------------------------------------------------------

    - Left side: Conservation of SMBH number density

    - ?F/?z: Change with cosmic time

    - ?(F???)/?M: Growth through accretion

    - S(M,z): Mergers add pairs, seeding creates new SMBHs

    KEY RESULTS:

    -----------------------------------------------------------------------------

    - Large fraction of SMBHs in place by z � 4 for e = 0.07

    - Implies massive seeds (M ~ 105 M_?) required

    - Local BHMF: F(M) ? M^(-1.2) for M > 107 M_?

    �2025 Daniel T. Murphy - All Rights Reserved

    """

    def __init__(self):

        self.M_sun = 1.989e30      # Solar mass (kg)
        self.Mpc_to_m = 3.086e22   # Mpc to meters
        # Local BHMF parameters (Schechter-like function)
        self.Phi_star = 1e-3       # Normalization (Mpc?� dex?�)
        self.M_star = 1e8          # Characteristic mass (M_?)
        self.alpha = -1.2          # Low-mass slope
        # Accretion parameters
        self.epsilon_rad = 0.1     # Radiative efficiency
        self.t_Salp = 4.5e7        # Salpeter time (yr)

    def compute_local_BHMF(self, M: float) -> Tuple[float, str]:
        """
        Compute local (z=0) black hole mass function.
        Args:
            M: Black hole mass (M_?)
        Returns:
            Phi: Number density (Mpc?� dex?�)
            steps: Calculation explanation
        """
        import math
        # Schechter function: F(M) = F* � (M/M*)^a � exp(-M/M*)
        x = M / self.M_star
        Phi = self.Phi_star * (x ** self.alpha) * math.exp(-x)
        steps = f"""Local Black Hole Mass Function:


  F(M) = F* � (M/M*)^a � exp(-M/M*)


  Parameters:

    M = {M:.4e} M_?

    F* = {self.Phi_star:.4e} Mpc?� dex?�

    M* = {self.M_star:.4e} M_?

    a = {self.alpha}


  Calculation:

    M/M* = {x:.4f}

    (M/M*)^a = {x**self.alpha:.4e}

    exp(-M/M*) = {math.exp(-x):.4e}


  Result:

    F(M) = {Phi:.4e} Mpc?� dex?�


  This means {Phi * 1e9:.2f} SMBHs per Gpc� in this mass bin.

"""

        return Phi, steps

    def compute_mass_density(self, M_min: float = 1e6, M_max: float = 1e10, 

                              n_bins: int = 100) -> Tuple[float, str]:
        """
        Compute total SMBH mass density from BHMF.
        Args:
            M_min: Minimum mass (M_?)
            M_max: Maximum mass (M_?)
            n_bins: Integration bins
        Returns:
            rho_BH: Mass density (M_? Mpc?�)
            steps: Calculation explanation
        """
        import math
        # ?_BH = ? M � F(M) � d(log M)
        log_M_min = math.log10(M_min)
        log_M_max = math.log10(M_max)
        d_log_M = (log_M_max - log_M_min) / n_bins
        rho_BH = 0
        for i in range(n_bins):
            log_M = log_M_min + (i + 0.5) * d_log_M
            M = 10**log_M
            Phi, _ = self.compute_local_BHMF(M)
            rho_BH += M * Phi * d_log_M
        steps = f"""SMBH Mass Density:


  ?_BH = ? M � F(M) d(log M)


  Integration range:

    M_min = {M_min:.4e} M_?

    M_max = {M_max:.4e} M_?


  Result:

    ?_BH = {rho_BH:.4e} M_? Mpc?�

    ?_BH = {rho_BH * self.M_sun / self.Mpc_to_m**3:.4e} kg m?�


  This represents the total SMBH contribution to cosmic mass density.

"""

        return rho_BH, steps

    def compute_e_folding_time(self, epsilon: float = None) -> Tuple[float, str]:
        """
        Compute e-folding (Salpeter) time for SMBH growth.
        t_Salp = e � s_T � c / (4p � G � m_p) � 4.5 � 107 yr � (e/0.1)
        Args:
            epsilon: Radiative efficiency [0.05, 0.4]
        Returns:
            t_Salp: Salpeter time (yr)
            steps: Calculation explanation
        """
        if epsilon is None:
            epsilon = self.epsilon_rad
        t_Salp = 4.5e7 * (epsilon / 0.1)
        steps = f"""Salpeter (e-folding) Time:


  t_Salp � 4.5 � 107 yr � (e/0.1)


  Parameters:

    e (radiative efficiency) = {epsilon}


  Result:

    t_Salp = {t_Salp:.4e} yr


  At Eddington accretion, SMBH mass doubles every ~t_Salp.

  From 10� M_? to 10? M_? requires ~23 e-foldings = {23*t_Salp/1e9:.2f} Gyr

"""

        return t_Salp, steps

    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate BHMF Evolution Model."""
        import math
        tests = []
        all_passed = True
        # Test 1: BHMF peaks near M*
        Phi_low, _ = self.compute_local_BHMF(1e6)
        Phi_high, _ = self.compute_local_BHMF(1e10)
        t1 = Phi_low > Phi_high  # More low-mass SMBHs
        tests.append(f"Test 1: F(106) = {Phi_low:.2e} > F(10��) = {Phi_high:.2e}: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        # Test 2: Mass density in reasonable range (104 - 106 M_?/Mpc�)
        rho, _ = self.compute_mass_density()
        t2 = 1e4 < rho < 1e6
        tests.append(f"Test 2: ?_BH = {rho:.2e} M_?/Mpc� ? [104, 106]: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        # Test 3: Salpeter time ~45 Myr for e=0.1
        t_Salp, _ = self.compute_e_folding_time(0.1)
        t3 = 4e7 < t_Salp < 5e7
        tests.append(f"Test 3: t_Salp(e=0.1) = {t_Salp:.2e} yr � 4.5�107: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        # Test 4: Higher efficiency ? slower growth
        t_low, _ = self.compute_e_folding_time(0.05)
        t_high, _ = self.compute_e_folding_time(0.2)
        t4 = t_high > t_low
        tests.append(f"Test 4: t_Salp(e=0.2) > t_Salp(e=0.05): {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        summary = f"BHMFEvolutionModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary

    @staticmethod

    def run_tests() -> dict:
        """Test BHMFEvolutionModel functionality."""
        tests = []
        try:
            model = BHMFEvolutionModel()
            tests.append({'name': 'Instantiation', 'passed': model is not None})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'error': str(e)})
        try:
            model = BHMFEvolutionModel()
            has_method = hasattr(model, 'compute') or hasattr(model, 'calculate') or hasattr(model, 'get_equation_text')
            tests.append({'name': 'Has compute method', 'passed': has_method})
        except Exception as e:
            tests.append({'name': 'Has compute method', 'passed': False, 'error': str(e)})
        all_passed = all(t['passed'] for t in tests)
        return {'class': 'BHMFEvolutionModel', 'tests': tests, 'passed': sum(1 for t in tests if t['passed']), 'total': len(tests), 'all_passed': all_passed}

    # === 8 UQFF MASTER EQUATIONS (Auto-added) ===

    def compute_UQFF_base(self, r=None, t=0):
        """UQFF Base: F_U = Ug1 + Ug2 + Ug3 + Ug4 - Ub + Ui"""
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        Ug = dpm_ug1_seed(M, r)
        return {'Ug': Ug, 'F_U': Ug, 'equation': f"F_U = G*M/r^2 = {Ug:.3e} m/s^2"}

    def compute_compressed_equation(self, r=None):
        """Compressed MUGE gravity equation"""
        import numpy as np
        G, H_0 = _URP_G, 2.268e-18
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_N = dpm_ug1_seed(M, r)
        g_H = H_0**2 * r
        g = g_N - g_H
        return {'g_compressed': g, 'g_N': g_N, 'g_Hubble': g_H}

    def compute_resonance_equation(self, r=None, t=0):
        """Resonance MUGE with frequency modes"""
        import numpy as np
        G, H_0, c = _URP_G, 2.268e-18, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        aDPM = dpm_ug1_seed(M, r)
        aExpFreq = H_0 * c * np.sin(H_0 * t)
        return {'g_resonance': aDPM + aExpFreq, 'aDPM': aDPM, 'aExpFreq': aExpFreq}

    def compute_superconductive_equation(self, T=None, T_c=None):
        """Superconductive coefficient H_SCm"""
        T = T if T else getattr(self, 'T', 4.2)
        T_c = T_c if T_c else getattr(self, 'T_c', 9.2)
        H_SCm = max(0, 1 - (T / T_c)**4) if T < T_c else 0
        return {'H_SCm': H_SCm, 'T': T, 'T_c': T_c}

    def compute_buoyant_equation(self, r=None, V=None):
        """Buoyancy component Ub"""
        import numpy as np
        G, rho_vac = _URP_G, _RHO_VAC_UA
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        if V is None: V = (4/3) * np.pi * r**3
        g = dpm_ug1_seed(M, r)
        Ub = (rho_vac * V * g) / M
        return {'Ub': Ub, 'g': g, 'V': V}

    def compute_master_buoyant_equation(self, r=None, v=0):
        """Master Buoyant: F_U_Bi_i = M * (Ug_i - Ub_i + Ui_i)"""
        import numpy as np
        G, rho_vac, k_eta, c = _URP_G, _RHO_VAC_UA, 1e-113, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        V = (4/3) * np.pi * r**3
        Ug = dpm_ug1_seed(M, r)
        Ub = (rho_vac * V * Ug) / M
        Ui = -k_eta * rho_vac * V * (v / c)**2
        a_net = Ug - Ub + Ui
        return {'F_U_Bi_i': M * a_net, 'Ug': Ug, 'Ub': Ub, 'Ui': Ui, 'a_net': a_net}

    def compute_triadic_equation(self, r=None):
        """Triadic gravity: g_matter + g_field + g_vacuum"""
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_matter = dpm_ug1_seed(M, r)
        g_field, g_vacuum = 1e-15, 1e-20
        return {'g_triadic': g_matter + g_field + g_vacuum, 'g_matter': g_matter}

    def compute_quadratic_equation(self, r=None):
        """Quadratic polynomial fit: g = a*r^2 + b*r + c"""
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        # DPM-seeded: mu_s x grad(M_s/r) base (Newtonian form is emergent, not foundational)
        g_base = dpm_ug1_seed(M, r)
        a, b, c = -1e-30, 1e-20, g_base
        return {'g_quad': a * r**2 + b * r + c, 'a': a, 'b': b, 'c': c}

    def long_form_solution(self, r=None, t=0):
        """
        Long-form solution with complete equation display.
        Returns detailed step-by-step calculation for all UQFF equations.
        """
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        # Collect all equation results
        results = {}
        steps = []
        # 1. UQFF Base
        uqff = self.compute_UQFF_base(r, t)
        results['UQFF_base'] = uqff
        steps.append(f"UQFF Base: F_U = G*M/r^2 = {uqff['Ug']:.6e} m/s^2")
        # 2. Compressed equation
        comp = self.compute_compressed_equation(r)
        results['compressed'] = comp
        steps.append(f"Compressed: g = g_N - g_H = {comp['g_compressed']:.6e} m/s^2")
        # 3. Resonance equation
        res = self.compute_resonance_equation(r, t)
        results['resonance'] = res
        steps.append(f"Resonance: g_res = aDPM + aExpFreq = {res['g_resonance']:.6e} m/s^2")
        # 4. Superconductive
        sc = self.compute_superconductive_equation()
        results['superconductive'] = sc
        steps.append(f"Superconductive: H_SCm = {sc['H_SCm']:.6f}")
        # 5. Buoyant equation
        buoy = self.compute_buoyant_equation(r)
        results['buoyant'] = buoy
        steps.append(f"Buoyancy: Ub = {buoy['Ub']:.6e} m/s^2")
        # 6. Master buoyant
        master = self.compute_master_buoyant_equation(r)
        results['master_buoyant'] = master
        steps.append(f"Master Buoyant: F_U_Bi_i = {master['F_U_Bi_i']:.6e} N")
        # 7. Triadic
        tri = self.compute_triadic_equation(r)
        results['triadic'] = tri
        steps.append(f"Triadic: g_triadic = {tri['g_triadic']:.6e} m/s^2")
        # 8. Quadratic
        quad = self.compute_quadratic_equation(r)
        results['quadratic'] = quad
        steps.append(f"Quadratic: g_quad = {quad['g_quad']:.6e} m/s^2")
        return {
            'model': self.__class__.__name__,
            'parameters': {'M': M, 'r': r, 't': t},
            'results': results,
            'long_form': '\n'.join(steps)
        }

    def compute_master_gravity(self, r=None, t=0, include_all=True):
        """
        Master Gravity: Complete UQFF gravity computation.
        g_master = g_N * (1 - Ub/g_N + Ui/g_N) * H_SCm * fTRZ
        Combines: Newtonian, buoyancy, inertia, superconductivity, triadic zone
        """
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        # DPM-seeded: Newtonian form is emergent, not foundational\r\n
        g_N = dpm_ug1_seed(M, r)
        # Get buoyancy correction
        buoy = self.compute_buoyant_equation(r)
        Ub = buoy['Ub']
        # Get superconductive coefficient
        sc = self.compute_superconductive_equation()
        H_SCm = sc['H_SCm']
        # Get triadic factor (default: in resonance zone)
        fTRZ = 1.0
        # Compute master gravity
        if g_N != 0:
            correction = 1 - Ub / g_N
        else:
            correction = 1.0
        g_master = g_N * correction * max(0.01, H_SCm) * fTRZ
        # Collect additional terms if requested
        if include_all:
            comp = self.compute_compressed_equation(r)
            res = self.compute_resonance_equation(r, t)
            tri = self.compute_triadic_equation(r)
            return {
                'g_master': g_master,
                'g_N': g_N,
                'Ub': Ub,
                'H_SCm': H_SCm,
                'fTRZ': fTRZ,
                'correction': correction,
                'g_compressed': comp['g_compressed'],
                'g_resonance': res['g_resonance'],
                'g_triadic': tri['g_triadic'],
                'equation': f"g_master = g_N * (1 - Ub/g_N) * H_SCm * fTRZ = {g_master:.6e} m/s^2"
            }
        return {'g_master': g_master, 'g_N': g_N}

