class BondiAccretionModel(SelfSimulatingExpandingMixin):
    """

    Bondi-Hoyle-Lyttleton Accretion Model

    Models spherical accretion of ambient gas onto a massive object,

    fundamental for SMBH feeding in galaxy centers.

    KEY EQUATION:

    -----------------------------------------------------------------------------

    ? = 4p � ?_8 � (GM/v_8�)� � v_8

    Simplified form:

    ? = 4p � ? � ?_8 � (GM)� / c_s�

    Where:

        ? : Accretion rate (kg/s or M_?/yr)
        ?_8 : Ambient gas density (kg/m�)
        v_8 : Relative velocity of gas (m/s)
        c_s : Sound speed (m/s)
        ? : Dimensionless factor (~0.25-1)
        G, M : Gravitational constant, BH mass

    PHYSICAL SCALES:

    -----------------------------------------------------------------------------

    Bondi radius: r_B = GM/c_s� (where BH gravity dominates)

    For M = 108 M_?, T = 107 K (hot halo):

    - r_B ~ 100 pc

    - ?_Bondi ~ 0.01-1 M_?/yr

    �2025 Daniel T. Murphy - All Rights Reserved

    """

    def __init__(self):

        self.G = _URP_G         # Gravitational constant
        self.M_sun = 1.989e30      # Solar mass (kg)
        self.k_B = 1.381e-23       # Boltzmann constant
        self.m_p = 1.673e-27       # Proton mass (kg)
        self.yr_s = 3.156e7        # Seconds per year

    def compute_sound_speed(self, T: float, mu: float = 0.6) -> Tuple[float, str]:
        """
        Compute sound speed in hot gas.
        c_s = v(? k_B T / (� m_p))
        Args:
            T: Temperature (K)
            mu: Mean molecular weight (0.6 for ionized H/He)
        Returns:
            c_s: Sound speed (m/s)
            steps: Calculation explanation
        """
        import math
        gamma = 5/3  # Monatomic ideal gas
        c_s = math.sqrt(gamma * self.k_B * T / (mu * self.m_p))
        steps = f"""Sound Speed:


  c_s = v(? k_B T / (� m_p))


  Parameters:

    T = {T:.4e} K

    ? = {gamma}

    � = {mu}


  Result:

    c_s = v({gamma} � {self.k_B:.4e} � {T:.4e} / ({mu} � {self.m_p:.4e}))

    c_s = {c_s:.4e} m/s = {c_s/1e3:.1f} km/s

"""

        return c_s, steps

    def compute_bondi_radius(self, M: float, c_s: float) -> Tuple[float, str]:
        """
        Compute Bondi radius.
        Args:
            M: Black hole mass (kg)
            c_s: Sound speed (m/s)
        Returns:
            r_B: Bondi radius (m)
            steps: Calculation explanation
        """
        r_B = dpm_ug1_seed(M, c_s)
        pc = 3.086e16  # parsec in meters
        steps = f"""Bondi Radius:


  r_B = GM / c_s�

  r_B = {self.G:.4e} � {M:.4e} / {c_s:.4e}�

  r_B = {r_B:.4e} m = {r_B/pc:.2f} pc


  Inside r_B, BH gravity dominates over thermal pressure.

"""

        return r_B, steps

    def compute_accretion_rate(self, M: float, rho_inf: float, 

                               c_s: float = None, v_inf: float = None,
                               T: float = None) -> Tuple[float, str]:
        """
        Compute Bondi accretion rate.
        Args:
            M: Black hole mass (kg)
            rho_inf: Ambient density (kg/m�)
            c_s: Sound speed (m/s), optional
            v_inf: Relative velocity (m/s), optional
            T: Temperature (K), to compute c_s if not given
        Returns:
            M_dot: Accretion rate (M_?/yr)
            steps: Calculation explanation
        """
        import math
        if c_s is None:
            if T is not None:
                c_s, _ = self.compute_sound_speed(T)
            else:
                c_s = 300e3  # Default 300 km/s for hot gas
        if v_inf is None:
            v_inf = c_s  # Subsonic limit
        # ? = 4p � ?_8 � (GM)� / (c_s� + v_8�)^(3/2)
        v_eff = math.sqrt(c_s**2 + v_inf**2)
        M_dot_SI = 4 * math.pi * rho_inf * (self.G * M)**2 / v_eff**3
        # Convert to M_?/yr
        M_dot = M_dot_SI * self.yr_s / self.M_sun
        # Compare to Eddington rate
        M_dot_Edd = 4 * math.pi * self.G * M * self.m_p / (0.1 * 6.652e-29 * 2.998e8)
        M_dot_Edd_yr = M_dot_Edd * self.yr_s / self.M_sun
        steps = f"""Bondi Accretion Rate:


  ? = 4p � ?_8 � (GM)� / v_eff�


  Parameters:

    M = {M:.4e} kg = {M/self.M_sun:.2e} M_?

    ?_8 = {rho_inf:.4e} kg/m�

    c_s = {c_s:.4e} m/s = {c_s/1e3:.1f} km/s

    v_8 = {v_inf:.4e} m/s

    v_eff = v(c_s� + v_8�) = {v_eff:.4e} m/s


  Result:

    ? = {M_dot_SI:.4e} kg/s = {M_dot:.4e} M_?/yr


  Eddington rate: ?_Edd � {M_dot_Edd_yr:.4e} M_?/yr

  ?/?_Edd � {M_dot/M_dot_Edd_yr:.4f}

"""

        return M_dot, steps

    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Bondi Accretion Model."""
        import math
        tests = []
        all_passed = True
        # Test 1: Sound speed at 107 K ~ 500 km/s
