    def compute(self, dataset: dict) -> dict:
        """UQFF Virgo gravitational potential (NFW form + UQFF SCm correction)."""
        import math
        M_vir_Msun = 1.28e15
        c_vir = 9.9519
        r_kpc = dataset.get('r_kpc', 500.0)
