        g_expected = 3.160e-5
        ratio6 = g_clean / g_expected
        t6 = 0.99 < ratio6 < 1.01
        tests.append(f"Test 6: g_clean = {g_clean:.4e} / {g_expected:.3e} = {ratio6:.4f} ? [0.99, 1.01]: {'PASS' if t6 else 'FAIL'}")
        all_passed &= t6
        # Test 7: EM dominates total (>99%)
        em_fraction = a_EM / g_clean
        t7 = em_fraction > 0.99
