        tests.append(f"Test 6: g_NGC1792 = {g_total:.4e} / {expected_g_total:.4e} = {ratio6:.4f} ? [0.99, 1.01]: {'PASS' if pass6 else 'FAIL'}")
        passed_count += int(pass6)
        # Test 7: EM dominance (>99% of total)
        EM_fraction = a_EM / g_total
        pass7 = EM_fraction > 0.99
        tests.append(f"Test 7: EM fraction = {EM_fraction:.6f} > 0.99: {'PASS' if pass7 else 'FAIL'}")
        passed_count += int(pass7)
        # Test 8: F_sn bounds
        _, _ = self.compute_F_sn(self.t_current)
        F_sn = self.F_sn_0 * (1 - math.exp(-1))
