        self.f_TRZ = f_TRZ if f_TRZ is not None else 0.1
        self.N_stars = N_stars if N_stars is not None else CONSTANTS.get('M16_N_stars', 20)
        self.L_O_star = L_O_star if L_O_star is not None else CONSTANTS.get('M16_L_O_star', 3.828e31)
        # Erosion parameters (radiation from O-type stars)
