class CrabNebulaModel(SelfSimulatingExpandingMixin):
    """

    Crab Nebula Model - Pulsar-Driven Supernova Remnant

    The Crab Nebula (M1, NGC 1952) is a supernova remnant in Taurus, located

    ~6,500 light-years away. The nebula is the remnant of a supernova observed

    in 1054 AD, driven by a central pulsar (neutron star) spinning at 30.2 Hz.

    KEY EQUATIONS:

    -----------------------------------------------------------------------------

    Master UQFF Equation:

    g_Crab(r, t) = g_grav � (1 + H(z)�t) � (1 + f_TRZ) + a_wind + M_mag

    Where:

        g_grav  = G�M/r�           Base gravitational acceleration
        H(z)    = H_0�v(O_m(1+z)� + O_?)  Hubble parameter at redshift z
        f_TRZ   = 0.1              Time-reversal zone correction
        a_wind  = P_rad/s � scale  Pulsar wind-driven acceleration
        M_mag   = q(v�B)/m_e � scale  Magnetic acceleration

    DOCUMENT BENCHMARKS (t = 971 years since 1054 AD):

    -----------------------------------------------------------------------------

        g_grav         = 2.258e-13 m/s�
        Hubble factor  = 1 + H(z)�t = 1.00000007
        a_wind         = 1.481e6 m/s�
        M_mag          = 2.638e-3 m/s�
        g_Crab (total) = 1.481e6 m/s� (pulsar wind dominated)

    PHYSICAL PARAMETERS:

    -----------------------------------------------------------------------------

        M_total     = 4.6 M_sun (pulsar 1.4 M_sun + ejecta 3.2 M_sun)
        r           = 5.2�10�6 m (5.5 light-years radius)
        v_exp       = 1500 km/s (expansion velocity)
        P_pulsar    = 5�10�� W (pulsar luminosity)
        B_nebula    = 10?8 T (average), 10?4 T (near pulsar)
        f_spin      = 30.2 Hz (pulsar rotation rate)
        ?_filament  = 10?�� kg/m� (filament density)

    APPLICATIONS:

    -----------------------------------------------------------------------------

    - Pulsar wind nebula (PWN) dynamics

    - Synchrotron radiation modeling

    - Supernova remnant evolution

    - Neutron star physics

    - High-energy astrophysics

    AUTHOR:

    -----------------------------------------------------------------------------

    Copyright � Daniel T. Murphy, 2025

    Grok 3 DeepSearch analysis, May 09, 2025

    Location: Youngstown, OH, USA (41.0997� N, 80.6495� W)

    """

    def __init__(self, M=None, r=None, P_pulsar=None, v_exp=None, B=None, 

                 rho_filament=None, t_age=None, z=None, f_TRZ=0.1, spin_Hz=30.2):
        """
        Initialize Crab Nebula Model with configurable parameters.
        Args:
            M: Total mass in kg (default: 9.15e30 = 4.6 M_sun)
            r: Nebula radius in m (default: 5.2e16 = 5.5 ly)
            P_pulsar: Pulsar luminosity in W (default: 5e31)
            v_exp: Expansion velocity in m/s (default: 1.5e6 = 1500 km/s)
            B: Average magnetic field in T (default: 1e-8)
            rho_filament: Filament density in kg/m� (default: 1e-21)
            t_age: Age since supernova in s (default: 3.064e10 = 971 yr)
            z: Redshift (default: 0.0015)
            f_TRZ: Time-reversal zone factor (default: 0.1)
            spin_Hz: Pulsar spin frequency in Hz (default: 30.2)
        """
        import math
        # Physical constants
        self.G = _URP_G         # Gravitational constant (m�/kg/s�)
        self.c = 2.998e8            # Speed of light (m/s)
        self.H_0 = 2.268e-18        # Hubble constant (s?�) = 70 km/s/Mpc
        self.Omega_m = 0.3          # Matter density parameter
        self.Omega_Lambda = 0.7     # Dark energy density parameter
        self.q_e = 1.602e-19        # Electron charge (C)
        self.m_e = 9.109e-31        # Electron mass (kg)
        self.M_sun = 1.989e30       # Solar mass (kg)
        # UQFF vacuum densities
        self.rho_vac_UA = CONSTANTS.get('rho_vac_UA', _RHO_VAC_UA)     # UA vacuum (kg/m�)
        self.rho_vac_SCm = CONSTANTS.get('rho_vac_SCm', _RHO_VAC_SCM)   # SCm vacuum (kg/m�)
        # System parameters (with CONSTANTS fallbacks)
        self.M = M if M is not None else CONSTANTS.get('Crab_M', 9.15e30)
        self.r = r if r is not None else CONSTANTS.get('Crab_r', 5.2e16)
        self.P_pulsar = P_pulsar if P_pulsar is not None else CONSTANTS.get('Crab_P_pulsar', 5e31)
        self.v_exp = v_exp if v_exp is not None else CONSTANTS.get('Crab_v_exp', 1.5e6)
        self.B = B if B is not None else CONSTANTS.get('Crab_B_avg', 1e-8)
        self.B_pulsar = CONSTANTS.get('Crab_B', 1e-4)  # Near pulsar
        self.rho_filament = rho_filament if rho_filament is not None else CONSTANTS.get('Crab_rho_filament', 1e-21)
        self.t_age = t_age if t_age is not None else CONSTANTS.get('Crab_t_age', 3.064e10)
        self.z = z if z is not None else CONSTANTS.get('Crab_z', 0.0015)
        self.f_TRZ = f_TRZ
        self.spin_Hz = spin_Hz if spin_Hz is not None else CONSTANTS.get('Crab_spin_Hz', 30.2)
        # Pulsar parameters
        self.M_pulsar = CONSTANTS.get('Crab_M_pulsar', 2.78e30)     # 1.4 M_sun
        self.M_ejecta = CONSTANTS.get('Crab_M_ejecta', 6.36e30)     # 3.2 M_sun
        self.r_pulsar = CONSTANTS.get('Crab_r_pulsar', 1.5e4)       # 15 km
        self.r_shock = CONSTANTS.get('Crab_r_shock', 3e15)          # 0.1 pc
        self.spin_slowdown = CONSTANTS.get('Crab_spin_slowdown', 3.8e-10)  # Hz/s
        # Derived quantities
        self.omega_pulsar = 2 * math.pi * self.spin_Hz  # Angular frequency (rad/s)
        self.sigma_column = self.rho_filament * self.r   # Column density (kg/m�)
        # Document reference values (May 2025)
        self.g_grav_doc = CONSTANTS.get('g_grav_Crab', 2.258e-13)
        self.a_wind_doc = CONSTANTS.get('a_wind_Crab', 1.481e6)
        self.M_mag_doc = CONSTANTS.get('M_mag_Crab', 2.638e-3)
        self.g_total_doc = CONSTANTS.get('g_Crab_total', 1.481e6)

    def compute_H_z(self):
        """
        Compute Hubble parameter at redshift z.
        H(z) = H_0 � v(O_m(1+z)� + O_?)
        Returns:
            H(z) in s?�
        """
        import math
        factor = self.Omega_m * (1 + self.z)**3 + self.Omega_Lambda
        return self.H_0 * math.sqrt(factor)

    def compute_hubble_correction(self, t=None):
        """
        Compute Hubble expansion correction factor (1 + H(z)�t).
        At z = 0.0015, t = 971 years: factor � 1.00000007 (negligible)
        Args:
            t: Time in seconds (default: t_age)
        Returns:
            Correction factor (1 + H(z)�t)
        """
        if t is None:
            t = self.t_age
        H_z = self.compute_H_z()
        return 1.0 + H_z * t

    def compute_g_grav(self, r=None):
        """
        Compute base gravitational acceleration.
        g_grav = G � M / r�
        Document value: g_grav = 2.258e-13 m/s�
        Args:
            r: Radius in m (default: self.r)
        Returns:
            Gravitational acceleration in m/s�
        """
        if r is None:
            r = self.r
        return dpm_ug1_seed(self.M, r)

    def compute_a_wind(self, r=None):
        """
        Compute pulsar wind-driven acceleration.
        The pulsar emits a relativistic wind with luminosity P_pulsar,
        creating radiation pressure that accelerates nebular material.
        P_rad = P_pulsar / (4pr�c)     [N/m� radiation pressure]
        s = ? � r                       [kg/m� column density]
        a_wind_raw = P_rad / s � (1 + v_exp/c)  [m/s�]
        a_wind = a_wind_raw � 10^12     [scaled to macroscopic effects]
        Document value: a_wind = 1.481e6 m/s�
        Args:
            r: Radius in m (default: self.r)
        Returns:
            Wind acceleration in m/s�
        """
        if r is None:
            r = self.r
        # Radiation pressure from pulsar luminosity
        # P_rad = L / (4pr�c) for photon pressure
        # Document uses P_rad = L / (4pr�) for simplified flux
        A_sphere = 4 * 3.141592653589793 * r * r
        F_rad = self.P_pulsar / A_sphere  # Energy flux (W/m�)
        # Relativistic correction factor
        rel_factor = 1.0 + self.v_exp / self.c  # 1.005
        # Column density
        sigma = self.rho_filament * r  # kg/m�
        # Document approach: F_rad / sigma to get acceleration dimension
        # But F_rad is W/m� = J/s/m�. Need conversion to N/m�.
        # P_rad = F_rad / c gives radiation pressure in N/m�
        # But document uses F_rad directly with different scaling.
        # Following document's approach:
        # F_wind = (P_pulsar / (4pr�)) � (1 + v/c) = 1.481e-3 N/m�
        F_wind = F_rad * rel_factor  # J/s/m� (Power flux, not force)
        # To convert to acceleration, document divides by density:
        # a = F_wind / rho = 1.481e-3 / 1e-21 = 1.481e18 m/s�
        # Then scales by 10^-12 for "macroscopic effects"
        a_wind_raw = F_wind / self.rho_filament
        a_wind_scaled = a_wind_raw * 1e-12
        return a_wind_scaled

    def compute_M_mag(self, v=None, B=None):
        """
        Compute magnetic field acceleration on charged particles.
        M_mag = q(v � B) / m_e � scale
        Where scale = 10^-12 for macroscopic effects.
        Document value: M_mag = 2.638e-3 m/s�
        Args:
            v: Velocity in m/s (default: v_exp = 1.5e6)
            B: Magnetic field in T (default: B_avg = 1e-8)
        Returns:
            Magnetic acceleration in m/s�
        """
        if v is None:
            v = self.v_exp
        if B is None:
            B = self.B
        # Lorentz force on electron
        F_lorentz = self.q_e * v * B  # N
        # Acceleration
        a_raw = F_lorentz / self.m_e  # m/s�
        # Scale for macroscopic effects
        a_scaled = a_raw * 1e-12
        return a_scaled

    def compute_a_EM_with_UA(self, v=None, B=None):
        """
        Compute electromagnetic acceleration with UQFF UA correction.
        a_EM = q(v � B) / m_p � (1 + U_UA/U_SCm) � scale
        Uses proton mass for ion dynamics (more relevant for macroscopic
        nebular dynamics than electron mass).
        Args:
            v: Velocity in m/s (default: v_exp)
            B: Magnetic field in T (default: B_avg)
        Returns:
            EM acceleration with UA correction in m/s�
        """
        if v is None:
            v = self.v_exp
        if B is None:
            B = self.B
        m_p = 1.673e-27  # Proton mass (kg)
        # UA correction factor
        UA_factor = 1.0 + self.rho_vac_UA / self.rho_vac_SCm  # ~11
        # Lorentz force on ion
        F_lorentz = self.q_e * v * B  # N
        # Acceleration with UA
        a_EM = (F_lorentz / m_p) * UA_factor
        # Scale for macroscopic effects
        a_EM_scaled = a_EM * 1e-12
        return a_EM_scaled

    def compute_clean_equation(self, t=None, r=None):
        """
        Compute the clean UQFF master equation for Crab Nebula evolution.
        g_Crab(r, t) = g_grav � (1 + H(z)�t) � (1 + f_TRZ) + a_wind + M_mag
        This equation captures:
        - Base gravitational acceleration (negligible at ~10?��)
        - Hubble expansion correction (negligible for local object)
        - Time-reversal zone correction
        - Pulsar wind-driven acceleration (DOMINANT at ~106)
        - Magnetic field acceleration on particles
        Document g_Crab = 1.481e6 m/s� (pulsar wind dominated)
        Args:
            t: Time in seconds (default: t_age = 971 years)
            r: Radius in m (default: 5.2e16 m)
        Returns:
            dict with all computed values and final g_Crab
        """
        if t is None:
            t = self.t_age
        if r is None:
            r = self.r
        # Base gravitational term
        g_grav = self.compute_g_grav(r)
        # Hubble expansion correction
        hubble_factor = self.compute_hubble_correction(t)
        # Time-reversal zone correction
        trz_factor = 1.0 + self.f_TRZ
        # Gravitational term with all corrections
        g_grav_corrected = g_grav * hubble_factor * trz_factor
        # Pulsar wind acceleration
        a_wind = self.compute_a_wind(r)
        # Magnetic acceleration
        M_mag = self.compute_M_mag()
        # Final clean equation
        g_Crab = g_grav_corrected + a_wind + M_mag
        # Fraction analysis
        wind_fraction = a_wind / g_Crab if g_Crab > 0 else 0.0
        mag_fraction = M_mag / g_Crab if g_Crab > 0 else 0.0
        grav_fraction = g_grav_corrected / g_Crab if g_Crab > 0 else 0.0
        return {
            'g_grav': g_grav,
            'hubble_factor': hubble_factor,
            'trz_factor': trz_factor,
            'g_grav_corrected': g_grav_corrected,
            'a_wind': a_wind,
            'M_mag': M_mag,
            'g_Crab': g_Crab,
            'wind_fraction': wind_fraction,
            'mag_fraction': mag_fraction,
            'grav_fraction': grav_fraction
        }

    def compute_pulsar_properties(self):
        """
        Compute pulsar (neutron star) properties.
        Returns:
            dict with pulsar physics
        """
        import math
        # Rotation energy
        # E_rot = (1/2) I ?� where I � (2/5) M R� for uniform sphere
        I_pulsar = 0.4 * self.M_pulsar * self.r_pulsar**2  # kg m�
        E_rot = 0.5 * I_pulsar * self.omega_pulsar**2  # J
        # Spin-down luminosity (energy loss rate)
        # dE/dt = I � ? � d?/dt = I � ? � 2p � df/dt
        dw_dt = 2 * math.pi * self.spin_slowdown  # rad/s�
        L_spindown = I_pulsar * self.omega_pulsar * abs(dw_dt)  # W
        # Characteristic age (t = f / (2 � df/dt))
        tau_char = self.spin_Hz / (2 * abs(self.spin_slowdown))  # s
        tau_char_yr = tau_char / (3.156e7)  # years
        # Surface magnetic field estimate (from spin-down)
        # B_surface � 3.2e19 � v(P � dP/dt) Gauss
        P_spin = 1.0 / self.spin_Hz  # Period in s
        dP_dt = self.spin_slowdown / (self.spin_Hz**2)  # Period derivative
        B_surface_gauss = 3.2e19 * math.sqrt(abs(P_spin * dP_dt))
        B_surface_T = B_surface_gauss * 1e-4  # Convert to Tesla
        # Light cylinder radius (where v = c)
        r_light = self.c / self.omega_pulsar  # m
        # Goldreich-Julian charge density
        # n_GJ = O�B / (2pce) for aligned rotator
        n_GJ = self.omega_pulsar * self.B_pulsar / (2 * math.pi * self.c * self.q_e)  # m?�
        return {
            'I_pulsar': I_pulsar,
            'E_rot_J': E_rot,
            'E_rot_erg': E_rot * 1e7,  # Convert to erg
            'L_spindown_W': L_spindown,
            'L_spindown_erg_s': L_spindown * 1e7,
            'tau_char_s': tau_char,
            'tau_char_yr': tau_char_yr,
            'B_surface_T': B_surface_T,
            'B_surface_gauss': B_surface_gauss,
            'r_light_m': r_light,
            'r_light_km': r_light / 1e3,
            'n_GJ_m3': n_GJ,
            'P_spin_ms': P_spin * 1e3,  # Period in milliseconds
            'omega_rad_s': self.omega_pulsar
        }

    def compute_nebula_properties(self):
        """
        Compute nebula expansion and structure properties.
        Returns:
            dict with nebula physics
        """
        import math
        # Expansion timescale
        t_exp = self.r / self.v_exp  # s
        t_exp_yr = t_exp / (3.156e7)  # years
        # Kinetic energy of expanding ejecta
        E_kin = 0.5 * self.M_ejecta * self.v_exp**2  # J
        E_kin_erg = E_kin * 1e7  # erg
        # Energy from supernova (typical � 105� erg)
        E_SN_typical = 1e44  # J (105� erg)
        # Volume and average density
        V_nebula = (4/3) * math.pi * self.r**3  # m�
        rho_avg = self.M / V_nebula  # kg/m�
        # Synchrotron cooling time (for electrons in magnetic field)
        # t_sync = 6pm_e c / (s_T B� ?) � simplified estimate
        sigma_T = 6.652e-29  # Thomson cross-section (m�)
        gamma_typical = 1e6  # Typical Lorentz factor
        t_sync = (6 * math.pi * self.m_e * self.c) / (sigma_T * self.B**2 * gamma_typical)
        t_sync_yr = t_sync / (3.156e7)
        # Sound speed in nebula (assume T ~ 10^4 K, fully ionized)
        T_nebula = 1e4  # K
        k_B = 1.381e-23  # J/K
        m_H = 1.673e-27  # kg
        mu = 0.6  # Mean molecular weight (ionized)
        c_s = math.sqrt(k_B * T_nebula / (mu * m_H))  # m/s
        # Mach number
        mach = self.v_exp / c_s
        return {
            'r_m': self.r,
            'r_ly': self.r / 9.461e15,
            'v_exp_m_s': self.v_exp,
            'v_exp_km_s': self.v_exp / 1e3,
            't_exp_s': t_exp,
            't_exp_yr': t_exp_yr,
            'E_kin_J': E_kin,
            'E_kin_erg': E_kin_erg,
            'V_nebula_m3': V_nebula,
            'rho_avg_kg_m3': rho_avg,
            't_sync_s': t_sync,
            't_sync_yr': t_sync_yr,
            'c_sound_m_s': c_s,
            'mach_number': mach,
            'T_nebula_K': T_nebula
        }

    def compute_synchrotron_properties(self):
        """
        Compute synchrotron radiation properties.
        The Crab Nebula is famous for its synchrotron radiation
        from relativistic electrons spiraling in the magnetic field.
        Returns:
            dict with synchrotron physics
        """
        import math
        # Critical synchrotron frequency
        # ?_c = (3/2) ?� (eB / 2pm_e c)
        gamma_typical = 1e6  # Typical electron Lorentz factor
        nu_cyclotron = self.q_e * self.B / (2 * math.pi * self.m_e)  # Cyclotron frequency (Hz)
        nu_sync = 1.5 * gamma_typical**2 * nu_cyclotron  # Synchrotron frequency (Hz)
        # Synchrotron power from single electron
        # P_sync = (s_T c / 6p) � B� � ?�
        sigma_T = 6.652e-29  # Thomson cross-section (m�)
        P_sync = (sigma_T * self.c / (6 * math.pi)) * self.B**2 * gamma_typical**2
        # Total synchrotron luminosity (rough estimate)
        # Assume N_e ~ 10^50 electrons
        N_e_estimate = 1e50
        L_sync_total = N_e_estimate * P_sync  # W
        # Photon energy
        h = 6.626e-34  # Planck constant (J s)
        E_photon = h * nu_sync  # J
        E_photon_keV = E_photon / (1.602e-16)  # keV
        # Magnetic energy density
        U_B = self.B**2 / (2 * 4 * math.pi * 1e-7)  # J/m� (SI)
        return {
            'nu_cyclotron_Hz': nu_cyclotron,
            'nu_sync_Hz': nu_sync,
            'nu_sync_GHz': nu_sync / 1e9,
            'P_sync_single_W': P_sync,
            'L_sync_total_W': L_sync_total,
            'L_sync_total_erg_s': L_sync_total * 1e7,
            'E_photon_J': E_photon,
            'E_photon_keV': E_photon_keV,
            'U_B_J_m3': U_B,
            'gamma_electron': gamma_typical
        }

    def validate_model(self):
        """
        Validate model outputs against document reference values.
        Returns:
            dict with validation results and pass/fail status
        """
        results = self.compute_clean_equation()
        # Compare to document values
        g_grav_ratio = results['g_grav'] / self.g_grav_doc if self.g_grav_doc != 0 else float('inf')
        a_wind_ratio = results['a_wind'] / self.a_wind_doc if self.a_wind_doc != 0 else float('inf')
        M_mag_ratio = results['M_mag'] / self.M_mag_doc if self.M_mag_doc != 0 else float('inf')
        g_total_ratio = results['g_Crab'] / self.g_total_doc if self.g_total_doc != 0 else float('inf')
        # Tolerance bounds (�1%)
        tol_low, tol_high = 0.99, 1.01
        validations = {
            'g_grav': {
                'computed': results['g_grav'],
                'document': self.g_grav_doc,
                'ratio': g_grav_ratio,
                'passed': tol_low <= g_grav_ratio <= tol_high
            },
            'a_wind': {
                'computed': results['a_wind'],
                'document': self.a_wind_doc,
                'ratio': a_wind_ratio,
                'passed': tol_low <= a_wind_ratio <= tol_high
            },
            'M_mag': {
                'computed': results['M_mag'],
                'document': self.M_mag_doc,
                'ratio': M_mag_ratio,
                'passed': tol_low <= M_mag_ratio <= tol_high
            },
            'g_Crab': {
                'computed': results['g_Crab'],
                'document': self.g_total_doc,
                'ratio': g_total_ratio,
                'passed': tol_low <= g_total_ratio <= tol_high
            }
        }
        all_passed = all(v['passed'] for v in validations.values())
        return {
            'validations': validations,
            'all_passed': all_passed,
            'computed_results': results
        }

    @staticmethod

    def run_tests():
        """
        Run comprehensive test suite for CrabNebulaModel.
        Tests:
        1. g_grav computation (document: 2.258e-13)
        2. Hubble correction factor (1 + H(z)�t � 1.00000007)
        3. a_wind computation (document: 1.481e6)
        4. M_mag computation (document: 2.638e-3)
        5. g_Crab total (document: 1.481e6)
        6. Wind dominance (>99% of total)
        """
        model = CrabNebulaModel()
        results = model.compute_clean_equation()
        tests = []
        # Test 1: g_grav
        g_grav_expected = 2.258e-13
        g_grav_ratio = results['g_grav'] / g_grav_expected
        tests.append({
            'name': 'g_grav computation',
            'computed': results['g_grav'],
            'expected': g_grav_expected,
            'ratio': g_grav_ratio,
            'passed': 0.99 <= g_grav_ratio <= 1.01
        })
        # Test 2: Hubble correction
        hubble_expected = 1.00000007
        hubble_ratio = results['hubble_factor'] / hubble_expected
        tests.append({
            'name': 'Hubble (1+H(z)t)',
            'computed': results['hubble_factor'],
            'expected': hubble_expected,
            'ratio': hubble_ratio,
            'passed': 0.99 <= hubble_ratio <= 1.01
        })
        # Test 3: TRZ factor
        trz_expected = 1.1
        trz_ratio = results['trz_factor'] / trz_expected
        tests.append({
            'name': 'TRZ factor (1+f_TRZ)',
            'computed': results['trz_factor'],
            'expected': trz_expected,
            'ratio': trz_ratio,
            'passed': 0.99 <= trz_ratio <= 1.01
        })
        # Test 4: a_wind
        a_wind_expected = 1.481e6
        a_wind_ratio = results['a_wind'] / a_wind_expected
        tests.append({
            'name': 'a_wind computation',
            'computed': results['a_wind'],
            'expected': a_wind_expected,
            'ratio': a_wind_ratio,
            'passed': 0.99 <= a_wind_ratio <= 1.01
        })
        # Test 5: M_mag
        M_mag_expected = 2.638e-3
        M_mag_ratio = results['M_mag'] / M_mag_expected
        tests.append({
            'name': 'M_mag computation',
            'computed': results['M_mag'],
            'expected': M_mag_expected,
            'ratio': M_mag_ratio,
            'passed': 0.99 <= M_mag_ratio <= 1.01
        })
        # Test 6: g_Crab total
        g_total_expected = 1.481e6
        g_total_ratio = results['g_Crab'] / g_total_expected
        tests.append({
            'name': 'g_Crab total',
            'computed': results['g_Crab'],
            'expected': g_total_expected,
            'ratio': g_total_ratio,
            'passed': 0.99 <= g_total_ratio <= 1.01
        })
        # Test 7: Wind dominance
        wind_dom = results['wind_fraction'] > 0.99
        tests.append({
            'name': 'Wind dominance',
            'computed': results['wind_fraction'],
            'expected': '>0.99',
            'ratio': results['wind_fraction'],
            'passed': wind_dom
        })
        # Print results
        print(f"g_Crab = {results['g_Crab']:.4e}")
        print(f"CrabNebulaModel: {sum(1 for t in tests if t['passed'])}/{len(tests)} tests passed")
        for test in tests:
            status = "PASS" if test['passed'] else "FAIL"
            if isinstance(test['expected'], str):
                print(f"Test {tests.index(test)+1}: {test['name']} = {test['computed']:.4f} {test['expected']}: {status}")
            else:
                print(f"Test {tests.index(test)+1}: {test['name']} = {test['computed']:.4e} / {test['expected']:.4e} = {test['ratio']:.4f}: {status}")
        return {
            'tests': tests,
            'all_passed': all(t['passed'] for t in tests),
            'class': 'CrabNebulaModel',
            'g_final': results['g_Crab']
        }

    # === 8 UQFF MASTER EQUATIONS (Auto-added) ===

    def compute_UQFF_base(self, r=None, t=0):
        """UQFF Base: F_U = Ug1 + Ug2 + Ug3 + Ug4 - Ub + Ui"""
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        Ug = dpm_ug1_seed(M, r)
        return {'Ug': Ug, 'F_U': Ug, 'equation': f"F_U = G*M/r^2 = {Ug:.3e} m/s^2"}

    def compute_compressed_equation(self, r=None):
        """Compressed MUGE gravity equation"""
        import numpy as np
        G, H_0 = _URP_G, 2.268e-18
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_N = dpm_ug1_seed(M, r)
        g_H = H_0**2 * r
        g = g_N - g_H
        return {'g_compressed': g, 'g_N': g_N, 'g_Hubble': g_H}

    def compute_resonance_equation(self, r=None, t=0):
        """Resonance MUGE with frequency modes"""
        import numpy as np
        G, H_0, c = _URP_G, 2.268e-18, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        aDPM = dpm_ug1_seed(M, r)
        aExpFreq = H_0 * c * np.sin(H_0 * t)
        return {'g_resonance': aDPM + aExpFreq, 'aDPM': aDPM, 'aExpFreq': aExpFreq}

    def compute_superconductive_equation(self, T=None, T_c=None):
        """Superconductive coefficient H_SCm"""
        T = T if T else getattr(self, 'T', 4.2)
        T_c = T_c if T_c else getattr(self, 'T_c', 9.2)
        H_SCm = max(0, 1 - (T / T_c)**4) if T < T_c else 0
        return {'H_SCm': H_SCm, 'T': T, 'T_c': T_c}

    def compute_buoyant_equation(self, r=None, V=None):
        """Buoyancy component Ub"""
        import numpy as np
        G, rho_vac = _URP_G, _RHO_VAC_UA
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        if V is None: V = (4/3) * np.pi * r**3
        g = dpm_ug1_seed(M, r)
        Ub = (rho_vac * V * g) / M
        return {'Ub': Ub, 'g': g, 'V': V}

    def compute_master_buoyant_equation(self, r=None, v=0):
        """Master Buoyant: F_U_Bi_i = M * (Ug_i - Ub_i + Ui_i)"""
        import numpy as np
        G, rho_vac, k_eta, c = _URP_G, _RHO_VAC_UA, 1e-113, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        V = (4/3) * np.pi * r**3
        Ug = dpm_ug1_seed(M, r)
        Ub = (rho_vac * V * Ug) / M
        Ui = -k_eta * rho_vac * V * (v / c)**2
        a_net = Ug - Ub + Ui
        return {'F_U_Bi_i': M * a_net, 'Ug': Ug, 'Ub': Ub, 'Ui': Ui, 'a_net': a_net}

    def compute_triadic_equation(self, r=None):
        """Triadic gravity: g_matter + g_field + g_vacuum"""
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_matter = dpm_ug1_seed(M, r)
        g_field, g_vacuum = 1e-15, 1e-20
        return {'g_triadic': g_matter + g_field + g_vacuum, 'g_matter': g_matter}

    def compute_quadratic_equation(self, r=None):
        """Quadratic polynomial fit: g = a*r^2 + b*r + c"""
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        # DPM-seeded: mu_s x grad(M_s/r) base (Newtonian form is emergent, not foundational)
        g_base = dpm_ug1_seed(M, r)
        a, b, c = -1e-30, 1e-20, g_base
        return {'g_quad': a * r**2 + b * r + c, 'a': a, 'b': b, 'c': c}

    def long_form_solution(self, r=None, t=0):
        """
        Long-form solution with complete equation display.
        Returns detailed step-by-step calculation for all UQFF equations.
        """
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        # Collect all equation results
        results = {}
        steps = []
        # 1. UQFF Base
        uqff = self.compute_UQFF_base(r, t)
        results['UQFF_base'] = uqff
        steps.append(f"UQFF Base: F_U = G*M/r^2 = {uqff['Ug']:.6e} m/s^2")
        # 2. Compressed equation
        comp = self.compute_compressed_equation(r)
        results['compressed'] = comp
        steps.append(f"Compressed: g = g_N - g_H = {comp['g_compressed']:.6e} m/s^2")
        # 3. Resonance equation
        res = self.compute_resonance_equation(r, t)
        results['resonance'] = res
        steps.append(f"Resonance: g_res = aDPM + aExpFreq = {res['g_resonance']:.6e} m/s^2")
        # 4. Superconductive
        sc = self.compute_superconductive_equation()
        results['superconductive'] = sc
        steps.append(f"Superconductive: H_SCm = {sc['H_SCm']:.6f}")
        # 5. Buoyant equation
        buoy = self.compute_buoyant_equation(r)
        results['buoyant'] = buoy
        steps.append(f"Buoyancy: Ub = {buoy['Ub']:.6e} m/s^2")
        # 6. Master buoyant
        master = self.compute_master_buoyant_equation(r)
        results['master_buoyant'] = master
        steps.append(f"Master Buoyant: F_U_Bi_i = {master['F_U_Bi_i']:.6e} N")
        # 7. Triadic
        tri = self.compute_triadic_equation(r)
        results['triadic'] = tri
        steps.append(f"Triadic: g_triadic = {tri['g_triadic']:.6e} m/s^2")
        # 8. Quadratic
        quad = self.compute_quadratic_equation(r)
        results['quadratic'] = quad
        steps.append(f"Quadratic: g_quad = {quad['g_quad']:.6e} m/s^2")
        return {
            'model': self.__class__.__name__,
            'parameters': {'M': M, 'r': r, 't': t},
            'results': results,
            'long_form': '\n'.join(steps)
        }

    def compute_master_gravity(self, r=None, t=0, include_all=True):
        """
        Master Gravity: Complete UQFF gravity computation.
        g_master = g_N * (1 - Ub/g_N + Ui/g_N) * H_SCm * fTRZ
        Combines: Newtonian, buoyancy, inertia, superconductivity, triadic zone
        """
        import numpy as np
        G = _URP_G
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        # DPM-seeded: Newtonian form is emergent, not foundational\r\n
        g_N = dpm_ug1_seed(M, r)
        # Get buoyancy correction
        buoy = self.compute_buoyant_equation(r)
        Ub = buoy['Ub']
        # Get superconductive coefficient
        sc = self.compute_superconductive_equation()
        H_SCm = sc['H_SCm']
        # Get triadic factor (default: in resonance zone)
        fTRZ = 1.0
        # Compute master gravity
        if g_N != 0:
            correction = 1 - Ub / g_N
        else:
            correction = 1.0
        g_master = g_N * correction * max(0.01, H_SCm) * fTRZ
        # Collect additional terms if requested
        if include_all:
            comp = self.compute_compressed_equation(r)
            res = self.compute_resonance_equation(r, t)
            tri = self.compute_triadic_equation(r)
            return {
                'g_master': g_master,
                'g_N': g_N,
                'Ub': Ub,
                'H_SCm': H_SCm,
                'fTRZ': fTRZ,
                'correction': correction,
                'g_compressed': comp['g_compressed'],
                'g_resonance': res['g_resonance'],
                'g_triadic': tri['g_triadic'],
                'equation': f"g_master = g_N * (1 - Ub/g_N) * H_SCm * fTRZ = {g_master:.6e} m/s^2"
            }
        return {'g_master': g_master, 'g_N': g_N}

    def compute(self, dataset: dict) -> dict:
        """UQFF Crab Nebula + PSR B0531+21 (PAPER_013 spin-down framework).

        PAPER_013 (magnetar spin-down): SCm coupling suppresses magnetic dipole radiation.
        For extreme magnetars: t_sd_UQFF = 3 * t_GR, n_UQFF in [1.5, 2.0]
        For Crab (young pulsar, not magnetar): SCm coupling ~ F_TRZ*A_5*SSQ/D_crit scaled
        """
        import math
        # Observations
        P_ms = 33.5028583
        P_dot = 4.2094e-13
        B_dipole_T = 3.78e8
        distance_kpc = 2.0
        age_yr = 971.0
        # Canonical NS moment of inertia
        I_NS = 1.0e38
        P_s = P_ms * 1e-3
        omega = 2.0 * math.pi / P_s
        omega_dot = -2.0 * math.pi * P_dot / (P_s**2)
        E_rot = 0.5 * I_NS * omega**2
        # Classical dipole spin-down
        L_sd_classical_W = -I_NS * omega * omega_dot
        # PAPER_013 SCm suppression: L_sd_UQFF = L_sd / (1 + f_SCm)
        # For extreme magnetars f_SCm = 2 (giving t_sd = 3*t_GR)
        # For Crab (fast rotator P=33ms, moderate B) scale down:
        f_SCm_Crab = F_TRZ * A_5 * SSQ / D_CRIT * (K_MEX / D_PHYS)
        L_sd_UQFF_W = L_sd_classical_W / (1.0 + f_SCm_Crab)
        L_sd_observed_W = 4.6e31
        residual_L = abs(L_sd_UQFF_W - L_sd_observed_W) / L_sd_observed_W * 100.0
        tau_char_yr = 0.5 * P_s / P_dot / (3.15e7)
        # Braking index — PAPER_013: n_UQFF < 3 due to SCm coupling
        # Crab observed n = 2.51. UQFF prediction with SCm coupling factor:
        n_braking_UQFF = 3.0 - F_TRZ * A_5 * SSQ * K_MEX / D_CRIT
        n_observed = 2.51
        residual_n = abs(n_braking_UQFF - n_observed) / n_observed * 100.0
        return {
            'primary_equations': [
                f"P = {P_ms} ms, P_dot = {P_dot:.3e} s/s (observed)",
                f"I_NS (canonical) = {I_NS:.1e} kg*m^2",
                f"omega = {omega:.2f} rad/s, E_rot = {E_rot:.3e} J",
                f"L_sd_classical = -I*omega*omega_dot = {L_sd_classical_W:.3e} W",
                f"PAPER_013 SCm suppression factor f_SCm_Crab = F_TRZ*A_5*SSQ/D_crit * K_MEX/D_phys = {f_SCm_Crab:.4f}",
                f"L_sd_UQFF = L_sd_classical / (1 + f_SCm) = {L_sd_UQFF_W:.3e} W",
                f"L_sd observed = {L_sd_observed_W:.3e} W, residual = {residual_L:.3f}%",
                f"Characteristic age = P/(2*P_dot) = {tau_char_yr:.0f} yr (SN 1054 -> 971 yr)",
                f"Braking index n_UQFF = 3 - F_TRZ*A_5*SSQ*K_MEX/D_crit = {n_braking_UQFF:.4f}",
                f"Braking index observed n = {n_observed}, residual = {residual_n:.3f}%",
            ],
            'P_ms': P_ms, 'P_dot': P_dot,
            'omega_rad_s': omega, 'I_NS_kg_m2': I_NS, 'E_rot_J': E_rot,
            'L_spindown_classical_W': L_sd_classical_W,
            'L_spindown_UQFF_W': L_sd_UQFF_W,
            'L_spindown_observed_W': L_sd_observed_W,
            'L_spindown_residual_pct': residual_L,
            'f_SCm_Crab_suppression': f_SCm_Crab,
            'characteristic_age_yr': tau_char_yr,
            'actual_age_yr': age_yr,
            'braking_index_UQFF': n_braking_UQFF,
            'braking_index_observed': n_observed,
            'braking_index_residual_pct': residual_n,
            'B_dipole_T': B_dipole_T,
            'F_TRZ': F_TRZ, 'A_5': A_5, 'SSQ': SSQ, 'K_MEX': K_MEX, 'D_CRIT': D_CRIT,
            'note': 'PAPER_013 magnetar spin-down. Crab-scaled SCm suppression f_SCm = F_TRZ*A_5*SSQ*K_MEX/(D_crit*D_phys). Braking index deviation from 3 = same coupling.',
        }

class NGC2264Model(SelfSimulatingExpandingMixin):
    """

    NGC 2264 Model - Christmas Tree Cluster / Cone Nebula Star-Forming Region

    NGC 2264 encompasses the Cone Nebula, Christmas Tree Cluster, Snowflake 

    Cluster, and Fox Fur Nebula. Located ~2,300 light-years away in Monoceros,

    it spans ~10-15 light-years with ~100 young stars (1-5 Myr old).

    KEY EQUATIONS:

    -----------------------------------------------------------------------------

    Master Compressed UQFF Equation:

    g(r,t) = g_grav � (1+H(z)�t) � (1+M_sf) � (1-E_rad) � (1+f_TRZ) + a_EM

    Master Resonance UQFF Equation:

    R(t) = R_grav�cos(?_grav�t) + R_mag�cos(?_mag�t) � UA_factor � TRZ_factor

    Where:

        g_grav  = G�M/r�           Base gravitational acceleration
        M_sf(t) = SFR�t/M0         Star formation mass growth
        E_rad(t)= E0(1-e^(-t/t))   Radiation erosion
        a_EM    = q(v�B)/m_p � UA  Electromagnetic with Aether correction
        R_grav  = g_grav � M_sf    Gravitational resonance amplitude
        R_mag   = q�v�B/m_p � scale Magnetic resonance amplitude
        ?_grav  = 2p/T_sf          Star formation angular frequency
        ?_mag   = 2p/T_wind        Wind cycle angular frequency

    DOCUMENT BENCHMARKS (t = 3 Myr):

    -----------------------------------------------------------------------------

        g_grav              = 5.927e-11 m/s�
        1 + H(z)�t          = 1.0002147
        1 + M_sf            = 2.5
        1 - E_rad           = 0.8446
        a_EM                = 1.053e-2 m/s�
        g_Compressed (total)= 1.053e-2 m/s� (EM-dominated)
        R_Resonance (total) = 1.161e-2 m/s� (magnetic resonance dominated)

    PHYSICAL PARAMETERS:

    -----------------------------------------------------------------------------

        M           = 1000 M_sun (focused region)
        r           = 4.73�10�6 m (5 ly half-radius)
        SFR         = 0.5 M_sun/yr
        v_wind      = 106 m/s (stellar wind)
        B           = 10?5 T
        ?_gas       = 10?�� kg/m�
        E0          = 0.2 (20% max erosion)
        t_erode     = 2 Myr

    APPLICATIONS:

    -----------------------------------------------------------------------------

    - Star formation dynamics

    - Radiation-driven erosion modeling

    - Protostellar outflow physics

    - Stellar wind interactions

    AUTHOR:

    -----------------------------------------------------------------------------

    Copyright � Daniel T. Murphy, 2025

    Grok 3 DeepSearch analysis, May 09, 2025

    Location: Youngstown, OH, USA (41.0997� N, 80.6495� W)

    """

    def __init__(self, M=None, r=None, SFR=None, v_wind=None, B=None, 

                 rho_gas=None, t_age=None, z=None, f_TRZ=0.1, E_0=0.2, tau_erode=None):
        """
        Initialize NGC 2264 Model with configurable parameters.
        Args:
            M: Total mass in kg (default: 1.989e33 = 1000 M_sun)
            r: Region radius in m (default: 4.73e16 = 5 ly)
            SFR: Star formation rate in M_sun/yr (default: 0.5)
            v_wind: Stellar wind velocity in m/s (default: 1e6)
            B: Magnetic field in T (default: 1e-5)
            rho_gas: Gas density in kg/m� (default: 1e-20)
            t_age: Age in s (default: 9.468e13 = 3 Myr)
            z: Redshift (default: 0.0006)
            f_TRZ: Time-reversal zone factor (default: 0.1)
            E_0: Max erosion fraction (default: 0.2)
            tau_erode: Erosion timescale in s (default: 6.312e13 = 2 Myr)
        """
        import math
        # Physical constants
        self.G = _URP_G         # Gravitational constant (m�/kg/s�)
        self.c = 2.998e8            # Speed of light (m/s)
        self.H_0 = 2.268e-18        # Hubble constant (s?�) = 70 km/s/Mpc
        self.Omega_m = 0.3          # Matter density parameter
        self.Omega_Lambda = 0.7     # Dark energy density parameter
        self.q_e = 1.602e-19        # Electron charge (C)
        self.m_p = 1.673e-27        # Proton mass (kg)
        self.M_sun = 1.989e30       # Solar mass (kg)
        # UQFF vacuum densities
        self.rho_vac_UA = CONSTANTS.get('rho_vac_UA', _RHO_VAC_UA)
        self.rho_vac_SCm = CONSTANTS.get('rho_vac_SCm', _RHO_VAC_SCM)
        # System parameters
        self.M = M if M is not None else CONSTANTS.get('NGC2264_M_May2025', 1.989e33)
        self.r = r if r is not None else CONSTANTS.get('NGC2264_r_May2025', 4.73e16)
        self.SFR = SFR if SFR is not None else 0.5  # M_sun/yr
        self.SFR_kg_s = self.SFR * self.M_sun / (3.156e7)  # Convert to kg/s
        self.v_wind = v_wind if v_wind is not None else CONSTANTS.get('NGC2264_v_wind', 1e6)
        self.B = B if B is not None else CONSTANTS.get('NGC2264_B', 1e-5)
        self.rho_gas = rho_gas if rho_gas is not None else CONSTANTS.get('NGC2264_rho_gas', 1e-20)
        self.t_age = t_age if t_age is not None else CONSTANTS.get('NGC2264_t_age', 9.468e13)
        self.z = z if z is not None else CONSTANTS.get('NGC2264_z', 0.0006)
        self.f_TRZ = f_TRZ
        self.E_0 = E_0
        self.tau_erode = tau_erode if tau_erode is not None else 6.312e13  # 2 Myr
        # Resonance timescales
        self.T_sf = 3.156e13        # Star formation cycle ~ 1 Myr (s)
        self.T_wind = 3.156e11      # Wind cycle ~ 10,000 yr (s)
        # Document reference values
        self.g_grav_doc = CONSTANTS.get('g_grav_NGC2264', 5.927e-11)
        self.g_compressed_doc = CONSTANTS.get('g_NGC2264_Compressed', 1.053e-2)
        self.R_resonance_doc = CONSTANTS.get('R_NGC2264_Resonance', 1.161e-2)
        self.R_grav_doc = CONSTANTS.get('R_grav_NGC2264', 1.482e-10)
        self.R_mag_doc = CONSTANTS.get('R_mag_NGC2264', 9.575e-4)

    def compute_H_z(self):
        """Compute Hubble parameter at redshift z."""
        import math
        factor = self.Omega_m * (1 + self.z)**3 + self.Omega_Lambda
        return self.H_0 * math.sqrt(factor)

    def compute_hubble_correction(self, t=None):
        """Compute Hubble expansion correction factor (1 + H(z)�t)."""
        if t is None:
            t = self.t_age
        H_z = self.compute_H_z()
        return 1.0 + H_z * t

    def compute_g_grav(self, r=None):
        """
        Compute base gravitational acceleration g_grav = G�M/r�.
        Document value: 5.927e-11 m/s�
        """
        if r is None:
            r = self.r
        return dpm_ug1_seed(self.M, r)

    def compute_M_sf(self, t=None):
        """
        Compute star formation mass growth factor.
        M_sf(t) = SFR � t_Myr
        Document: M_sf = 0.5 � 3 = 1.5 ? 1 + M_sf = 2.5
        Note: Document formula is simplified, not ratio-based.
        """
        if t is None:
            t = self.t_age
        # Convert t to Myr
        t_Myr = t / (3.156e13)  # 1 Myr = 3.156e13 s
        M_sf = self.SFR * t_Myr
        return M_sf

    def compute_E_rad(self, t=None):
        """
        Compute radiation erosion factor.
        E_rad(t) = E0 � (1 - exp(-t/t_erode))
        Document: E_rad = 0.2 � (1 - exp(-1.5)) = 0.1554
        """
        import math
        if t is None:
            t = self.t_age
        return self.E_0 * (1.0 - math.exp(-t / self.tau_erode))

    def compute_a_EM_with_UA(self, v=None, B=None):
        """
        Compute electromagnetic acceleration with UQFF UA correction.
        a_EM = q(v�B)/m_p � (1 + ?_UA/?_SCm) � 10?��
        Document value: 1.053e-2 m/s�
        """
        if v is None:
            v = self.v_wind
        if B is None:
            B = self.B
        # UA correction factor
        UA_factor = 1.0 + self.rho_vac_UA / self.rho_vac_SCm  # ~11
        # Lorentz force acceleration on proton
        F_lorentz = self.q_e * v * B
        a_raw = F_lorentz / self.m_p
        # Apply UA factor and scale
        a_EM = a_raw * UA_factor * 1e-12
        return a_EM

    def compute_compressed_equation(self, t=None, r=None):
        """
        Compute Master Compressed UQFF equation for NGC 2264.
        g(r,t) = g_grav � (1+H(z)�t) � (1+M_sf) � (1-E_rad) � (1+f_TRZ) + a_EM
        Document g_Compressed = 1.053e-2 m/s�
        Returns:
            dict with all computed values
        """
        if t is None:
            t = self.t_age
        if r is None:
            r = self.r
        # Components
        g_grav = self.compute_g_grav(r)
        hubble_factor = self.compute_hubble_correction(t)
        M_sf = self.compute_M_sf(t)
        M_sf_factor = 1.0 + M_sf
        E_rad = self.compute_E_rad(t)
        E_rad_factor = 1.0 - E_rad
        trz_factor = 1.0 + self.f_TRZ
        a_EM = self.compute_a_EM_with_UA()
        # Gravitational term with all corrections
        g_grav_corrected = g_grav * hubble_factor * M_sf_factor * E_rad_factor * trz_factor
        # Total compressed equation
        g_compressed = g_grav_corrected + a_EM
        # Fraction analysis
        EM_fraction = a_EM / g_compressed if g_compressed > 0 else 0.0
        return {
            'g_grav': g_grav,
            'hubble_factor': hubble_factor,
            'M_sf': M_sf,
            'M_sf_factor': M_sf_factor,
            'E_rad': E_rad,
            'E_rad_factor': E_rad_factor,
            'trz_factor': trz_factor,
            'g_grav_corrected': g_grav_corrected,
            'a_EM': a_EM,
            'g_compressed': g_compressed,
            'EM_fraction': EM_fraction
        }

    def compute_resonance_equation(self, t=None):
        """
        Compute Master Resonance UQFF equation for NGC 2264.
        R(t) = R_grav�cos(?_grav�t) + R_mag�cos(?_mag�t) � UA_factor � TRZ_factor
        Document R_Resonance = 1.161e-2 m/s� at t = 3 Myr
        Returns:
            dict with all resonance values
        """
        import math
        if t is None:
            t = self.t_age
        # Angular frequencies
        omega_grav = 2 * math.pi / self.T_sf
        omega_mag = 2 * math.pi / self.T_wind
        # Gravitational resonance amplitude
        g_grav = self.compute_g_grav()
        M_sf = self.compute_M_sf(t)
        R_grav = g_grav * (1.0 + M_sf)
        # Magnetic resonance amplitude
        F_lorentz = self.q_e * self.v_wind * self.B
        R_mag_raw = F_lorentz / self.m_p
        R_mag = R_mag_raw * 1e-12  # Scaled
        # Correction factors
        UA_factor = 1.0 + self.rho_vac_UA / self.rho_vac_SCm
        TRZ_factor = 1.0 + self.f_TRZ
        # Oscillation phases
        phase_grav = omega_grav * t
        phase_mag = omega_mag * t
        # Resonance components
        R_grav_term = R_grav * math.cos(phase_grav)
        R_mag_term = R_mag * math.cos(phase_mag) * UA_factor * TRZ_factor
        # Total resonance
        R_total = R_grav_term + R_mag_term
        # Amplitude (non-oscillating for validation)
        R_amplitude = abs(R_grav) + abs(R_mag * UA_factor * TRZ_factor)
        return {
            'omega_grav': omega_grav,
            'omega_mag': omega_mag,
            'R_grav': R_grav,
            'R_mag': R_mag,
            'UA_factor': UA_factor,
            'TRZ_factor': TRZ_factor,
            'phase_grav': phase_grav,
            'phase_mag': phase_mag,
            'R_grav_term': R_grav_term,
            'R_mag_term': R_mag_term,
            'R_total': R_total,
            'R_amplitude': R_amplitude
        }

    def compute_UQFF_base(self, t=None, r=None):
        """
        Compute UQFF Base Unified Field equation.
        F_U = S(Ug_i + Ub_i) + Um + Ur + Ut + Ui + UA + SCm
        This is the fundamental UQFF equation combining all field contributions.
        Returns:
            dict with all computed field values
        """
        import math
        if t is None:
            t = self.t_age
        if r is None:
            r = self.r
        # Gravitational terms
        g_grav = self.compute_g_grav(r)
        # Universal gravity components (26 layers simplified to primary terms)
        k_1, k_2, k_3, k_4 = 1.5, 1.2, 0.8, 0.5
        # DPM-seeded: Ug1 from magnetic moment coupling (not Newtonian base)
        Ug1 = k_1 * g_grav                          # Magnetic dipole
        Ug2 = k_2 * g_grav * (1 + self.z)           # Charge-reactivity
        Ug3 = k_3 * g_grav * math.sin(2 * math.pi * t / self.t_age) if self.t_age > 0 else 0  # String rotation
        Ug4 = k_4 * g_grav * self.rho_vac_UA / 1e-36 if self.rho_vac_UA else k_4 * g_grav    # Vacuum concentration
        # Buoyancy term
        beta = CONSTANTS.get('beta_i', 0.6)
        Ub = beta * (g_grav - self.rho_vac_UA * self.G) if self.rho_vac_UA else beta * g_grav
        # Magnetism term
        Um = self.q_e * self.v_wind * self.B / self.m_p if hasattr(self, 'v_wind') else 0
        # Additional contributions (simplified)
        Ur = 0.01 * g_grav              # Radiation pressure
        Ut = 0.001 * g_grav             # Thermal contribution
        Ui = 0.0001 * g_grav            # Interstellar medium
        UA = self.rho_vac_UA * dpm_ug1_seed(self.M, r) if self.rho_vac_UA else 0
        SCm = self.rho_vac_SCm * dpm_ug1_seed(self.M, r) if self.rho_vac_SCm else 0
        # Total unified field
        F_U = Ug1 + Ug2 + Ug3 + Ug4 + Ub + Um + Ur + Ut + Ui + UA + SCm
        return {
            'F_U': F_U,
            'Ug1': Ug1,
            'Ug2': Ug2,
            'Ug3': Ug3,
            'Ug4': Ug4,
            'Ub': Ub,
            'Um': Um,
            'Ur': Ur,
            'Ut': Ut,
            'Ui': Ui,
            'UA': UA,
            'SCm': SCm,
            'g_grav': g_grav
        }

    def compute_superconductive_equation(self, t=None):
        """
        Compute UQFF Superconductive equation.
        [SCm](t) = [SCm]0 � e^(-?t) � (1 - cos(?t))
        Models SCm vacuum modulation over time.
        Returns:
            dict with superconductive field values
        """
        import math
        if t is None:
            t = self.t_age
        # UQFF calibrated constants
        kappa = CONSTANTS.get('kappa', 0.0005)      # Reactivity decay (day?�)
        SSq = CONSTANTS.get('SSq', 0.57)            # Quantum state factor
        # Convert kappa from day?� to s?�
        kappa_s = kappa / 86400
        # SCm base density
        SCm_0 = self.rho_vac_SCm if self.rho_vac_SCm else _RHO_VAC_SCM
        # Angular frequency (based on characteristic timescale)
        omega_SCm = 2 * math.pi / (self.t_age if self.t_age > 0 else 1e13)
        # Exponential decay
        decay = math.exp(-kappa_s * t)
        # Oscillation factor
        oscillation = 1 - math.cos(omega_SCm * t)
        # SCm(t) modulation
        SCm_t = SCm_0 * decay * oscillation
        # Effective field contribution
        g_SCm = SCm_t * self.G * self.M / (self.r * self.r) if self.r > 0 else 0
        return {
            'SCm_t': SCm_t,
            'SCm_0': SCm_0,
            'decay_factor': decay,
            'oscillation_factor': oscillation,
            'g_SCm': g_SCm,
            'kappa': kappa,
            'omega_SCm': omega_SCm,
            'SSq': SSq
        }

    def compute_buoyant_equation(self, t=None, r=None):
        """
        Compute UQFF Buoyant equation (F_U_Bi).
        F_U_Bi = S �_i � (Ug_i - ?_vac,i � G)
        Inside?Out atomic scale buoyancy (pushing outward).
        Returns:
            dict with buoyant field values
        """
        import math
        if t is None:
            t = self.t_age
        if r is None:
            r = self.r
        # Beta coupling factors
        beta = CONSTANTS.get('beta_i', 0.6)
        # Gravitational base
        g_grav = self.compute_g_grav(r)
        # Universal gravity components
        k_1 = 1.5
        Ug = k_1 * g_grav
        # Vacuum contribution
        rho_vac = self.rho_vac_UA if self.rho_vac_UA else _RHO_VAC_UA
        vac_term = rho_vac * self.G
        # Momentum term (electron pressure)
        m_e = CONSTANTS.get('m_e', 9.109e-31)
        c = self.c
        DPM_momentum = CONSTANTS.get('DPM_momentum', 1e-8)
        theta = math.pi / 4  # Default angle
        momentum_term = (m_e * c ** 2 / (r ** 2)) * DPM_momentum * math.cos(theta)
        # Gravity term
        DPM_gravity = CONSTANTS.get('DPM_gravity', 1e-10)
        gravity_term = g_grav * DPM_gravity
        # Buoyant fraction
        F_U_Bi = beta * (Ug - vac_term) + momentum_term + gravity_term
        return {
            'F_U_Bi': F_U_Bi,
            'beta': beta,
            'Ug': Ug,
            'vac_term': vac_term,
            'momentum_term': momentum_term,
            'gravity_term': gravity_term,
            'direction': 'Inside ? Out',
            'scale': 'Atomic'
        }

    def compute_master_buoyant_equation(self, t=None):
        """
        Compute UQFF Master Buoyant equation (F_U_Bi_i).
        F_U_Bi_i = O_g � (M_bh/d_g) � S(Ug_i + Ub_i)
        Outside?In cosmic scale buoyancy (supporting from vacuum).
        Returns:
            dict with master buoyant field values
        """
        import math
        if t is None:
            t = self.t_age
        # Galactic parameters (defaults for star-forming regions)
        M_bh = CONSTANTS.get('M_bh_MW', 4e6 * self.M_sun)      # MW central BH
        d_g = CONSTANTS.get('d_g_sun', 2.55e20)                 # Distance to galactic center
        Omega_g = CONSTANTS.get('Omega_g_MW', 2.5e-8)           # Galactic rotation rate
        # Get base UQFF values
        base = self.compute_UQFF_base(t)
        Ug_sum = base['Ug1'] + base['Ug2'] + base['Ug3'] + base['Ug4']
        Ub = base['Ub']
        # Master buoyant integral
        galactic_factor = Omega_g * (M_bh / d_g)
        F_U_Bi_i = galactic_factor * (Ug_sum + Ub)
        return {
            'F_U_Bi_i': F_U_Bi_i,
            'galactic_factor': galactic_factor,
            'Omega_g': Omega_g,
            'M_bh': M_bh,
            'd_g': d_g,
            'Ug_sum': Ug_sum,
            'Ub': Ub,
            'direction': 'Outside ? In',
            'scale': 'Cosmic'
        }

    def compute_triadic_equation(self, t=None, n_layers=26):
        """
        Compute UQFF Triadic equation (26-layer gravitational scaling).
        g(r,t) = S(i=1..26) [Ug1_i + Ug2_i + Ug3_i + Ug4_i] � Q_i � [UA]_i � [SCm]_i
        Full 26-dimensional polynomial gravity summation.
        Returns:
            dict with triadic/26-layer field values
        """
        import math
        if t is None:
            t = self.t_age
        # Base gravitational acceleration
        g_grav = self.compute_g_grav()
        # Universal gravity couplings
        k_1, k_2, k_3, k_4 = 1.5, 1.2, 0.8, 0.5
        # 26-layer summation
        g_triadic = 0.0
        layer_contributions = []
        for i in range(1, n_layers + 1):
            # Layer-dependent quantum state factor
            Q_i = 1.0 / (1 + 0.01 * i)  # Decreasing with layer
            # Layer-dependent UA factor
            UA_i = self.rho_vac_UA * (1 - 0.02 * i) if self.rho_vac_UA else _RHO_VAC_UA * (1 - 0.02 * i)
            # Layer-dependent SCm factor
            SCm_i = self.rho_vac_SCm * (1 - 0.01 * i) if self.rho_vac_SCm else _RHO_VAC_SCM * (1 - 0.01 * i)
            # Phase factor for this layer
            phase = 2 * math.pi * i / n_layers
            # Four Ug components for this layer
            Ug1_i = k_1 * g_grav * Q_i * UA_i / _RHO_VAC_UA
            Ug2_i = k_2 * g_grav * Q_i * (1 + self.z) * math.cos(phase)
            Ug3_i = k_3 * g_grav * Q_i * math.sin(phase + 2 * math.pi * t / self.t_age) if self.t_age > 0 else 0
            Ug4_i = k_4 * g_grav * Q_i * SCm_i / _RHO_VAC_SCM
            # Total for this layer
            g_i = (Ug1_i + Ug2_i + Ug3_i + Ug4_i) * Q_i * UA_i * SCm_i * 1e72  # Normalize
            g_triadic += g_i
            layer_contributions.append({
                'layer': i,
                'Q_i': Q_i,
                'UA_i': UA_i,
                'SCm_i': SCm_i,
                'g_i': g_i
            })
        return {
            'g_triadic': g_triadic,
            'n_layers': n_layers,
            'g_grav_base': g_grav,
            'layer_sum': sum(lc['g_i'] for lc in layer_contributions),
            'first_layer': layer_contributions[0] if layer_contributions else None,
            'last_layer': layer_contributions[-1] if layer_contributions else None
        }

    def compute_quadratic_equation(self, t=None):
        """
        Compute UQFF Quadratic equation (root solutions).
        Solves g� + b�g + c = 0 for gravitational field regimes.
        Returns:
            dict with quadratic solution values
        """
        import math
        if t is None:
            t = self.t_age
        # Get compressed and resonance values
        compressed = self.compute_compressed_equation(t)
        resonance = self.compute_resonance_equation(t)
        g_comp = compressed.get('g_compressed', 0)
        R_amp = resonance.get('R_amplitude', 0)
        # Quadratic coefficients based on UQFF field balance
        # g� - (g_comp + R_amp)g + g_comp � R_amp � correlation = 0
        a = 1.0
        b = -(g_comp + R_amp)
        c = g_comp * R_amp * 0.1  # Correlation factor
        # Discriminant
        discriminant = b * b - 4 * a * c
        # Solutions
        if discriminant >= 0:
            sqrt_disc = math.sqrt(discriminant)
            x1 = (-b + sqrt_disc) / (2 * a)
            x2 = (-b - sqrt_disc) / (2 * a)
            solution_type = 'real'
        else:
            sqrt_disc = math.sqrt(-discriminant)
            x1 = -b / (2 * a)  # Real part
            x2 = sqrt_disc / (2 * a)  # Imaginary part
            solution_type = 'complex'
        return {
            'x1': x1,
            'x2': x2,
            'solution_type': solution_type,
            'discriminant': discriminant,
            'a': a,
            'b': b,
            'c': c,
            'g_compressed': g_comp,
            'R_amplitude': R_amp
        }

    def validate_model(self):
        """
        Validate model outputs against document reference values.
        Returns:
            dict with validation results and pass/fail status
        """
        compressed = self.compute_compressed_equation()
        resonance = self.compute_resonance_equation()
        # Compare to document values
        g_grav_ratio = compressed['g_grav'] / self.g_grav_doc if self.g_grav_doc != 0 else float('inf')
        g_comp_ratio = compressed['g_compressed'] / self.g_compressed_doc if self.g_compressed_doc != 0 else float('inf')
        R_res_ratio = resonance['R_amplitude'] / self.R_resonance_doc if self.R_resonance_doc != 0 else float('inf')
        # Tolerance bounds
        tol_low, tol_high = 0.95, 1.05
        validations = {
            'g_grav': {
                'computed': compressed['g_grav'],
                'document': self.g_grav_doc,
                'ratio': g_grav_ratio,
                'passed': tol_low <= g_grav_ratio <= tol_high
            },
            'g_compressed': {
                'computed': compressed['g_compressed'],
                'document': self.g_compressed_doc,
                'ratio': g_comp_ratio,
                'passed': tol_low <= g_comp_ratio <= tol_high
            },
            'R_resonance': {
                'computed': resonance['R_amplitude'],
                'document': self.R_resonance_doc,
                'ratio': R_res_ratio,
                'passed': tol_low <= R_res_ratio <= tol_high
            }
        }
        all_passed = all(v['passed'] for v in validations.values())
        return {
            'validations': validations,
            'all_passed': all_passed,
            'compressed_results': compressed,
            'resonance_results': resonance
        }

