                f"Stromgren radius = ({r_stromgren_pc:.3f} pc, {r_stromgren_cm:.3e} cm)",
                f"H-alpha luminosity ~ {L_H_alpha:.3e} erg/s",
                f"Emission measure = n_e^2 * L = {emission_measure:.3e} cm^-5",
                f"UQFF F_UBi factor = (1+F_TRZ*SSQ) = {F_UBi_factor:.4f}",
