        self.rho_gas = rho_gas if rho_gas is not None else CONSTANTS.get('NGC2841_rho_gas', 1e-20)
        self.t_age = t_age if t_age is not None else CONSTANTS.get('NGC2841_t_age', 3.15e17)
        self.z = z if z is not None else CONSTANTS.get('NGC2841_z', 0.0031)
        self.f_TRZ = f_TRZ
