class NegativeTimeModel(SelfSimulatingExpandingMixin):
    """

    Model for negative time physics and retrocausality.

    Implements t? = -t_n � exp(? - t_n) and TRZ physics.

    """

    def __init__(self, t_n: float = 0.0, kappa: float = 0.1):

        self.t_n = t_n
        self.kappa = kappa
        self.f_TRZ = CONSTANTS.get('f_TRZ', 0.1)
        self.calc = NEGATIVE_TIME_CALCULATOR

    def compute_t_minus(self) -> tuple:
        """t? = -t_n � exp(? - t_n)"""
        result = self.calc.compute_negative_time_operator(self.t_n, self.kappa)
        return result.result, result.substituted

    def compute_retrocausal_factor(self, base_value: float) -> tuple:
        """Apply TRZ modulation to base value"""
        result = self.calc.compute_time_reversal_zone_factor(self.t_n, base_value)
        return result.result, result.substituted

    def is_retrocausal(self) -> bool:
        """Check if evolution is retrocausal (t_n < 0)"""
        return self.t_n < CONSTANTS.get('t_n_threshold', 0.0)

    # 

    # 8 UQFF MASTER EQUATIONS

    # 

    def compute_UQFF_base(self, params=None) -> dict:
        """UQFF Base: F_U = S(Ug_i + Ub_i) + Um + Ur + Ut + Ui + UA + SCm"""
        G = CONSTANTS.get('G', _URP_G)
        M = getattr(self, 'M', getattr(params, 'M', 1.989e30)) if params else getattr(self, 'M', 1.989e30)
        r = getattr(self, 'r', getattr(params, 'r', 1e10)) if params else getattr(self, 'r', 1e10)
        # DPM-seeded: mu_s x grad(M_s/r) base (Newtonian form is emergent, not foundational)
        g_base = dpm_ug1_seed(M, r)  # DPM-seeded projection, not Newton seed
        Ug1 = (N_CH / D_BSFG) * g_base   # PAPER_1916 base shell = 3/2 EXACT; Ug2 = (1.0 / PHI_RES_NUCLEAR) * g_base   # PAPER_1916 charge-reactivity shell = 6/5 EXACT; Ug3 = (2.0 * D_PHYS / SO_5) * g_base   # PAPER_1916 dark-matter shell = 4/5 EXACT * np.sin(np.pi/4); Ug4 = 0.5 * g_base   # PAPER_1916 BH vacuum shell = 1/2 EXACT (Sum U_gi = D_PHYS EXACT)
        beta = CONSTANTS.get('beta_i', 0.6)
        rho_vac = CONSTANTS.get('rho_vac_UA', _RHO_VAC_UA)
        Ub = beta * (g_base - rho_vac * G)
        Um = CONSTANTS.get('mu_0', 4e-7) * 1e6 / (4 * np.pi * r**2) if r > 0 else 0
        F_U = Ug1 + Ug2 + Ug3 + Ug4 + Ub + Um
        return {'F_U': F_U, 'Ug1': Ug1, 'Ug2': Ug2, 'Ug3': Ug3, 'Ug4': Ug4, 'Ub': Ub, 'Um': Um, 'g_base': g_base}

    def compute_compressed_equation(self, params=None, t=None) -> dict:
        """UQFF Compressed: g = g_N  (1+Ht)  (1+M_sf)  (1-E_rad)  (1+f_TRZ) + a_EM"""
        G = CONSTANTS.get('G', _URP_G)
        M = getattr(self, 'M', getattr(params, 'M', 1.989e30)) if params else getattr(self, 'M', 1.989e30)
        r = getattr(self, 'r', getattr(params, 'r', 1e10)) if params else getattr(self, 'r', 1e10)
        t = t if t is not None else getattr(self, 't', 3.156e13)
        g_N = dpm_ug1_seed(M, r)  # DPM-seeded projection
        H_0 = CONSTANTS.get('H_0', 2.268e-18)
        f_TRZ = CONSTANTS.get('f_TRZ', 0.1)
        hubble = 1 + H_0 * t; trz = 1 + f_TRZ
        g_compressed = g_N * hubble * trz
        return {'g_compressed': g_compressed, 'g_N': g_N, 'hubble_factor': hubble, 'trz_factor': trz}

    def compute_resonance_equation(self, params=None, t=None) -> dict:
        """UQFF Resonance: R = S(a_i  cos(?_i  t))"""
        t = t if t is not None else getattr(self, 't', 1e8)
        omega_grav = 2 * np.pi / 3.156e13
        omega_mag = 2 * np.pi / 3.156e11
        R_grav = CONSTANTS.get('G', _URP_G) * 1e30 / 1e20 * np.cos(omega_grav * t)
        R_mag = 1e-5 * np.cos(omega_mag * t)
        UA_factor = 1 + CONSTANTS.get('rho_vac_UA', _RHO_VAC_UA) / CONSTANTS.get('rho_vac_SCm', _RHO_VAC_SCM)
        R_total = R_grav + R_mag * UA_factor
        return {'R_total': R_total, 'R_grav': R_grav, 'R_mag': R_mag, 'UA_factor': UA_factor}

    def compute_superconductive_equation(self, params=None, t=None) -> dict:
        """UQFF Superconductive: [SCm](t) = [SCm]  e^(-?t)  (1 - cos(?t))"""
        t = t if t is not None else getattr(self, 't', 1e8)
        SCm_0 = CONSTANTS.get('rho_vac_SCm', _RHO_VAC_SCM)
        kappa = CONSTANTS.get('kappa', 0.0005) / 86400
        omega = 2 * np.pi / 3.156e13
        SCm_t = SCm_0 * np.exp(-kappa * t) * (1 - np.cos(omega * t))
        return {'SCm_t': SCm_t, 'SCm_0': SCm_0, 'decay': np.exp(-kappa * t)}

    def compute_buoyant_equation(self, params=None) -> dict:
        """UQFF Buoyant (F_U_Bi): F_Bi = �  (Ug - ?_vac  G)"""
        G = CONSTANTS.get('G', _URP_G)
        M = getattr(self, 'M', getattr(params, 'M', 1.989e30)) if params else getattr(self, 'M', 1.989e30)
        r = getattr(self, 'r', getattr(params, 'r', 1e10)) if params else getattr(self, 'r', 1e10)
        # DPM-seeded: mu_s x grad(M_s/r) base (Newtonian form is emergent, not foundational)
        g_base = dpm_ug1_seed(M, r)  # DPM-seeded projection, not Newton seed
        beta = CONSTANTS.get('beta_i', 0.6)
        rho_vac = CONSTANTS.get('rho_vac_UA', _RHO_VAC_UA)
        F_Bi = beta * (g_base - rho_vac * G)
        return {'F_Bi': F_Bi, 'g_base': g_base, 'beta': beta, 'rho_vac': rho_vac}

    def compute_master_buoyant_equation(self, params=None) -> dict:
        """UQFF Master Buoyant (F_U_Bi_i): Cosmic-scale buoyancy integral"""
        buoyant = self.compute_buoyant_equation(params)
        Omega_g = CONSTANTS.get('Omega_g', 7.3e-16)
        f_TRZ = CONSTANTS.get('f_TRZ', 0.1)
        F_U_Bi_i = buoyant['F_Bi'] * (1 + f_TRZ) / (1 - Omega_g)
        return {'F_U_Bi_i': F_U_Bi_i, 'F_Bi': buoyant['F_Bi'], 'Omega_g': Omega_g, 'f_TRZ': f_TRZ}

    def compute_triadic_equation(self, params=None, n_layers=26) -> dict:
        """UQFF Triadic: g_26 = S(i=1 to 26) [Ug1_i + Ug2_i + Ug3_i + Ug4_i]"""
        G = CONSTANTS.get('G', _URP_G)
        M = getattr(self, 'M', getattr(params, 'M', 1.989e30)) if params else getattr(self, 'M', 1.989e30)
        r = getattr(self, 'r', getattr(params, 'r', 1e10)) if params else getattr(self, 'r', 1e10)
        # DPM-seeded: mu_s x grad(M_s/r) base (Newtonian form is emergent, not foundational)
        g_base = dpm_ug1_seed(M, r)  # DPM-seeded projection, not Newton seed
        k_values = [1.5, 1.2, 0.8, 0.5]
        g_layers = []; total = 0
        for i in range(1, n_layers + 1):
            scale = 1 + 0.1 * (i - 13) / 13
            Ug_i = sum(k * g_base * scale for k in k_values)
            g_layers.append(Ug_i); total += Ug_i
        return {'g_triadic': total, 'g_layers': g_layers, 'n_layers': n_layers}

    def compute_quadratic_equation(self, params=None) -> dict:
        """UQFF Quadratic: Solves g + bg + c = 0 for unified field roots"""
        G = CONSTANTS.get('G', _URP_G)
        M = getattr(self, 'M', getattr(params, 'M', 1.989e30)) if params else getattr(self, 'M', 1.989e30)
        r = getattr(self, 'r', getattr(params, 'r', 1e10)) if params else getattr(self, 'r', 1e10)
        a = 1; b = -G * M / (r ** 2) if r > 0 else 1e-10; c = CONSTANTS.get('Lambda', 1.1e-52) * r**2 / 3
        disc = b**2 - 4*a*c
        if disc >= 0:
            g_plus = (-b + np.sqrt(disc)) / (2*a); g_minus = (-b - np.sqrt(disc)) / (2*a)
        else:
            g_plus = g_minus = -b / (2*a)
        return {'g_plus': g_plus, 'g_minus': g_minus, 'discriminant': disc, 'a': a, 'b': b, 'c': c}

    def compute(self, dataset: dict) -> dict:
        """UQFF Negative-time dual-existence CW/CCW branches (PAPER_597)."""
        import math
        t_pos = dataset.get('t_pos_s', 1.0)
        omega_s = dataset.get('omega_s_rad_s', 2.5e-6)
        t_neg = -t_pos * F_TRZ
        rho_UA = 10.0 * RHO_SCM
        branch_CW = RHO_SCM * math.cos(math.pi * t_pos * omega_s)
        branch_CCW = rho_UA * math.cos(math.pi * t_neg * omega_s + math.pi)
        overlap_integral = SSQ * K_MEX * F_TRZ
        big_bang_contact_amplitude = RHO_SCM * (1.0 + F_TRZ) * BETA_I
        big_bang_energy_J = big_bang_contact_amplitude * K_MEX
        return {
            'primary_equations': [
                f"t_pos (forward) = {t_pos} s (SCm North CW branch)",
                f"PAPER_597_UPDATE canonical calibration: t_neg = -2512 s",
                f"t_neg = -F_TRZ * t_pos = {t_neg:.4f} s (UA' South CCW branch)",
                f"Branch CW: rho_SCm*cos(pi*t_pos*omega_s) = {branch_CW:.3e} J/m^3",
                f"Branch CCW: rho_UA*cos(pi*t_neg*omega_s + pi) = {branch_CCW:.3e} J/m^3",
                f"CW x CCW overlap integral = SSQ*K_MEX*F_TRZ = {overlap_integral:.4f}",
                f"Big Bang contact amplitude = rho_SCm*(1+F_TRZ)*beta_i = {big_bang_contact_amplitude:.3e} J/m^3",
                f"Big Bang seed energy = amp*K_MEX = {big_bang_energy_J:.3e} J/m^3",
                f"PAPER_597: two grinding poles (SCm-CW North + UA'-CCW South) meet at t=0",
            ],
            't_pos_s': t_pos,
            't_neg_s': t_neg,
            'branch_CW_J_m3': branch_CW,
            'branch_CCW_J_m3': branch_CCW,
            'overlap_integral': overlap_integral,
            'big_bang_contact_amplitude': big_bang_contact_amplitude,
            'big_bang_energy_J_m3': big_bang_energy_J,
            'RHO_SCM': RHO_SCM, 'RHO_UA': rho_UA,
            't_neg_canonical_s': -2512.0,
            'F_TRZ': F_TRZ, 'BETA_I': BETA_I, 'SSQ': SSQ, 'K_MEX': K_MEX,
            'note': 'PAPER_597 + PAPER_597_UPDATE canonical (t_neg = -2512 s). Dual CW/CCW branches. Big Bang = SCm-UA contact event at t=0. Also PAPER_517 dilation proof.',
        }

