        disc = b**2 - 4*a*c
        if disc >= 0:
            g_plus = (-b + np.sqrt(disc)) / (2*a); g_minus = (-b - np.sqrt(disc)) / (2*a)
        else:
            g_plus = g_minus = -b / (2*a)
