class StarMagicVacuumEnergy:
    """

    Vacuum Energy Density (?_vac) Calculator.

    ?_vac = S(f_i � E_i) / V

    Includes SCm and UA contributions for complete aether density.

    """

    def __init__(self):

        self.C = CONSTANTS
        self.energy_structure = StarMagicEnergyStructure()

    def vacuum_energy_density(self, occupation_fractions: dict, volume: float) -> dict:
        """
        Compute vacuum energy density from occupation fractions.
        occupation_fractions: {level_n: fraction_f_i} for n=1 to 26
        """
        total_energy = 0.0
        for n, f_i in occupation_fractions.items():
            E_n = self.energy_structure.E_0 * (10 ** n)
            total_energy += f_i * E_n
        lambda_vac = total_energy / volume
        return {
            'lambda_vac': lambda_vac,
            'total_energy': total_energy,
            'volume': volume,
            'levels_used': len(occupation_fractions),
            'unit': 'J/m�'
        }

    def cosmological_vacuum(self, volume: float = 1.0) -> dict:
        """
        Compute cosmological vacuum energy density (n=20-26 levels).
        Matches JWST 2025 cosmological constant (~10^-9 J/m�).
        """
        # Low occupation fractions for cosmological vacuum
        cosmological_fractions = {n: 1e-15 for n in range(20, 27)}
        return self.vacuum_energy_density(cosmological_fractions, volume)

    def compute(self, dataset: dict) -> dict:
        """Canonical UQFF compute. DPM-seeded: GM/r^2 is Step 10 projection, not seed.
        Chain: 0 -> grad(UA) -> DPM -> Ug1 -> Ug_family -> F_U -> M -> GM/r^2 (last).
        """
        import math
        M   = dataset.get('M_kg',   1.989e30)
        r   = dataset.get('r_m',    1.496e11)
        B   = dataset.get('B_T',    _URP_F_TRZ ** 4)                   # R387: 1e-4 EXACT F_TRZ^4
        t   = dataset.get('t_s',    0.0)
        t_n = dataset.get('t_n',    0.0)
        kappa   = dataset.get('kappa',   _URP_KAPPA)                    # R387: 5e-4 EXACT PAPER_2112
        E_react = dataset.get('E_react', float(_URP_SO_5 ** 46))        # R387: 1e46 EXACT SO_5^46 (R335)
        beta_i  = dataset.get('beta_i', _URP_BETA_I)                   # R387: 0.6029 canonical PAPER_1203 (was legacy 0.6)
        SSq     = dataset.get('SSq',     _URP_SSQ)                     # R387: 0.57 PAPER_1154 canonical
        Omega_g = dataset.get('Omega_g', 7.3e-16)
        M_bh    = dataset.get('M_bh',    8.15e36)
        d_g     = dataset.get('d_g',     float(_URP_D_CRIT * (_URP_SO_5 ** 19)))  # R387: 2.6e20 EXACT PAPER_2139
        # --- DPM-seeded gravity family (NOT Newton-first) ---
        g_b = dpm_ug1_seed(M, r, B)  # Ug1: DPM seed
        Ug1 = g_b
        Ug2 = (1.0 / PHI_RES_NUCLEAR) * g_b   # PAPER_1916 charge-reactivity shell = 6/5 EXACT (from Phi_res_nuclear=5/6)
        Ug3 = (2.0 * D_PHYS / SO_5) * g_b   # PAPER_1916 dark-matter shell = 4/5 EXACT * math.cos(math.pi * t_n)  # magnetic string rotation
        Ug4 = 0.5 * g_b   # PAPER_1916 BH vacuum shell = 1/2 EXACT (Sum U_gi = D_PHYS EXACT)
        # Buoyancy (inside-out counter-force) — R387: 0.1 modulation coefficient promoted to F_TRZ EXACT
        Ub = -beta_i * Ug1 * Omega_g * (M_bh / max(d_g, 1.0)) * (
            1.0 + _URP_F_TRZ * math.cos(math.pi * t_n)
        )
        # Unified field
        F_U = Ug1 + Ug2 + Ug3 + Ug4 + Ub
        # GM/r^2 appears LAST as a derived observational projection only
        # R387: local _G CODATA literal promoted to LIVE _URP_G (PAPER_593, 22nd G-promotion) — bulk Rule 4 cleanup across all 160 classes carrying this boilerplate template
        _G = _URP_G
        g_projection = _G * M / (r ** 2) if r > 0 else 0.0
        return {
            'primary_equations': [
                f'Ug1(DPM-seed) = dpm_ug1_seed(M,r,B) = {Ug1:.6e}',
                f'Ug2(shell)    = 1.2*Ug1                 = {Ug2:.6e}',
                f'Ug3(string)   = 0.8*Ug1*cos(pi*t_n)    = {Ug3:.6e}',
                f'Ug4(BH-vac)   = 0.5*Ug1                 = {Ug4:.6e}',
                f'Ub (buoyancy) = {Ub:.6e}',
                f'F_U(unified)  = {F_U:.6e}',
                f'GM/r^2(projection, LAST) = {g_projection:.6e} m/s^2',
            ],
            'available_equations': [
                'g_base = dpm_ug1_seed(M, r, B)  # DPM-seeded, not Newton',
                'Ug1 = g_base  # seed from DPM vortex',
                'Ug2 = 1.2 * Ug1  # charge-reactivity',
                'Ug3 = 0.8 * Ug1 * cos(pi*t_n)  # magnetic string 90deg',
                'Ug4 = 0.5 * Ug1  # BH vacuum concentration',
                'Ub = -beta_i * Ug1 * Omega_g * M_bh/d_g  # buoyancy counter',
                'F_U = Ug1 + Ug2 + Ug3 + Ug4 + Ub  # unified field',
                'GM/r^2 = projection of F_U (EMERGENT, appears last)',
            ],
            'simulation_set': [
                {'equation': 'F_U_vs_r',  'M_kg': M, 'r_m': r, 'result': F_U},
                {'equation': 'Ug1_vs_B',  'B_T':  B, 'r_m': r, 'result': Ug1},
            ],
            'Ug1': Ug1, 'Ug2': Ug2, 'Ug3': Ug3, 'Ug4': Ug4,
            'Ub': Ub, 'F_U': F_U, 'g_base': g_b,
            'g_projection_GM_r2': g_projection,
        }

