class MuJTerm:
    """

    �J Helper Term - Magnetic moment � Angular momentum coupling

    Equation: �J = ? � J = (g � q / 2m) � J

    where:

        ? = gyromagnetic ratio
        g = g-factor (�2 for electrons)
        q = particle charge (C)
        m = particle mass (kg)
        J = angular momentum (J�s)

    Used in: Ug1 magnetic dipole gravity, spin-orbit coupling

    """

    def __init__(self):

        self.g_electron = 2.002319  # Electron g-factor
        self.e = 1.602e-19  # C
        self.m_e = 9.109e-31  # kg
        self.hbar = 1.055e-34  # J�s

    def compute(self, dataset: dict = None, J: float = 1e40, g: float = None, q: float = None, m: float = None) -> tuple:
        """Compute magnetic moment from angular momentum."""
        if g is None:
            g = self.g_electron
        if q is None:
            q = self.e
        if m is None:
            m = self.m_e
        gamma = (g * q) / (2 * m)  # Gyromagnetic ratio
        mu_J = gamma * J
        equation = f"�J = ? � J = (g � q / 2m) � J = ({g} � {q:.4e} / (2 � {m:.4e})) � {J:.4e} = {mu_J:.4e} J/T"
        return mu_J, equation

    def compute_electron_spin(self) -> tuple:
        """Compute Bohr magneton (electron spin magnetic moment)."""
        J_spin = self.hbar / 2  # Electron spin �?/2
        return self.compute(J_spin)

