        d_m = d_Mpc * 3.086e22  # meters
        # Frequency range (GW190425: 30-400 Hz in detector band)
        f_start = 30.0   # Hz (higher than GW170817's 23 Hz)
        f_end = 400.0    # Hz (lower than GW170817's 800+ Hz)
