        # UQFF "AETHER NOISE" COMPONENTS
        # -----------------------------------------------------------------------
        # 1. U_m fundamental and harmonics
        # U_m creates spectral lines at f_U = some characteristic frequency
        f_U_fundamental = 1e-3  # 1 mHz fundamental (arbitrary but in LISA band)
        n_harmonics = 5
