    # ---------------------------------------------------------------------------

    # SELF-EXPANDING / SIMULATION

    # ---------------------------------------------------------------------------

    def add_scaling(self, scaling_func):
        """
        Self-expand: Add custom scaling factor.
        Args:
            scaling_func: Function(M, T_H) -> multiplicative factor
        Example:
            calc.add_scaling(lambda M, T_H: 1.0 + 1e-10/(M*T_H))
        """
        self.additional_scalings.append(scaling_func)

    def simulate_over_mass(self, M_start: float, M_end: float, n_points: int = 50):
        """
        Simulate lifetime over mass range.
        Args:
            M_start: Starting mass [kg]
            M_end: Ending mass [kg]
            n_points: Number of points
        Returns:
            Dict with masses, temperatures, lifetimes
        """
        masses = np.logspace(np.log10(M_start), np.log10(M_end), n_points)
        T_H = np.array([self.compute_T_H(M) for M in masses])
        tau_std = np.array([self.compute_tau_standard(M) for M in masses])
        tau_UQFF = np.array([self.compute_tau_UQFF(M) for M in masses])
        stability = tau_UQFF / tau_std
        return {
            'masses': masses,
            'M_solar': masses / self.params['M_sun'],
            'T_H': T_H,
            'tau_standard': tau_std,
            'tau_UQFF': tau_UQFF,
            'stability_factor': stability,
        }

    # ---------------------------------------------------------------------------

    # COMPUTE INTERFACE

    # ---------------------------------------------------------------------------

    def compute(self, mode: str = 'full', **kwargs) -> dict:
        """
        Main computation interface.
        Args:
            mode: Computation mode
                - 'full': All lifetime steps for given mass
                - 'temperature': Hawking temperature only
                - 'standard': Standard Hawking lifetime only
                - 'simulate': Lifetime over mass range
            **kwargs: Mode-specific parameters
                M: Black hole mass [kg] (required for most modes)
        Returns:
            Dict with computed results
        """
        if mode == 'full':
            M = kwargs.get('M', 4.3e6 * self.params['M_sun'])  # Default: Sgr A*
            T_H = self.compute_T_H(M)
            tau_std = self.compute_tau_standard(M)
            tau_prime = self.compute_tau_prime(tau_std)
            tau_double_prime = self.compute_tau_double_prime(tau_prime)
            tau_UQFF = self.compute_tau_UQFF_step(tau_double_prime, T_H)
            tau_full = self.compute_tau_UQFF(M)
            stability = tau_full / tau_std if np.isfinite(tau_full) else np.inf
            return {
                'mode': 'full',
                'M': M,
                'M_solar': M / self.params['M_sun'],
                'T_H': T_H,
                'tau_standard': tau_std,
                'tau_prime': tau_prime,
                'tau_double_prime': tau_double_prime,
                'tau_UQFF': tau_UQFF,
                'tau_full': tau_full,
                'stability_factor': stability,
                'is_stable': np.isinf(tau_full),
            }
        elif mode == 'temperature':
            M = kwargs.get('M', 4.3e6 * self.params['M_sun'])
            return {
                'mode': 'temperature',
                'M': M,
                'T_H': self.compute_T_H(M),
            }
        elif mode == 'standard':
            M = kwargs.get('M', 4.3e6 * self.params['M_sun'])
            tau = self.compute_tau_standard(M)
            return {
                'mode': 'standard',
                'M': M,
                'tau_standard': tau,
                'tau_years': tau / self.params['year'],
            }
        elif mode == 'simulate':
            M_start = kwargs.get('M_start', 1e10)
            M_end = kwargs.get('M_end', 1e40)
            n_points = kwargs.get('n_points', 50)
            return self.simulate_over_mass(M_start, M_end, n_points)
        elif mode == 'validate_sgr_a':
            # Use user-specified U_m_ratio or default assumption
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            return self.validate_sgr_a_star(U_m_kT_ratio=U_m_kT_ratio)
        elif mode == 'validate_m87':
            # M87* stability analysis (EHT target)
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            return self.validate_m87_star(U_m_kT_ratio=U_m_kT_ratio)
        elif mode == 'T_UQFF_m87':
            # M87* temperature modulation chain
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            verbose = kwargs.get('verbose', False)
            return self.compute_T_UQFF_m87(U_m_kT_ratio=U_m_kT_ratio, verbose=verbose)
        elif mode == 'm87_mass_evolution':
            # M87* mass evolution simulation (Standard vs UQFF)
            t_end_years = kwargs.get('t_end_years', 1e100)
            n_points = kwargs.get('n_points', 20)
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            return self.simulate_m87_mass_evolution(t_end_years, n_points, U_m_kT_ratio)
        elif mode == 'stability_proofs':
            # All UQFF stability proofs combined
            M = kwargs.get('M', 4.3e6 * self.params['M_sun'])
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            return self.compute_stability_proof_combined(M, U_m_kT_ratio)
        elif mode == 'stability_proof_1':
            # Proof 1: Time-reversal suppression
            M = kwargs.get('M', 4.3e6 * self.params['M_sun'])
            return self.compute_stability_proof_1(M)
        elif mode == 'stability_proof_2':
            # Proof 2: Aether density damping
            M = kwargs.get('M', 4.3e6 * self.params['M_sun'])
            return self.compute_stability_proof_2(M)
        elif mode == 'stability_proof_3':
            # Proof 3: Magnetic string barrier
            M = kwargs.get('M', 4.3e6 * self.params['M_sun'])
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            return self.compute_stability_proof_3(M, U_m_kT_ratio)
        elif mode == 'temperature_modulation':
            # UQFF Hawking temperature modulation
            M = kwargs.get('M', 4.3e6 * self.params['M_sun'])
            use_coherence = kwargs.get('use_coherence', True)
            use_magnetic_damping = kwargs.get('use_magnetic_damping', True)
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', None)
            return self.compute_T_UQFF_modulated(
                M, 
                use_coherence=use_coherence,
                use_magnetic_damping=use_magnetic_damping,
                U_m_kT_ratio=U_m_kT_ratio,
                **{k: v for k, v in kwargs.items() 
                   if k not in ['M', 'use_coherence', 'use_magnetic_damping', 'U_m_kT_ratio']}
            )
        elif mode == 'modulate_mass_range':
            # Temperature modulation over mass range
            M_start = kwargs.get('M_start', 1e30)
            M_end = kwargs.get('M_end', 1e40)
            n_points = kwargs.get('n_points', 50)
            return self.modulate_over_mass(M_start, M_end, n_points, **kwargs)
        elif mode == 'pbh_survival':
            # PBH survival analysis for single mass
            M = kwargs.get('M', 1e12)  # Default: critical mass
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            return self.compute_pbh_survival_enhancement(M, U_m_kT_ratio)
        elif mode == 'pbh_asteroid_validation':
            # Validate asteroid-mass PBH (M = 10^12 kg) stability
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            return self.validate_asteroid_mass_pbh(U_m_kT_ratio)
        elif mode == 'pbh_stability_derivation':
            # Full step-by-step UQFF PBH stability derivation
            M = kwargs.get('M', 1e12)
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            verbose = kwargs.get('verbose', False)
            return self.pbh_uqff_stability_derivation(M, U_m_kT_ratio, verbose)
        elif mode == 'pbh_lifetime_chart':
            # Mass vs lifetime chart data for plotting
            M_start = kwargs.get('M_start', 1e8)
            M_end = kwargs.get('M_end', 1e16)
            n_points = kwargs.get('n_points', 100)
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            return self.pbh_mass_lifetime_chart_data(M_start, M_end, n_points, U_m_kT_ratio)
        elif mode == 'pbh_dark_matter':
            # PBH dark matter viability analysis
            U_m_kT_ratio = kwargs.get('U_m_kT_ratio', 1.0)
            return self.analyze_pbh_dark_matter_viability(U_m_kT_ratio)
        elif mode == 'pbh_mass_sweep':
            # PBH evaporation over mass range
            M_start = kwargs.get('M_start', 1e10)
            M_end = kwargs.get('M_end', 1e20)
            n_points = kwargs.get('n_points', 50)
