    def compute_g_YM_squared(self, L: float) -> float:
        """Step 3: g_YM� = (4pG/L�) � (1 + f_TRZ)"""
        G = self.params['G']
        f_TRZ = self.params['f_TRZ']
        if L <= 0:
            return 0.0
        return (4.0 * np.pi * G / L**2) * (1.0 + f_TRZ)

    def compute_g_YM_UQFF(self, L: float) -> float:
        """g_YM = sqrt(g_YM�)"""
