        t_phase = dataset.get('t_phase', 0.0)
        rho_base = 1e-23
        delta_n_rad = (2.0 * math.pi) ** (n_state / 6.0)
        # PAPER_855: at t=0 reference, exp factor is 1; time dependence via exp(-|t|)
        time_factor = math.exp(-abs(t_phase))
