        sigma_T = 6.652e-29
        m_p = 1.673e-27
        G_val = _URP_G
        L_Edd_W = 4.0 * math.pi * G_val * M_kg * m_p * c_ms / sigma_T
        Eddington_ratio = L_source_W / L_Edd_W
