              f"  r = {self.r:.4f}, A_s = {self.A_s:.2e}\n"
              f"  n_t = n_t_std + d_UQFF = {n_t_standard:.4f} + {n_t_uqff:.4f} = {n_t:.4f}\n"
              f"  h�O_GW = {h2_Omega_GW:.4e}\n"
