        g_UQFF = params.get('g_UQFF', 1e-8)  # UQFF gravity (m/s�)
        # Simplified 1D NS: dv/dt = -dP/dx/? + g_UQFF  (ignoring viscous term for first approx)
        dv_dt = -dP_dx / rho + g_UQFF if rho != 0 else g_UQFF
        # Time to reach jet velocity
