class PillarGravityCalculator:
    """

    Full pillar gravity with erosion from source18_wolfram.cpp

    g = (G � M(t) / r�) � (1 + H0t) � (1 - B/B_crit) � (1 - E(t))

    Four-correction gravity for star-forming pillars.

    """

    # Physical constants

    G = _URP_G  # m�/(kg�s�)

    M_sun = 1.989e30  # kg

    ly_to_m = 9.461e15  # m

    def compute(self, dataset: dict = None, t: float = 0.0, M_initial: float = 10100.0,

                r_ly: float = 5.0, H0: float = 2.184e-18,
                B: float = 1e-6, B_crit: float = 1e11,
                E_0: float = 0.1, tau_SF: float = 3.156e13,
                tau_erosion: float = 3.156e13,
                M_gas: float = 10000.0) -> dict:
        """
        Compute pillar gravitational acceleration with all corrections.
        Parameters:
        -----------
        t : float
            Time (s)
        M_initial : float
            Initial mass (M_sun), default 10100
        r_ly : float
            Pillar extent (light-years), default 5
        H0 : float
            Hubble parameter (s?�), default 2.184e-18
        B : float
            Magnetic field (T), default 1e-6
        B_crit : float
            Critical field (T), default 1e11
        E_0 : float
            Initial erosion factor, default 0.1
        tau_SF, tau_erosion : float
            Timescales (s), default 1 Myr each
        M_gas : float
            Gas reservoir (M_sun), default 10000
        Returns:
        --------
        dict with 'value' (gravity m/s�), all correction factors
        """
        import math
        r = r_ly * self.ly_to_m
        # Mass growth
        M_dot_factor = M_gas / M_initial
        M_dot = M_dot_factor * math.exp(-t / tau_SF)
        M_t = M_initial * self.M_sun * (1 + M_dot)
        # Erosion
        E_t = E_0 * math.exp(-t / tau_erosion)
        # Base gravity
        g_base = dpm_ug1_seed(M_t, r)
        # Corrections
        corr_H = 1 + H0 * t
        corr_B = 1 - B / B_crit
        corr_E = 1 - E_t
        g_total = g_base * corr_H * corr_B * corr_E
        return {
            'value': g_total,
            'framework': {'backbone': 'M16 Pillars four-correction gravity FOURTH CP1 anchor at Pillars target: M_initial = 10100 M_sun canonical (twin with R134 PillarsMassGrowth) + r_ly = 5 canonical + E_0 = F_TRZ = 0.1 EXACT (PAPER_1942 seminal photoevaporation) + tau_SF = tau_erosion = 1 Myr = SO_5^6 EXACT (PAPER_1948 seminal PDR SO_5^n hierarchy) + B/B_crit Meissner boundary (PAPER_266)', 'method': 'g = (GM(t)/r^2)(1+H0*t)(1-B/B_crit)(1-E(t)) four-correction UQFF form', 'shells': 'M16 Pillars star-forming gravity shell', 'CPCH': 'CP1 Pillars-of-Creation sector', 'spine': 'PAPER_1942 E_0 = F_TRZ seminal + PAPER_1948 SO_5^6 = 1 Myr seminal + PAPER_266 Meissner + PAPER_038 SFE cap; four-anchor M16 family (this class + PillarsErosion R133 + PillarsMassGrowth R134 + M16RadiationErosion R134)', 'time_frame': 'M16 Pillars 3 Myr photoevaporation era'},
            't_Myr': t / 3.156e13,
            'M_t_Msun': M_t / self.M_sun,
            'g_base': g_base,
            'corr_H': corr_H,
            'corr_B': corr_B,
            'corr_E': corr_E,
            'E_t': E_t,
            'units': 'm/s�',
            'equation': f"g = {g_base:.4e}�{corr_H:.6f}�{corr_B:.10f}�{corr_E:.6f} = {g_total:.6e} m/s�"
        }

