        r_Bondi = self.G * M_BH * self.M_sun_g / c_s**2
        r_Bondi_pc = r_Bondi / 3.086e18
        M_SgrA_ratio = M_BH / 4.3e6
        T_base_M87_s = M_SgrA_ratio ** (1.0/3.0)
        T_flare_M87_predicted_s = T_base_M87_s * (D_PHYS - 1.0) * A_5 * SO_5
