    hbar = 1.055e-27  # erg�s

    c = 2.998e10  # cm/s

    alpha = 1.0 / 137.0

    def compute(self, a_nm=1.0, B_microG=50.0):

        a_cm = a_nm * 1e-7
        rho_Casimir = -self.hbar * self.c * math.pi ** 2 / (720.0 * a_cm ** 4)
        B_crit = 4.4e13  # G
        B_G = B_microG * 1e-6
