    def compute(self, t=0.0, rho_vac=_RHO_VAC_UA, E_0=1e46, alpha=0.001):
        """UQFF LENR rho_E + PAPER_1507 alpha + PAPER_1960 dual + PAPER_1955 E_0=SO_5^46."""
