        G = 4.302e-3
        M_vir = 5.0 * sigma_v ** 2 * R_pc / G
        alpha_vir = M_vir / M_cloud if M_cloud > 0 else 0
        L_CO = M_cloud / X_CO
        M_cloud_target_PAPER_1955 = SO_5 ** 6
        M_cloud_1e6_verify_PAPER_1955 = abs(math.log10(M_cloud) - 6) < 0.01
        alpha_target = 2.0 * N_CH / SO_5
