        import math
        if M_cluster is None:
            M_cluster = 1.2e15 * self.M_sun
        if R_virial is None:
            R_virial = 2.2 * 3.086e22
        x = max(r / R_virial, 1e-10)
        f_c = math.log(1 + c_NFW) - c_NFW / (1 + c_NFW)
