    G = _URP_G

    M_sun = 1.989e30

    def compute(self, dataset: dict = None, r: float = 6.96e8, M_gal: float = None, M_cluster: float = None,

                R_virial: float = None) -> dict:
        if M_gal is None:
            M_gal = 1e11 * self.M_sun
        if M_cluster is None:
            M_cluster = 1.2e15 * self.M_sun
        if R_virial is None:
            R_virial = 2.2 * 3.086e22
        x = r / R_virial
        M_enclosed = M_cluster * (x**3) / ((1 + x)**2)
