    """General oscillatory resonance: 2A�cos(kx)�cos(?t)+(2p/13.8)�A�Re[exp(i(kx-?t))], f_osc=4.57e14 Hz."""

    def __init__(self):

        self.A = 1e-10
        self.k = 1e20
        self.omega_osc = 1e15
        self.x = 0.0
        import math
        self.pi = math.pi

    def compute(self, t: float = 0.0) -> dict:

        import math, cmath
        cos_term = 2.0 * self.A * math.cos(self.k * self.x) * math.cos(self.omega_osc * t)
