class CompressionMassEvolutionCalculator:
    """

    Calculate mass evolution from star formation.

    Physics: M(t) = M0�(1 + M_sf(t))

    Star formation rate drives mass accumulation

    """

    M0_PRIMITIVE = 1.989e30
    SFR_PRIMITIVE = 4 / 4

    def __init__(self, M0: float = None, SFR: float = None):
        self.M0 = self.M0_PRIMITIVE if M0 is None else M0
        self.SFR = self.SFR_PRIMITIVE if SFR is None else SFR

    def compute(self, dataset: dict = None, t: float = 0.0, **params) -> float:
        """
        Calculate evolved mass at time t.
        M(t) = M0�(1 + SFR�t/M0)
        Args:
            t: time (s)
        Returns:
            Current mass (kg)
        """
        yr_to_s = 3.156e7
        M_sf = self.SFR * self.M0 * (t / yr_to_s) / self.M0
        return self.M0 * (1 + M_sf)

    def to_wolfram(self) -> str:

        return "CompressionMassEvolution[t_, M0_: 1.989*^30, SFR_: 1] := M0 * (1 + SFR * (t / 3.156*^7))"

