class M51InertialVacuumCalculator:
    """

    Calculate inertial vacuum term.

    Physics: ?_I � (?_SCm/?_UA) � ?_i � cos(pt_n) � (1 + F_RZ)

    ?_SCm = _RHO_VAC_SCM, ?_UA = _RHO_VAC_UA, F_RZ = 0.01

    """

    LAMBDA_I_PRIMITIVE = 4 / 4
    OMEGA_I_PRIMITIVE = 4 / 4
    F_RZ_PRIMITIVE = 0.1 ** 2

    def __init__(self, lambda_I: float = None,
                 rho_SCm: float = _RHO_VAC_SCM,
                 rho_UA: float = _RHO_VAC_UA,
                 omega_i: float = None,
                 F_RZ: float = None):
        self.lambda_I = self.LAMBDA_I_PRIMITIVE if lambda_I is None else lambda_I
        self.rho_SCm = rho_SCm
        self.rho_UA = rho_UA
        self.omega_i = self.OMEGA_I_PRIMITIVE if omega_i is None else omega_i
        self.F_RZ = self.F_RZ_PRIMITIVE if F_RZ is None else F_RZ

    def compute(self, dataset: dict = None, t_n: float = 0.0, **params) -> float:
        """
        Calculate inertial vacuum contribution.
        Ubi = ?_I � (?_SCm/?_UA) � ?_i � cos(pt_n) � (1 + F_RZ)
        Args:
            t_n: normalized time
        Returns:
            Inertial term value
        """
        import math
        ratio = self.rho_SCm / self.rho_UA
        return self.lambda_I * ratio * self.omega_i * math.cos(math.pi * t_n) * (1 + self.F_RZ)

    def to_wolfram(self) -> str:

        return "M51InertialVacuum[tn_, lambdaI_: 1, rhoSCm_: 7.09*^-37, rhoUA_: 7.09*^-36, omegai_: 1, FRZ_: 0.01] := lambdaI * (rhoSCm / rhoUA) * omegai * Cos[Pi * tn] * (1 + FRZ)"

class M51SpiralArmWaveCalculator:
    """

    Calculate spiral arm density wave |?|�.

    Physics: ? = A � exp(-r�/2s�) � exp(i(m�f - ?�t))

    m = 2 arms, s = 10 kpc = 3.086e22 m, ? = 1e-15 rad/s

    """

    A_PRIMITIVE = 0.1 ** 10
    SIGMA_PRIMITIVE = 3.086e22
    M_PRIMITIVE = 4 // 2
    OMEGA_PRIMITIVE = 0.1 ** 15

    def __init__(self, A: float = None, sigma: float = None, m: int = None, omega: float = None):
        self.A = self.A_PRIMITIVE if A is None else A
        self.sigma = self.SIGMA_PRIMITIVE if sigma is None else sigma
        self.m = self.M_PRIMITIVE if m is None else m
        self.omega = self.OMEGA_PRIMITIVE if omega is None else omega

    def compute(self, dataset: dict = None, r: float = 6.96e8, phi: float = 0.0, t: float = 0.0, **params) -> float:
        """
        Calculate spiral density wave |?|�.
        |?|� = A� � exp(-r�/s�) � [cos�(m�f - ?�t) + sin�(m�f - ?�t)]
        Args:
            r: radius (m)
            phi: azimuthal angle (rad)
            t: time (s)
        Returns:
            Probability density |?|�
        """
        import math
        radial = math.exp(-r * r / (2.0 * self.sigma * self.sigma))
        phase = self.m * phi - self.omega * t
        # |?|� = A� � radial� (phase cancels in norm)
        return self.A * self.A * radial * radial

    def to_wolfram(self) -> str:

        return "M51SpiralArmWave[r_, phi_, t_, A_: 10^-10, sigma_: 3.086*^22, m_: 2, omega_: 10^-15] := A^2 * Exp[-r^2 / sigma^2]"

