class M31CentralBlackHoleCalculator:
    """

    Calculate M31* SMBH gravitational potential.

    Physics: F_BH = -GM_BH/r (Schwarzschild potential)

    M31* SMBH: M_BH = 1.4e8 M_sun

    """

    G_PRIMITIVE = _URP_G
    M_BH_PRIMITIVE = ((6 + 1) / (4 + 1)) * (10 ** 8)
    M_SUN_PRIMITIVE = 1.989e30
    PC_TO_M_PRIMITIVE = 3.086e16

    def __init__(self, G: float = None, M_BH: float = None):
        self.G = self.G_PRIMITIVE if G is None else G
        self.M_BH = self.M_BH_PRIMITIVE if M_BH is None else M_BH
        self.M_sun = self.M_SUN_PRIMITIVE
        self.pc_to_m = self.PC_TO_M_PRIMITIVE

    def compute(self, dataset: dict = None, r_pc: float = 22600.0, **params) -> float:
        """
        Calculate SMBH gravitational potential.
        F_BH = -GM_BH/r
        Args:
            r_pc: radius (pc)
        Returns:
            Gravitational potential (J/kg = m�/s�)
        """
        if r_pc <= 0:
            return 0.0
        M_BH_kg = self.M_BH * self.M_sun
        r_m = r_pc * self.pc_to_m
        return -self.G * M_BH_kg / r_m

    def to_wolfram(self) -> str:

        return "M31CentralBlackHole[r_, MBH_: 1.4*^8, G_: 6.674*^-11, Msun_: 1.989*^30, pcToM_: 3.086*^16] := Module[{MBHkg, rM}, MBHkg = MBH * Msun; rM = r * pcToM; -G * MBHkg / rM]"

