        k_1 = 1.5e-4
        Ug1 = k_1 * (M_s / r) * math.exp(-gamma * t) * math.cos(math.pi * t_n) * (1 + 0.01 * math.sin(gamma * t))
        # Ug_2: Outer field bubble
