    category = "Black Hole Thermodynamics"

    M_PRIMITIVE = 10 ** 12
    SCM_PRIMITIVE = 1.0 - F_TRZ ** 2
    UBI_FACTOR_PRIMITIVE = F_TRZ ** 2

