        G = _URP_G
        c = 2.998e8
        hbar = 1.055e-34
        kB = 1.381e-23
        pi = math.pi
        sigma_SB = 5.670e-8
        M_sun = 1.989e30
        # Schwarzschild radius
        r_s = 2.0 * dpm_ug1_seed(M, c)
        # Horizon area
        A_H = 4.0 * pi * r_s**2
