        import math
        tau_0 = dataset.get('tau_0_s', 3.94e11)
        n_harmonics = dataset.get('n_harmonics', 26)
        biblical_gen_yr = dataset.get('biblical_gen_yr', 40.0)
        kali_yuga_yr = dataset.get('kali_yuga_yr', 432000.0)
        day_s = 86400.0
        yr_s = 3.156e7
        # Mayan cycles
        kin = 1 * day_s
        uinal = 20 * day_s
        tun = 360 * day_s
        katun = 7200 * day_s
        baktun = 144000 * day_s
        # Biblical generation
        gen_s = biblical_gen_yr * yr_s
        # Vedic Yuga cycle (4:3:2:1 ratio)
        kali = kali_yuga_yr * yr_s
        dvapara = 2 * kali
        treta = 3 * kali
        satya = 4 * kali
        maha_yuga = satya + treta + dvapara + kali
        # Pi-cycle harmonics
        harmonics = []
        for n in range(1, n_harmonics + 1):
            tau_n = tau_0 * abs(math.cos(n * math.pi / 26.0))
            harmonics.append({'n': n, 'tau_n_s': tau_n, 'tau_n_yr': tau_n / yr_s})
        # DPM grinding period ratios
        ratio_baktun_gen = baktun / gen_s if gen_s > 0 else 0
        ratio_yuga_baktun = maha_yuga / baktun if baktun > 0 else 0
        # Planck time ratio
