class MSigmaPhononCorrectedRelationCalculator:
    """M-s relation with explicit F1.25THz phonon modulation on the power-law slope.

    Standard M-s: M_BH = M_0 � (s / s_0)^a

    UQFF correction: a_UQFF = a � (1 + �_i � SCm � F � S26)

    The 1.25 THz SCm phonon linewidth modulates the feedback coupling between

    SMBH accretion and stellar velocity dispersion, steepening the slope.

    Physics:

    - Classical Ferrarese & Merritt (2000): a � 4.02

    - SCm phonon feedback: phonon energy density in bulge ISM modifies

      momentum transfer efficiency in AGN-driven outflows

    - Buoyancy correction: F_UBii prevents excessive momentum deposition

      at low s, flattening the relation below s ~ 100 km/s

    Output:

    1. Primary equations with M_BH predictions (6 equations)

    2. Available equations for this dataset

    3. Simulation sets for M-s parameter sweeps

    """

    category = "SMBH / M-sigma / Phonon Correction / AGN Feedback"

    BETA_I_PRIMITIVE = D_BSFG * F_TRZ
    SSQ_PRIMITIVE = 0.57
    KAPPA_PRIMITIVE = (D_phys + 1) * (0.1 ** 4)
    SCM_PRIMITIVE = 1.0 - F_TRZ ** 2
    GAMMA_THZ_PRIMITIVE = F_TRZ
    SIGMA_0_PRIMITIVE = 2 * (10 ** 5)
    SIGMA_CRIT_PRIMITIVE = 10 ** 5
    SCATTER_DEX_PRIMITIVE = 3.0 * F_TRZ

    def compute(self, dataset: dict) -> dict:

        d = dataset if isinstance(dataset, dict) else {}
        import math
        # UQFF parameters (R247 primitive-derived defaults)
        beta_i = d.get('beta_i', MSigmaPhononCorrectedRelationCalculator.BETA_I_PRIMITIVE)
        SSq = d.get('SSq', MSigmaPhononCorrectedRelationCalculator.SSQ_PRIMITIVE)
        kappa = d.get('kappa', MSigmaPhononCorrectedRelationCalculator.KAPPA_PRIMITIVE)
        SCm = d.get('SCm', MSigmaPhononCorrectedRelationCalculator.SCM_PRIMITIVE)
        Gamma = d.get('Gamma_THz', MSigmaPhononCorrectedRelationCalculator.GAMMA_THZ_PRIMITIVE)
        M_sun = 1.989e30
        c = 2.998e8
        G = _URP_G
        # Phonon modulation
        omega_0 = 1.25e12 * 2 * math.pi
        Gamma_rad = Gamma * 2 * math.pi * 1e12
        Phi_phonon = 1.0 / (1.0 + Gamma_rad ** 2 / omega_0 ** 2)
        S26 = SSq ** 3 * math.exp(-kappa * 26) * (2 * math.pi) ** (1.0 / 6)
        # Classical M-s parameters (external Ferrarese-Merritt astronomy)
        alpha_classic = d.get('alpha', 4.02)
        M_0 = d.get('M_0', 1.66e8 * M_sun)
        sigma_0 = d.get('sigma_0', MSigmaPhononCorrectedRelationCalculator.SIGMA_0_PRIMITIVE)
        sigma = d.get('sigma', MSigmaPhononCorrectedRelationCalculator.SIGMA_0_PRIMITIVE)
        # UQFF-corrected slope
        delta_alpha = beta_i * SCm * Phi_phonon * S26
        alpha_UQFF = alpha_classic * (1 + delta_alpha)
        # SMBH mass predictions
        sigma_ratio = sigma / sigma_0
        M_BH_classic = M_0 * sigma_ratio ** alpha_classic
        M_BH_UQFF = M_0 * sigma_ratio ** alpha_UQFF
        correction_factor = M_BH_UQFF / (M_BH_classic + 1e-300)
        # Buoyancy-modified Eddington momentum
        L_Edd = d.get('L_Edd', 1.26e38 * M_BH_UQFF / M_sun)
        v_outflow = d.get('v_outflow', 0.1 * c)
        p_dot_classic = L_Edd / c
        p_dot_UQFF = p_dot_classic * (1 - beta_i * S26 * Phi_phonon)
        # Feedback efficiency (R247 primitive-derived sigma_crit)
        sigma_crit = d.get('sigma_crit', MSigmaPhononCorrectedRelationCalculator.SIGMA_CRIT_PRIMITIVE)
        eta_feedback = 1.0 / (1.0 + (sigma_crit / sigma) ** 2 * beta_i * S26 * Phi_phonon)
        # Scatter reduction from phonon damping (R247 primitive-derived)
        scatter_classic = d.get('scatter_dex', MSigmaPhononCorrectedRelationCalculator.SCATTER_DEX_PRIMITIVE)
        scatter_UQFF = scatter_classic * (1 - 0.5 * delta_alpha)
        scatter_UQFF = max(scatter_UQFF, 0.05)
        # M_BH at multiple s values for curve
        sigma_points = [70e3, 100e3, 150e3, 200e3, 250e3, 350e3]
        M_curve_classic = [M_0 * (s / sigma_0) ** alpha_classic / M_sun for s in sigma_points]
        M_curve_UQFF = [M_0 * (s / sigma_0) ** alpha_UQFF / M_sun for s in sigma_points]
        return {
            'primary_equations': [
                f'a_UQFF = a�(1+�_i�SCm�F�S26) = {alpha_classic}�(1+{delta_alpha:.6f}) = {alpha_UQFF:.6f}',
                f'M_BH(s) = M0�(s/s0)^a_UQFF = {M_BH_UQFF/M_sun:.4e} M? (classic: {M_BH_classic/M_sun:.4e})',
                f'Correction factor: M_UQFF/M_classic = {correction_factor:.6f}',
                f'?_UQFF = (L_Edd/c)�(1-�_i�S26�F) = {p_dot_UQFF:.4e} N (buoyancy-damped)',
                f'?_feedback(s) = 1/(1+(s_c/s)���_i�S26�F) = {eta_feedback:.6f}',
                f'Scatter_UQFF = {scatter_UQFF:.3f} dex (classic: {scatter_classic:.3f} dex)',
            ],
            'available_equations': [
                'M-s power law (classic + UQFF)', 'Phonon-corrected slope a',
                'Eddington momentum (buoyancy-damped)', 'Feedback efficiency ?(s)',
                'Scatter reduction from phonon damping', 'Multi-s M_BH curve',
                'Bulge luminosity correlation', 'AGN outflow momentum ratio',
            ],
            'simulation_set': [
                {'name': 'SgrA_MW', 'sigma': 105e3, 'M_0': 1.66e8 * M_sun, 'alpha': 4.02},
                {'name': 'M87_Virgo', 'sigma': 375e3, 'M_0': 1.66e8 * M_sun, 'alpha': 4.02},
                {'name': 'NGC4889_Coma', 'sigma': 395e3, 'M_0': 1.66e8 * M_sun, 'alpha': 4.02},
                {'name': 'Low_sigma_dwarf', 'sigma': 50e3, 'M_0': 1.66e8 * M_sun, 'sigma_crit': 80e3},
            ],
            'values': {
                'alpha_classic': alpha_classic, 'alpha_UQFF': alpha_UQFF,
                'delta_alpha': delta_alpha, 'Phi_phonon': Phi_phonon, 'S26': S26,
                'M_BH_classic_Msun': M_BH_classic / M_sun,
                'M_BH_UQFF_Msun': M_BH_UQFF / M_sun,
                'correction_factor': correction_factor, 'eta_feedback': eta_feedback,
                'scatter_UQFF_dex': scatter_UQFF,
                'sigma_points_kms': [s / 1e3 for s in sigma_points],
                'M_curve_classic': M_curve_classic,
                'M_curve_UQFF': M_curve_UQFF,
            },
        }

