class Source10GPUDPMSpectralAtlasCalculator:
    """Vectorized 26-state DPM force-density spectral atlas with ALMA Cycle 12

    frequency targets.  Extends CR34 7-system atlas to full 26-dimensional

    state panorama with GPU-style batch evaluation and ALMA Band 3-10 overlay.

    Physics: f_density(state_i) = G�M�? / r� � S26??? � (f_DPM/f_ref)

    ALMA overlay: Band-matched a_THz per state at 84-950 GHz windows.

    Equations: 8 primary  |  Simulations: 4

    """

    R_PRIMITIVE = 10 ** 16
    RHO_PRIMITIVE = 0.1 ** 20
    F_DPM_PRIMITIVE = 10 ** 12
    F_REF_PRIMITIVE = 10 ** 12
    N_STATES_PRIMITIVE = 26
    T_DUST_PRIMITIVE = 3.0 * SO_5
    I_PROXY_PRIMITIVE = 10 ** 15
    B_PROXY_PRIMITIVE = 2.0 * (0.1 ** 5)
    T_KERNEL_US_PRIMITIVE = float((D_phys + 1) * SO_5)
    OPS_PER_STATE_PRIMITIVE = SO_5 + D_phys

    def compute(self, dataset: dict) -> dict:

        import math
        d = dataset if isinstance(dataset, dict) else {}
        G = _URP_G
        c = 2.998e8
        hbar = 1.055e-34
        k_B = 1.381e-23
        M = d.get('M', 1.989e30)
        r = d.get('r', Source10GPUDPMSpectralAtlasCalculator.R_PRIMITIVE)
        rho = d.get('rho', Source10GPUDPMSpectralAtlasCalculator.RHO_PRIMITIVE)
        f_DPM = d.get('f_DPM', Source10GPUDPMSpectralAtlasCalculator.F_DPM_PRIMITIVE)
        f_ref = d.get('f_ref', Source10GPUDPMSpectralAtlasCalculator.F_REF_PRIMITIVE)
        beta_i = d.get('beta_i', 0.6)
        SSq = d.get('SSq', 0.57)
        n_states = d.get('n_states', Source10GPUDPMSpectralAtlasCalculator.N_STATES_PRIMITIVE)
        T_dust = d.get('T_dust', Source10GPUDPMSpectralAtlasCalculator.T_DUST_PRIMITIVE)
        # DPM-seeded: mu_s x grad(M_s/r) base (Newtonian form is emergent, not foundational)
        g_base = G * M / (r * r + 1e-300)
        # 26-state S26 phonon weighting vector
        S26_vector = []
        for i in range(1, n_states + 1):
            S26_i = math.sin(math.pi * i / (n_states + 1)) ** 2
            S26_vector.append(S26_i)
        # DPM force density per state
        f_density = []
        for i, S26_i in enumerate(S26_vector):
            fd_i = g_base * rho * S26_i * (f_DPM / f_ref)
            f_density.append(fd_i)
        f_density_max = max(f_density)
        f_density_min = min(f for f in f_density if f > 0)
        xi_span = f_density_max / (f_density_min + 1e-300)
        # Compressed vs resonant channel per state
        a_compressed = []
        a_resonant = []
        for i, S26_i in enumerate(S26_vector):
            a_c = g_base * (1 + beta_i * S26_i * SSq)
            I_proxy = Source10GPUDPMSpectralAtlasCalculator.I_PROXY_PRIMITIVE
            B_proxy = Source10GPUDPMSpectralAtlasCalculator.B_PROXY_PRIMITIVE
            mu_0 = 4 * math.pi * 1e-7
            a_DPM_i = (mu_0 / (4 * math.pi)) * I_proxy * f_DPM / (r * r + 1e-300) * S26_i
            a_compressed.append(a_c)
            a_resonant.append(a_DPM_i)
        # ALMA Cycle 12 band overlay (GHz ? Hz)
        alma_bands = {
            'Band3': (84e9, 116e9),
            'Band4': (125e9, 163e9),
            'Band5': (163e9, 211e9),
            'Band6': (211e9, 275e9),
            'Band7': (275e9, 373e9),
            'Band8': (385e9, 500e9),
            'Band9': (602e9, 720e9),
            'Band10': (787e9, 950e9),
        }
        alma_a_THz = {}
        for band, (f_lo, f_hi) in alma_bands.items():
            f_mid = (f_lo + f_hi) / 2.0
            lam = c / f_mid
            a_THz = (k_B * T_dust / (hbar * f_mid + 1e-300)) * g_base * beta_i * SSq
            alma_a_THz[band] = {
                'f_mid_GHz': f_mid / 1e9,
                'lambda_mm': lam * 1e3,
                'a_THz': a_THz,
            }
        # Crossover state index (compressed � resonant)
        crossover_idx = 0
        min_ratio_diff = 1e30
        for i in range(n_states):
            ratio = abs(math.log10(a_compressed[i] / (a_resonant[i] + 1e-300) + 1e-300))
            if ratio < min_ratio_diff:
                min_ratio_diff = ratio
                crossover_idx = i + 1
        # Vectorized throughput estimate
        n_batch = d.get('n_batch', 1024)
        ops_per_state = Source10GPUDPMSpectralAtlasCalculator.OPS_PER_STATE_PRIMITIVE
        total_ops = n_states * n_batch * ops_per_state
        t_kernel_us = d.get('t_kernel_us', Source10GPUDPMSpectralAtlasCalculator.T_KERNEL_US_PRIMITIVE)
        throughput = n_batch / (t_kernel_us * 1e-6 + 1e-300)
        return {
            'primary_equations': [
                f'f_density(i) = G�M�?/r��S26???�(f_DPM/f_ref)  [{n_states} states]',
                f'f_density_max = {f_density_max:.4e} N/m� (state peak)',
                f'f_density_min = {f_density_min:.4e} N/m� (state floor)',
                f'?_span = f_max/f_min = {xi_span:.4e} (dynamic range)',
                f'Crossover state = {crossover_idx} (compressed � resonant)',
                f'ALMA Band6 a_THz = {alma_a_THz["Band6"]["a_THz"]:.4e} m/s� at {alma_a_THz["Band6"]["f_mid_GHz"]:.1f} GHz',
                f'Vectorized throughput = {throughput:.2e} systems/s (batch={n_batch})',
                f'g_base = {g_base:.4e} m/s�',
            ],
            'available_equations': [
                '26-state S26 phonon weighting vector',
                'DPM force density per state', '?_span dynamic range',
                'Compressed vs resonant per state', 'ALMA Band 3-10 a_THz overlay',
                'Channel crossover state index', 'GPU batch throughput estimate',
                'Spectral energy density SED per state',
            ],
            'simulation_set': [
                {'name': 'Orion_M42_atlas', 'M': 3.978e33, 'r': 1.18e17, 'rho': 1e-20, 'T_dust': 40},
                {'name': 'NGC6302_atlas', 'M': 3.978e30, 'r': 1.42e16, 'rho': 1e-20, 'T_dust': 25},
                {'name': 'Lagoon_M8_atlas', 'M': 1.989e34, 'r': 5.2e17, 'rho': 1e-21, 'T_dust': 35},
                {'name': 'Crab_PWN_atlas', 'M': 2.8e30, 'r': 1.65e16, 'rho': 1e-19, 'T_dust': 50},
            ],
            'values': {
                'S26_vector': S26_vector,
                'f_density': f_density,
                'a_compressed': a_compressed,
                'a_resonant': a_resonant,
                'alma_a_THz': alma_a_THz,
                'xi_span': xi_span,
                'crossover_state': crossover_idx,
                'throughput_per_s': throughput,
                'n_states': n_states,
            },
        }

class MUGEFUBiiUnifiedNineSystemSynthesisCalculator:
    """Unified 9-system F_U_Bi_i buoyancy multiplier synthesis table.

    Systems: NGC 6302, Orion M42, Lagoon M8, Saturn, Crab Nebula,

             Andromeda M31, Sombrero M104, Hydrogen atom, Observable Universe.

    Physics: ?_buoyancy(sys) = |F_U_Bi_i| / |F_grav|  ?  multiplier vs H-atom baseline.

    Cross-system buoyancy ratio table with S26�F�E_net modulation.

    Equations: 9 primary  |  Simulations: 3

    """

    def compute(self, dataset: dict) -> dict:

        import math
        d = dataset if isinstance(dataset, dict) else {}
        G = _URP_G
        c = 2.998e8
        beta_i = d.get('beta_i', 0.6)
        SSq = d.get('SSq', 0.57)
        kappa = d.get('kappa', 0.0005)
        # Canonical 9-system parameters
        systems = {
            'NGC_6302': {'M': 3.978e30, 'r': 1.42e16, 'rho': 1e-20, 'label': 'Bug Nebula PN'},
            'Orion_M42': {'M': 3.978e33, 'r': 1.18e17, 'rho': 1e-20, 'label': 'HII Trapezium'},
            'Lagoon_M8': {'M': 1.989e34, 'r': 5.2e17, 'rho': 1e-21, 'label': 'HII Herschel 36'},
            'Saturn': {'M': 5.683e26, 'r': 6.0268e7, 'rho': 687.0, 'label': 'Gas giant'},
            'Crab_Nebula': {'M': 2.8e30, 'r': 1.65e16, 'rho': 1e-19, 'label': 'PWN/SNR'},
            'Andromeda_M31': {'M': 2.5e42, 'r': 1.1e21, 'rho': 1e-25, 'label': 'Spiral galaxy'},
            'Sombrero_M104': {'M': 1.989e41, 'r': 2.36e20, 'rho': 1e-24, 'label': 'SA(s) galaxy'},
            'Hydrogen_atom': {'M': 1.673e-27, 'r': 5.292e-11, 'rho': 1.0e17, 'label': 'H ground state'},
            'Observable_Universe': {'M': 1.5e53, 'r': 4.4e26, 'rho': 9.9e-27, 'label': 'Hubble volume'},
        }
        # Override any system parameters from dataset
        for key in systems:
            if key in d and isinstance(d[key], dict):
                systems[key].update(d[key])
        # Compute F_U_Bi_i and F_grav for each system
        results = {}
        for name, params in systems.items():
            M = params['M']
            r = params['r']
            rho = params['rho']
            # DPM-seeded: mu_s x grad(M_s/r) base (Newtonian form is emergent, not foundational)
            g_base = G * M / (r * r + 1e-300)
            V_sys = (4.0 / 3.0) * math.pi * r ** 3
            F_grav = g_base * M
            # Buoyancy force: F_U_Bi_i = ?�V�g_base � �_i�S26�[SSq]
            S26_eff = math.sin(math.pi * 13 / 27) ** 2
            F_U_Bi_i = rho * V_sys * g_base * beta_i * S26_eff * SSq
            eta = F_U_Bi_i / (F_grav + 1e-300)
            results[name] = {
                'g_base': g_base, 'F_grav': F_grav,
                'F_U_Bi_i': F_U_Bi_i, 'eta': eta,
                'V_sys': V_sys, 'label': params['label'],
            }
        # Normalise to Hydrogen baseline
        eta_H = results['Hydrogen_atom']['eta']
        multiplier_table = {}
        for name, res in results.items():
            multiplier_table[name] = res['eta'] / (eta_H + 1e-300)
        # Rank systems by buoyancy dominance
        ranked = sorted(results.items(), key=lambda x: x[1]['eta'], reverse=True)
        rank_names = [r[0] for r in ranked]
        # Positive vs negative E(t) classification
        positive_Enet = []
        negative_Enet = []
        for name, res in results.items():
            if res['eta'] > 1.0:
                positive_Enet.append(name)
            else:
                negative_Enet.append(name)
        primary_eqs = []
        for name, res in results.items():
            m = multiplier_table[name]
            primary_eqs.append(
                f'?({name}) = |F_U_Bi_i|/|F_grav| = {res["eta"]:.4e}  ?  {m:.4e}� H-baseline  [{res["label"]}]'
            )
        return {
            'primary_equations': primary_eqs,
            'available_equations': [
                'F_U_Bi_i per system', '? buoyancy ratio',
                'Hydrogen-normalised multiplier table',
                'System ranking by buoyancy dominance',
                'Positive/negative E(t) partition',
                'Cross-system ? ratio matrix',
                'V_sys volume comparison', 'g_base gravity ladder',
                'Astrophysical class taxonomy',
            ],
            'simulation_set': [
                {'name': 'Nebular_trio', 'systems': ['NGC_6302', 'Orion_M42', 'Lagoon_M8']},
                {'name': 'Galaxy_pair', 'systems': ['Andromeda_M31', 'Sombrero_M104']},
                {'name': 'Extremes', 'systems': ['Hydrogen_atom', 'Observable_Universe', 'Crab_Nebula']},
            ],
            'values': {
                'multiplier_table': multiplier_table,
                'rank_order': rank_names,
                'positive_Enet_systems': positive_Enet,
                'negative_Enet_systems': negative_Enet,
                'system_results': {
                    name: {
                        'g_base': res['g_base'], 'F_grav': res['F_grav'],
                        'F_U_Bi_i': res['F_U_Bi_i'], 'eta': res['eta'],
                    } for name, res in results.items()
                },
            },
        }

class UniversalDualitySCmUASynthesisTheoremCalculator:
    """Universal SCm-UA duality synthesis theorem: every gravitational system

    admits a complementary phonon-condensate (SCm) description and a

    vacuum-aether (UA) description that are dual under buoyancy sign inversion.

    Core theorem: F_U_Bi_i = F_SCm(inside?outside) + F_UA(outside?inside)

    with |F_SCm| + |F_UA| = |F_total|   and   sign(E_net) = sign(F_SCm - F_UA).

    Positive E(t) ? expansion-dominated (nebulae, Universe).

    Negative E(t) ? collapse-dominated (compact objects, BHs).

    Neutral E(t=0) ? equilibrium (stable orbits, rings).

    Equations: 7 primary  |  Simulations: 5

    """

    KAPPA_PRIMITIVE = (D_phys + 1) * (0.1 ** 4)
    R_PRIMITIVE = 10 ** 16
    RHO_PRIMITIVE = 0.1 ** 20
    T_AGE_YR_PRIMITIVE = 10 ** 6
    T_N_PRIMITIVE = 1.0 / (D_phys - 2)
    U_UA_PRIMITIVE = 0.1 ** 4
    RHO_VAC_PRIMITIVE = D_BSFG * (0.1 ** 27)

    def compute(self, dataset: dict) -> dict:

        import math
        d = dataset if isinstance(dataset, dict) else {}
        G = _URP_G
        c = 2.998e8
        hbar = 1.055e-34
        beta_i = d.get('beta_i', 0.6)
        SSq = d.get('SSq', 0.57)
        kappa = d.get('kappa', UniversalDualitySCmUASynthesisTheoremCalculator.KAPPA_PRIMITIVE)
        M = d.get('M', 1.989e30)
        r = d.get('r', UniversalDualitySCmUASynthesisTheoremCalculator.R_PRIMITIVE)
        rho = d.get('rho', UniversalDualitySCmUASynthesisTheoremCalculator.RHO_PRIMITIVE)
        t_age_yr = d.get('t_age_yr', UniversalDualitySCmUASynthesisTheoremCalculator.T_AGE_YR_PRIMITIVE)
        t_n = d.get('t_n', UniversalDualitySCmUASynthesisTheoremCalculator.T_N_PRIMITIVE)
        # DPM-seeded: mu_s x grad(M_s/r) base (Newtonian form is emergent, not foundational)
        g_base = G * M / (r * r + 1e-300)
        V_sys = (4.0 / 3.0) * math.pi * r ** 3
        # SCm phonon condensate contribution (inside?outside)
        S26_eff = math.sin(math.pi * 13 / 27) ** 2
        Phi_phonon = math.cos(math.pi * t_n)
        omega_SCm = 2 * math.pi * 1.25e12
