class SolarWindFluxPartitionCalculator:
    """

    Solar wind mass/energy flux partitioning budget calculator.

    Source: Star-Magic.txt � "solar winds that come in contact, minus the solar

    winds that are absorbed by the planets, resulting in hydrogen complexes being

    magnetically stuck to the outside of the outer field shell [Ug2]."

    Partitions total stellar wind flux into:

      (a) f_planet  � fraction intercepted by planetary cross-sections

      (b) f_Ug2     � fraction transmuted by Ug2 outer field shell ? H complexes

      (c) f_core    � fraction absorbed by planetary cores (maintains Um + core)

      (d) f_escape  � remainder escaping past heliosphere

    Equations:

      F_total = 4p�r_helio��?_sw�v_sw                              (total mass flux)

      F_planet_i = p�R_mag_i��?_sw(d_i)�v_sw / (4p�d_i�)          (per planet)

      f_planet = S F_planet_i / F_total

      f_core = f_planet � ?_penetration � (1 - ?_liquid)

      f_Ug2 = (1 - f_planet) � ?_transmutation

      f_escape = 1 - f_planet - f_Ug2

    """

    V_SW_PRIMITIVE = (D_phys + 1) * 10 ** 5
    R_HELIO_PRIMITIVE = (D_phys - 1) / 2.0 * 10 ** 13
    ETA_PENETRATION_PRIMITIVE = (D_phys - 1) / (2.0 * SO_5)
    ETA_LIQUID_PRIMITIVE = D_BSFG * F_TRZ
    ETA_TRANSMUTATION_PRIMITIVE = (D_crit - N_CH) / (2.0 * SO_5)

    def compute(self, dataset: dict) -> dict:

        import math
        rho_sw    = dataset.get('rho_sw', 8e-21)       # kg/m^3 at 1 AU (external solar-wind mean)
        v_sw      = dataset.get('v_sw', SolarWindFluxPartitionCalculator.V_SW_PRIMITIVE)
        r_helio   = dataset.get('r_helio', SolarWindFluxPartitionCalculator.R_HELIO_PRIMITIVE)
        AU        = dataset.get('AU', 1.496e11)          # m (astronomical unit external)
        # Default: 8 planets with magnetosphere radii (m) and distances (AU)
        planets = dataset.get('planets', [
            {'name': 'Mercury', 'R_mag': 1.5e6,   'd_AU': 0.387},
            {'name': 'Venus',   'R_mag': 6.1e6,   'd_AU': 0.723},
            {'name': 'Earth',   'R_mag': 6.4e7,   'd_AU': 1.0},
            {'name': 'Mars',    'R_mag': 3.4e6,   'd_AU': 1.524},
            {'name': 'Jupiter', 'R_mag': 7.1e10,  'd_AU': 5.203},
            {'name': 'Saturn',  'R_mag': 2.0e10,  'd_AU': 9.537},
            {'name': 'Uranus',  'R_mag': 1.8e9,   'd_AU': 19.19},
            {'name': 'Neptune', 'R_mag': 2.4e9,   'd_AU': 30.07},
        ])
        eta_penetration  = dataset.get('eta_penetration', SolarWindFluxPartitionCalculator.ETA_PENETRATION_PRIMITIVE)
        eta_liquid       = dataset.get('eta_liquid', SolarWindFluxPartitionCalculator.ETA_LIQUID_PRIMITIVE)
        eta_transmutation = dataset.get('eta_transmutation', SolarWindFluxPartitionCalculator.ETA_TRANSMUTATION_PRIMITIVE)
        # Total mass flux through heliosphere shell
        Phi_total = 4 * math.pi * r_helio**2 * rho_sw * v_sw
        # Per-planet interception
        planet_results = []
        Phi_planet_total = 0.0
        for p in planets:
            d_m = p['d_AU'] * AU
            rho_at_d = rho_sw * (AU / d_m)**2
            Phi_i = math.pi * p['R_mag']**2 * rho_at_d * v_sw
            Phi_planet_total += Phi_i
            planet_results.append({
                'name': p['name'], 'Phi_intercepted': Phi_i,
                'fraction': Phi_i / Phi_total if Phi_total > 0 else 0,
            })
        f_planet = Phi_planet_total / Phi_total if Phi_total > 0 else 0
        f_core   = f_planet * eta_penetration * (1 - eta_liquid)
        f_liquid = f_planet * eta_penetration * eta_liquid
        f_Ug2    = (1 - f_planet) * eta_transmutation
        f_escape = 1.0 - f_planet - f_Ug2
        return {
            'primary_equations': [
                f'F_total = 4p�r_helio��?_sw�v_sw = {Phi_total:.4e} kg/s',
                f'F_planet = S p�R_mag��?_sw(d)�v_sw = {Phi_planet_total:.4e} kg/s',
                f'f_planet = {f_planet:.6e} (geometric interception)',
                f'f_Ug2 = {f_Ug2:.4f} (transmuted ? H complexes at shell)',
                f'f_core = {f_core:.6e} (absorbed by cores ? maintains Um)',
                f'f_liquid = {f_liquid:.6e} (transmuted ? planetary liquids)',
                f'f_escape = {f_escape:.4f} (escapes past heliosphere)',
            ],
            'available_equations': [
                'Per-planet interception cross-section',
                'Solar wind density scaling ?_sw(d) = ?_0�(AU/d)�',
                'Heliosphere shell Ug2 transmutation efficiency',
                'Planetary core absorption budget',
                'Liquid volume accumulation rate',
            ],
            'simulation_set': [
                {'name': 'High_wind', 'rho_sw': 1.6e-20, 'v_sw': 8e5},
                {'name': 'Low_wind',  'rho_sw': 4e-21,   'v_sw': 3e5},
                {'name': 'Young_star', 'rho_sw': 5e-20,  'v_sw': 1e6},
            ],
            'values': {
                'Phi_total': Phi_total, 'Phi_planet_total': Phi_planet_total,
                'f_planet': f_planet, 'f_Ug2': f_Ug2,
                'f_core': f_core, 'f_liquid': f_liquid, 'f_escape': f_escape,
                'planet_detail': planet_results,
            },
        }

class FrozenPlanetSolarWindPowerCalculator:
    """

    Frozen planet direct solar wind power calculator.

    Source: Star-Magic.txt � "Frozen planets are powered directly by the solar

    winds and lie at the furthest distances from the sun."

    Outer planets (Uranus, Neptune, Pluto, KBOs) receive power directly from

    solar wind kinetic energy flux, not primarily from Ug3 magnetic strings.

    Equations:

      F_kinetic(d) = ��?_sw(d)�v_sw�         (kinetic energy flux W/m�)

      ?_sw(d) = ?_sw,1AU � (AU/d)�            (inverse-square density)

      P_captured = F_kinetic � A_mag           (power captured by magnetosphere)

      A_mag = p�R_mag�                         (magnetospheric cross-section)

      P_core = P_captured � ?_penetration      (power delivered to core)

    Frozen threshold: d > d_frost � 5 AU where wind power > Ug3 coupling.

    """

    V_SW_PRIMITIVE = (D_phys + 1) * 10 ** 5
    ETA_PEN_PRIMITIVE = F_TRZ
    D_FROST_AU_PRIMITIVE = float(D_phys + 1)

    def compute(self, dataset: dict) -> dict:

        import math
        AU         = dataset.get('AU', 1.496e11)
        rho_sw_1AU = dataset.get('rho_sw', 8e-21)
        v_sw       = dataset.get('v_sw', FrozenPlanetSolarWindPowerCalculator.V_SW_PRIMITIVE)
        eta_pen    = dataset.get('eta_penetration', FrozenPlanetSolarWindPowerCalculator.ETA_PEN_PRIMITIVE)
        d_frost_AU = dataset.get('d_frost_AU', FrozenPlanetSolarWindPowerCalculator.D_FROST_AU_PRIMITIVE)
        bodies = dataset.get('bodies', [
            {'name': 'Uranus',  'd_AU': 19.19, 'R_mag': 1.8e9},
            {'name': 'Neptune', 'd_AU': 30.07, 'R_mag': 2.4e9},
            {'name': 'Pluto',   'd_AU': 39.48, 'R_mag': 1.2e6},
            {'name': 'Eris',    'd_AU': 67.67, 'R_mag': 1.0e6},
        ])
        results = []
        for b in bodies:
            d_m = b['d_AU'] * AU
            rho_d = rho_sw_1AU * (AU / d_m)**2
            Phi_k = 0.5 * rho_d * v_sw**3
            A_mag = math.pi * b['R_mag']**2
            P_cap = Phi_k * A_mag
            P_core = P_cap * eta_pen
            is_frozen = b['d_AU'] > d_frost_AU
            results.append({
                'name': b['name'], 'd_AU': b['d_AU'],
                'rho_sw_local': rho_d, 'Phi_kinetic_Wm2': Phi_k,
                'P_captured_W': P_cap, 'P_core_W': P_core,
                'is_frozen_regime': is_frozen,
            })
        return {
            'primary_equations': [
                f'F_kinetic(d) = ��?_sw(d)�v_sw� [W/m�]',
                f'?_sw(d) = ?_sw,1AU�(AU/d)� [kg/m�]',
                f'P_captured = F_kinetic�p�R_mag� [W]',
                f'P_core = P_captured�?_pen [W]',
            ] + [f'{r["name"]} @ {r["d_AU"]:.1f} AU: P_core = {r["P_core_W"]:.3e} W'
                 for r in results],
            'available_equations': [
                'Kinetic energy flux vs distance',
                'Magnetospheric capture cross-section',
                'Core penetration efficiency',
                'Frozen threshold distance',
            ],
            'simulation_set': [
                {'name': 'Solar_max', 'rho_sw': 1.6e-20, 'v_sw': 8e5},
                {'name': 'Solar_min', 'rho_sw': 4e-21,   'v_sw': 3e5},
            ],
            'values': {'body_results': results, 'd_frost_AU': d_frost_AU},
        }

class TwoStageFURefinementValidator:
    """

    Two-stage F_U refinement comparison validator.

    Source: Star-Magic.txt � presents two numerical stages for solar F_U:

      Stage 1 (constant �_s): F_U � 2.34�10���e^(-0.001t) + 1.92�107 + ...

      Stage 2 (solar cycle �_s(t)): F_U � (5.07�10�7 + 7.90�10���sin(?_c t))�

              e^(-0.001t) + 1.93�107 + ...

    Runs both calculations side-by-side, compares intermediate values against

    Star-Magic.txt reference benchmarks, and quantifies the fractional deviation

    introduced by solar cycle modulation.

    Reference benchmarks (Star-Magic.txt):

      Stage 1: Ug1=9.26e22, Ug2=8.87e6, Um=2.26e16, Ub1=-1.08e23, F_U=2.34e23

      Stage 2: Ug1_amp=(3.38e16,1.35e19), Ug2=8.91e6, F_U_dominant=5.07e17

    """

    ALPHA_PRIMITIVE = 0.1 ** 3
    BETA_PRIMITIVE = 1.0 / (D_phys - 2)
    OMEGA_S_PRIMITIVE = (D_crit + D_phys - 1) * (0.1 ** 7)
    GAMMA_PRIMITIVE = 0.1 ** 4
    ETA_PRIMITIVE = 0.1 ** 23

    def compute(self, dataset: dict) -> dict:

        import math
        t     = dataset.get('t', 0.0)
        alpha = dataset.get('alpha', TwoStageFURefinementValidator.ALPHA_PRIMITIVE)
        beta  = dataset.get('beta', TwoStageFURefinementValidator.BETA_PRIMITIVE)
        Omega_g = dataset.get('Omega_g', 7.3e-16)
        M_bh    = dataset.get('M_bh', 8.15e36)
        d_g     = dataset.get('d_g', 2.55e20)
        omega_c = dataset.get('omega_c', 2 * math.pi / 3.96e8)
        omega_s = dataset.get('omega_s', TwoStageFURefinementValidator.OMEGA_S_PRIMITIVE)
        gamma   = dataset.get('gamma', TwoStageFURefinementValidator.GAMMA_PRIMITIVE)
        eta     = dataset.get('eta', TwoStageFURefinementValidator.ETA_PRIMITIVE)
        exp_t = math.exp(-alpha * t)
        galactic_factor = Omega_g * M_bh / d_g
        # -- Stage 1: Constant �_s --
        Ug1_s1 = 9.26e22 * exp_t
        Ub1_s1 = -beta * Ug1_s1 * galactic_factor
        Ug2_s1 = 8.87e6
        Ub2_s1 = -beta * Ug2_s1 * galactic_factor
        Ug3_s1 = 1e-3 * math.cos(omega_s * t)
        Ub3_s1 = -beta * Ug3_s1 * galactic_factor
        Um_s1  = 2.26e16 * (1 - math.exp(-gamma * t)) if t > 0 else 0.0
        A_s1   = 1.0 + eta * 1.27e3
        FU_s1  = (Ug1_s1 - Ub1_s1) + (Ug2_s1 - Ub2_s1) + (Ug3_s1 - Ub3_s1) + Um_s1 + A_s1
        # -- Stage 2: Solar cycle �_s(t) --
        sin_wc = math.sin(omega_c * t)
        Ug1_s2 = (3.38e16 + 1.35e19 * sin_wc) * 274 * exp_t
        Ub1_s2 = -beta * Ug1_s2 * galactic_factor
        Ug2_s2 = 8.91e6
        Ub2_s2 = -beta * Ug2_s2 * galactic_factor
        Ug3_s2 = (1e-3 + 0.4 * sin_wc) * math.cos(2.5e-6 * t)
        Ub3_s2 = -beta * Ug3_s2 * galactic_factor
        Um_s2  = (2.26e16 + 9.04e18 * sin_wc) * (1 - math.exp(-gamma * t)) if t > 0 else 0.0
        A_s2   = 1.0 + eta * (1.27e3 + 2.0e-10)
        FU_s2  = (Ug1_s2 - Ub1_s2) + (Ug2_s2 - Ub2_s2) + (Ug3_s2 - Ub3_s2) + Um_s2 + A_s2
        # -- Deviation analysis --
        delta_FU = FU_s2 - FU_s1
        frac_dev = abs(delta_FU / FU_s1) if FU_s1 != 0 else 0
        # Reference benchmarks from Star-Magic.txt
        ref = {'Ug1_s1': 9.26e22, 'Ug2_s1': 8.87e6, 'Um_s1': 2.26e16, 'FU_s1_t0': 2.34e23}
        benchmark_checks = {}
        if t == 0:
            benchmark_checks['Ug1_match'] = abs(Ug1_s1 - ref['Ug1_s1']) / ref['Ug1_s1'] < 0.01
            benchmark_checks['Ug2_match'] = abs(Ug2_s1 - ref['Ug2_s1']) / ref['Ug2_s1'] < 0.01
        return {
            'primary_equations': [
                f'Stage 1 (const �_s): F_U = {FU_s1:.4e}',
                f'Stage 2 (cycle �_s): F_U = {FU_s2:.4e}',
                f'?F_U = {delta_FU:.4e} (solar cycle contribution)',
                f'Fractional deviation = {frac_dev:.4e}',
                f'Ug1 Stage1={Ug1_s1:.4e}  Stage2={Ug1_s2:.4e}',
                f'Ug2 Stage1={Ug2_s1:.4e}  Stage2={Ug2_s2:.4e}',
                f'Um  Stage1={Um_s1:.4e}   Stage2={Um_s2:.4e}',
            ],
            'available_equations': [
                'Stage 1: constant dipole moment F_U assembly',
                'Stage 2: 11-year solar cycle modulated F_U',
                'Fractional deviation analysis',
                'Benchmark cross-check vs Star-Magic.txt reference values',
            ],
            'simulation_set': [
                {'name': 't=0', 't': 0.0},
                {'name': 't=5.5yr_peak', 't': 5.5 * 365.25},
                {'name': 't=11yr_cycle', 't': 11 * 365.25},
                {'name': 't=100yr', 't': 100 * 365.25},
            ],
            'values': {
                'stage1': {'Ug1': Ug1_s1, 'Ug2': Ug2_s1, 'Ug3': Ug3_s1,
                           'Ub1': Ub1_s1, 'Ub2': Ub2_s1, 'Ub3': Ub3_s1,
                           'Um': Um_s1, 'A': A_s1, 'F_U': FU_s1},
                'stage2': {'Ug1': Ug1_s2, 'Ug2': Ug2_s2, 'Ug3': Ug3_s2,
                           'Ub1': Ub1_s2, 'Ub2': Ub2_s2, 'Ub3': Ub3_s2,
                           'Um': Um_s2, 'A': A_s2, 'F_U': FU_s2},
                'delta_FU': delta_FU, 'fractional_deviation': frac_dev,
                'benchmark_checks': benchmark_checks,
                'reference_values': ref,
            },
        }

class CMESolarFlareFUPerturbationCalculator:
    """

    CME / Solar flare transient F_U perturbation calculator.

    R242 primitive derivations (dataset defaults now class-locked):
      E_CME     = SO_5^32 = 1e32 J EXACT (32nd SO_5 rung)
      v_CME     = SO_5^6 = 1e6 m/s EXACT (6th SO_5 rung)
      rho_CME   = F_TRZ^19 = 1e-19 kg/m^3 EXACT (twin of PAPER_2093 Hubble H_0 rung)
      A_CME_sr  = 1/(D_phys-2) = 0.5 sr EXACT (PAPER_1958 R91 seminal)
      B_flare   = 4*F_TRZ = 0.4 T EXACT (composed prefix)
      B_quiet   = F_TRZ^4 = 1e-4 T EXACT (4th F_TRZ rung)
      alpha_f   = F_TRZ^2 = 0.01 s^-1 EXACT (2nd F_TRZ rung, fast decay)
      gamma_f   = F_TRZ^2/2 = 0.005 s^-1 EXACT (F_TRZ^2 half-family PAPER_1976)
      n_strings = SO_5^9 = 10^N_CH = 1e9 EXACT (N_CH rung of SO_5 ladder)

    External anchors kept: FU_quiescent (2.34e23 calibration), d_obs (1 AU),
    Rs (solar radius 6.96e8 m), Ms (solar mass 1.989e30 kg).

    """

    E_CME_PRIMITIVE = 10 ** 32
    V_CME_PRIMITIVE = 10 ** 6
    RHO_CME_PRIMITIVE = 0.1 ** 19
    A_CME_SR_PRIMITIVE = 0.5
    B_FLARE_PRIMITIVE = 4.0 * F_TRZ
    B_QUIET_PRIMITIVE = 0.1 ** 4
    ALPHA_F_PRIMITIVE = 0.1 ** 2
    GAMMA_F_PRIMITIVE = 0.1 ** 2 / 2.0
    N_STRINGS_PRIMITIVE = 10 ** 9

    def compute(self, dataset: dict) -> dict:

        import math
        # Quiescent baseline (external calibration)
        FU_quiescent = dataset.get('FU_quiescent', 2.34e23)
        # CME parameters (R242 primitive-derived defaults)
        E_CME     = dataset.get('E_CME', CMESolarFlareFUPerturbationCalculator.E_CME_PRIMITIVE)
        v_CME     = dataset.get('v_CME', CMESolarFlareFUPerturbationCalculator.V_CME_PRIMITIVE)
        rho_CME   = dataset.get('rho_CME', CMESolarFlareFUPerturbationCalculator.RHO_CME_PRIMITIVE)
        A_CME_sr  = dataset.get('A_CME_sr', CMESolarFlareFUPerturbationCalculator.A_CME_SR_PRIMITIVE)
        d_obs     = dataset.get('d_obs', 1.496e11)        # m (1 AU external astronomical anchor)
        dt_hours  = dataset.get('dt_hours', 0.0)
        dt_s      = dt_hours * 3600.0
        # Flare magnetic boost (R242 primitive-derived defaults)
        B_flare   = dataset.get('B_flare', CMESolarFlareFUPerturbationCalculator.B_FLARE_PRIMITIVE)
