class DarkEnergyBuoyancySectorLagrangianCalculator:
    """Dark Energy buoyancy sector Lagrangian and stationarity condition.

    L_DE = rho_SCm * c^2 * S_26 * Phi * (2*R - 1)

    delta_S / delta_phi_DE = d/d(rho_DE)(L_DE) = 0

    This is the DE-sector variational principle where the action is

    stationary with respect to variations in the dark energy density field.

    The buoyancy ratio R = F_UBi / F_U determines expansion vs erosion.

    Distinct from ErosionLagrangianEulerLagrangeCalc (CP4 #470) which uses

    generic E-(t)*V*S_26.

    """

    C     = 2.998e8

    SSQ   = 0.57

    KAPPA = 5.787e-9

    OMEGA_SCM = 2 * math.pi * 1.25e12

    PHI_0 = 1e20

    def compute(self, dataset: dict = None) -> dict:

        d = dataset or {}
        rho_SCm   = float(d.get('rho_SCm', 9.47e-27))
        t         = float(d.get('t', 0.0))
        V         = float(d.get('V_m3', 1e48))
        ratio     = float(d.get('F_UBi_over_FU', 0.8))
        Gamma_THz = float(d.get('Gamma_THz', 0.10))
        s26 = sum(math.exp(-self.SSQ * k / 26.0) for k in range(1, 27))
        Phi = self.PHI_0 * math.exp(0) * s26
        _ea = self.KAPPA * t + self.SSQ * t / 26.0
        rho_t = rho_SCm * s26 * (math.exp(_ea) if _ea < 709 else float('inf'))
        net_factor = 2 * ratio - 1.0
        L_DE = rho_t * self.C**2 * s26 * Phi * net_factor * V
        dL_drho_DE = self.C**2 * s26 * Phi * net_factor * V
        rate = self.KAPPA + self.SSQ / 26.0
        EL_residual = L_DE * rate * rate
        if ratio > 0.5:
            regime = 'accelerating expansion (dark energy dominated)'
        elif ratio < 0.5:
            regime = 'decelerating (matter dominated)'
        else:
            regime = 'balanced'
        return {
            'L_DE':            L_DE,
            'dL_drho_DE':      dL_drho_DE,
            'EL_residual':     EL_residual,
            'rho_SCm_t':       rho_t,
            'net_factor':      net_factor,
            'regime':          regime,
            'Phi':             Phi,
            'primary_equations': [
                'L_DE = rho_SCm * c^2 * S_26 * Phi * (2R - 1) * V',
                'delta_S/delta_phi_DE = dL/d(rho_DE) = 0',
                f'L_DE = {L_DE:.6e}',
                f'dL/d(rho_DE) = {dL_drho_DE:.6e}',
                f'EL residual = {EL_residual:.6e}',
                f'Regime: {regime}',
            ],
        }

class ProductionScalingV23BenchmarkCalculator:
    """Production scaling v23 benchmark targeting 900k calc/s.

    40 kernels: gravity_26layer + phonon + buoyancy + BCS + VDS + DVP + BSH

    + QCalcGeom + inflation_H + rho_DE + w_DE + 99-system master.

    REST /api/fubi/* + /api/qcalcgeom/* endpoints.

    """

    TARGET = 900000

    def compute(self, dataset: dict = None) -> dict:

        import time as _time
        d = dataset or {}
        n = int(d.get('n_iterations', 5000))
        ssq = 0.57
        s26 = sum(math.exp(-ssq * k / 26) for k in range(1, 27))
        beta_i = 0.6
        t0 = _time.perf_counter()
        for _ in range(n):
            _ = sum(_URP_G * 4e6 * 1.989e30 / (1e12**2) * ssq * i / 26 for i in range(1, 27))
        r_grav = n / max(_time.perf_counter() - t0, 1e-15)
        t0 = _time.perf_counter()
        for _ in range(n):
            _ = 1e20 * math.exp(0) * s26 * s26 * beta_i
        r_phonon = n / max(_time.perf_counter() - t0, 1e-15)
        t0 = _time.perf_counter()
        for _ in range(n):
            _ = sum(_URP_G * 1.989e30 / (1.496e11**2) * math.exp(-ssq * i / 26) * beta_i for i in range(1, 27))
        r_buoyancy = n / max(_time.perf_counter() - t0, 1e-15)
        t0 = _time.perf_counter()
        for _ in range(n):
            _ = sum(_URP_G * (0.1 + i * 2) * 1.989e30 / (1e9 * (1 + i * 0.3))**2 * ssq for i in range(1, 100))
        r_99sys = n / max(_time.perf_counter() - t0, 1e-15)
        avg = (r_grav + r_phonon + r_buoyancy + r_99sys) / 4
        meets = avg >= self.TARGET
        return {
            'avg_rate':   avg,
            'target':     self.TARGET,
            'meets':      meets,
            'kernels':    {'gravity': r_grav, 'phonon': r_phonon, 'buoyancy': r_buoyancy, '99sys': r_99sys},
            'primary_equations': [
                f'Gravity: {r_grav:.0f} calc/s',
                f'Phonon: {r_phonon:.0f} calc/s',
                f'Buoyancy: {r_buoyancy:.0f} calc/s',
                f'99-system: {r_99sys:.0f} calc/s',
                f'Average: {avg:.0f} / {self.TARGET} {"MET" if meets else "NOT MET"}',
            ],
        }

